INSERT INTO `mdl_customfield_field` (`id`, `shortname`, `name`, `type`, `description`, `descriptionformat`, `sortorder`, `categoryid`, `configdata`, `timecreated`, `timemodified`) VALUES
(1, 'edwcourseduration', 'Course Duration', 'text', NULL, 0, 0, 1, '{\"required\":0,\"uniquevalues\":0,\"locked\":0,\"visibility\":2,\"defaultvalue\":\"\",\"displaysize\":50,\"maxlength\":1333,\"ispassword\":0}', 1758085459, 1758085459),
(2, 'edwcourseintrovideourlembedded', 'Course Intro Video Url (Embedded)', 'text', NULL, 0, 1, 1, '{\"required\":0,\"uniquevalues\":0,\"locked\":0,\"visibility\":2,\"defaultvalue\":\"\",\"displaysize\":50,\"maxlength\":1333,\"ispassword\":0}', 1758085459, 1758085459),
(3, 'edwskilllevel', 'Skill Level', 'select', NULL, 0, 2, 1, '{\"required\":0,\"uniquevalues\":0,\"locked\":0,\"visibility\":2,\"options\":\"Beginner\\n Intermediate\\n Advanced\",\"defaultvalue\":\"Beginner\"}', 1758085459, 1758085459),
(4, 'edwfocusmode', 'Focus Mode', 'select', '<div class=\'overflow-hidden\' style=\'padding: 12px; border-radius: 6px; border: 1px solid #FFC107; background: #FFF9E5;\'>\n                    <p class=\'m-0\' style=\'font-size: 14px;\'>\n                        <strong>Default:</strong> Uses the Focus Mode setting defined by the site admin.\n                    </p>\n                    <p class=\'m-0 mt-2\' style=\'font-size: 14px;\'>\n                        <strong>Force Focus Mode (with learner control): </strong> This option lets you keep Focus Mode active for your course. Learners will see the course in Focus Mode by default, but they can choose to turn it off anytime. This applies only to learners.\n                    </p>\n                    <p class=\'m-0 mt-2\' style=\'font-size: 14px;\'>\n                        <strong>Note:</strong> If the site admin has either <strong>disabled</strong> or <strong>enforced</strong> Focus Mode across the site, the settings here won’t apply.\n                    </p>\n                </div>', 1, 3, 1, '{\"required\":0,\"uniquevalues\":0,\"locked\":0,\"visibility\":2,\"options\":\"Force Focus Mode with learner control\",\"defaultvalue\":\"Default\"}', 1758177487, 1758177487);
