th: 47.964px;height: 47.964px;}}\",\"js\":\"document.addEventListener(\\\"DOMContentLoaded\\\",function(){new class e{constructor(){this.testimonial=document.querySelector(\\\".edw_testimonial[[inst]]\\\"),this.carousel=this.testimonial.querySelector(\\\"#testimonial-carousel-5[[inst]]\\\"),this.readMoreBtn=this.testimonial.querySelectorAll(\\\".content-box .readMoreBtn\\\"),this.readLessBtn=this.testimonial.querySelectorAll(\\\".content-box .readLessBtn\\\"),this.readMoreTrigger=this.readMoreTrigger.bind(this),this.readLessTrigger=this.readLessTrigger.bind(this),this.initializeEventListeners()}initializeEventListeners(){this.readMoreBtn.forEach(e=>{e.addEventListener(\\\"click\\\",this.readMoreTrigger)}),this.readLessBtn.forEach(e=>{e.addEventListener(\\\"click\\\",this.readLessTrigger)})}readMoreTrigger(e){let t=e.target,i=t.nextElementSibling;t.parentNode.classList.remove(\\\"ellipsis\\\"),t.style.display=\\\"none\\\",i.style.display=\\\"inline\\\"}readLessTrigger(e){let t=e.target,i=t.previousElementSibling;i.parentNode.classList.add(\\\"ellipsis\\\"),i.style.display=\\\"inline\\\",t.style.display=\\\"none\\\"}}});\"}]', 2021071445, 0, 1, 'blocklayout', 'Homepages');
INSERT INTO `mdl_edw_page_blocks` (`id`, `title`, `label`, `thumbnail`, `content`, `version`, `updateavailable`, `visible`, `type`, `categories`) VALUES
(28, 'blocklayout5', 'School 2', 'https://staticcdn.edwiser.org/demoimporter/homepage/school2.jpeg', '[{\"html\":\"<div class=\\\"bg-white w-100 position-relative\\\">\\r\\n    <div class=\\\"section\\\" style=\\\"background-image:url(https:\\/\\/staticcdn.edwiser.org\\/demo\\/school\\/student.png);\\\">\\r\\n        <div class=\\\"background-overlay\\\"><\\/div>\\r\\n        <div class=\\\"container-fluid px-0\\\">\\r\\n            <div class=\\\"inner-content-wrap\\\">\\r\\n                <div class=\\\"inner-content\\\">\\r\\n                    <div class=\\\"row d-lg-none d-md-none d-sm-block\\\">\\r\\n                        <!-- Visible on only small devices -->\\r\\n                        <div class=\\\"element\\\">\\r\\n                            <img src=\\\"{{>cdnurl}}blocklayout5\\/images\\/mny.png\\\" class=\\\"img-fluid\\\">\\r\\n                        <\\/div>\\r\\n                    <\\/div>\\r\\n                    <div class=\\\"widget widget-heading\\\">\\r\\n                        <div class=\\\"widget-container\\\">\\r\\n                            <h2 class=\\\"heading-title size-default\\\">Educating Leaders <br class=\\\"br-desktop\\\"> of Character<\\/h2>\\r\\n                        <\\/div>\\r\\n                    <\\/div>\\r\\n                    <div class=\\\" widget widget-text-editor\\\">\\r\\n                        <div class=\\\"widget-container\\\">\\r\\n                            <div class=\\\"text-editor clearfix\\\">Edwiser School inspires a love of learning in children, <br class=\\\"br-desktop\\\"> encouraging creative thinking across all subjects.<\\/div>\\r\\n                        <\\/div>\\r\\n                    <\\/div>\\r\\n                    <div class=\\\" el-banner-btn mobile-align-center widget widget-button\\\">\\r\\n                        <div class=\\\"widget-container\\\">\\r\\n                            <div class=\\\"button-wrapper\\\">\\r\\n                                <a href=\\\"#\\\" class