INSERT INTO `mdl_edw_page_blocks` (`id`, `title`, `label`, `thumbnail`, `content`, `version`, `updateavailable`, `visible`, `type`, `categories`) VALUES
(62, 'testimonialdesign5', 'Testimonial Design 5', '{{>cdnurl}}testimonialdesign5/thumbnail.png', '{\"html\":\"<h2 class=\\\"testimonial-title text-center\\\" style=\\\"margin-top:50px\\\">Testimonials<\\/h2><p class=\\\"edw_testimonial-desc[[inst]] m-0\\\" style=\\\"color:#555;text-align:center;font-size:20px;font-style:normal;font-weight:400;line-height:normal\\\">Here\'s what clients have to say about Edwiser RemUI!<\\/p><div class=\\\"edwiser-testimonial5\\\" data-vvveb-disabled-area contenteditable=\\\"false\\\"><section class=\\\"edw_testimonial[[inst]] edw_adv_slider edw-testimonial-5\\\"><div id=\\\"testimonial-carousel-5[[inst]]\\\" class=\\\"carousel carousel-dark slide edw-carousel\\\" data-ride=\\\"carousel\\\" data-interval=\\\"3000\\\" data-pause=\\\"hover\\\" data-bs-ride=\\\"carousel\\\" data-bs-interval=\\\"3000\\\" data-bs-pause=\\\"hover\\\"><div class=\\\"carousel-inner edw-slider-inner-container\\\" id=\\\"carousel_container[[inst]]\\\"><div class=\\\"carousel-item edw-slider-item active\\\" data-value=\\\"0\\\"><div class=\\\"item-container\\\"><div class=\\\"content-box\\\"><div class=\\\"profile-image-box\\\"><div><div><img class=\\\"edw-profile-img\\\" src=\\\"{{>cdnurl}}testimonialdesign5\\/images\\/profile-images\\/profile-1.svg\\\" alt=\\\"profile-1\\\"><\\/div><\\/div><\\/div><div class=\\\"card-icon\\\"><img src=\\\"{{>cdnurl}}testimonialdesign5\\/images\\/card-icon.svg\\\" alt=\\\"card icon\\\"><\\/div><p class=\\\"profile-desc\\\"><span class=\\\"testimonial-user-name\\\">BERND KRAUSE<\\/span>,<label class=\\\"testimonial-user-desg\\\">Sumega GmbH<\\/label><\\/p><p class=\\\"card-desc-box ellipsis\\\"><span class=\\\"card-desc edw-carousel-content-para\\\">Edwiser RemUI instantly elevates the look-and-feel of Moodle for everyone - teachers, admins and students alike. I like how the course format plugin functions on the front page. The course formats and the simple navigation help a great deal because my students have a good understanding of my offerings and the overall course structure. They are clear about what to do and where to go on the site, making learning easier. Edwiser RemUI beautifully handholds them through the process.<\\/span><span class=\\\"readMoreBtn\\\">read more<\\/span><span class=\\\"readLessBtn\\\">read less<\\/span><\\/p><\\/div><\\/div><\\/div><div class=\\\"carousel-item edw-slider-item\\\" data-value=\\\"1\\\"><div class=\\\"item-container\\\"><div class=\\\"content-box\\\"><div class=\\\"profile-image-box\\\"><div><div><img class=\\\"edw-profile-img\\\" src=\\\"{{>cdnurl}}testimonialdesign5\\/images\\/profile-images\\/profile-2.svg\\\" alt=\\\"profile-1\\\"><\\/div><\\/div><\\/div><div class=\\\"card-icon\\\"><img src=\\\"{{>cdnurl}}testimonialdesign5\\/images\\/card-icon.svg\\\" alt=\\\"card icon\\\"><\\/div><p class=\\\"profile-desc\\\"><span class=\\\"testimonial-user-name\\\">BERND KRAUSE<\\/span>,<label class=\\\"testimonial-user-desg\\\">Sumega GmbH<\\/label><\\/p><p class=\\\"card-desc-box ellipsis\\\"><span class=\\\"card-desc edw-carousel-content-para\\\">Edwiser RemUI instantly elevates the look-and-feel of Moodle for everyone - teachers, admins and students alike. I like how the course format plugin functions on the front page. The course formats and the simple navigation help a great deal because my students have a good understanding of my offerings and the overall course structure. They are clear about what to do and where to go on the site, making learning easier. Edwiser RemUI beautifully handholds them through the process.<\\/span><span class=\\\"readMoreBtn\\\">read more<\\/span><span class=\\\"readLessBtn\\\">read less<\\/span><\\/p><\\/div><\\/div><\\/div><div class=\\\"carousel-item edw-slider-item\\\" data-value=\\\"2\\\"><div class=\\\"item-container\\\"><div class=\\\"content-box\\\"><div class=\\\"profile-image-box\\\"><div><div><img class=\\\"edw-profile-img\\\" src=\\\"{{>cdnurl}}testimonialdesign5\\/images\\/profile-images\\/profile-3.png\\\" alt=\\\"profile-1\\\"><\\/div><\\/div><\\/div><div class=\\\"card-icon\\\"><img src=\\\"{{>cdnurl}}testimonialdesign5\\/images\\/card-icon.svg\\\" alt=\\\"card icon\\\"><\\/div><p class=\\\"profile-desc\\\"><span class=\\\"testimonial-user-name\\\">BERND KRAUSE<\\/span>,<label class=\\\"testimonial-user-desg\\\">Sumega GmbH<\\/label><\\/p><p class=\\\"card-desc-box ellipsis\\\"><span class=\\\"card-desc edw-carousel-content-para\\\">Edwiser RemUI instantly elevates the look-and-feel of Moodle for everyone - teachers, admins and students alike. I like how the course format plugin functions on the front page. The course formats and the simple navigation help a great deal because my students have a good understanding of my offerings and the overall course structure. They are clear about what to do and where to go on the site, making learning easier. Edwiser RemUI beautifully handholds them through the process.<\\/span><span class=\\\"readMoreBtn\\\">read more<\\/span><span class=\\\"readLessBtn\\\">read less<\\/span><\\/p><\\/div><\\/div><\\/div><\\/div><button class=\\\"carousel-control-prev position-absolute edw-slide-control edw-control-prev border-0 bg-transparent\\\" style=\\\"--arrowassetcolor:#3E86F5\\\" type=\\\"button\\\" data-target=\\\"#testimonial-carousel-5[[inst]]\\\" data-slide=\\\"prev\\\" data-bs-target=\\\"#testimonial-carousel-5[[inst]]\\\" data-bs-slide=\\\"prev\\\"><span class=\\\"carousel-control-prev-icon fa fa-light fa-angle-left\\\" aria-hidden=\\\"true\\\"><\\/span><\\/button><button class=\\\"carousel-control-next position-absolute edw-slide-control edw-control-next border-0 bg-transparent\\\" style=\\\"--arrowassetcolor:#3E86F5\\\" type=\\\"button\\\" data-target=\\\"#testimonial-carousel-5[[inst]]\\\" data-slide=\\\"next\\\" data-bs-target=\\\"#testimonial-carousel-5[[inst]]\\\" data-bs-slide=\\\"next\\\"><span class=\\\"carousel-control-next-icon fa fa-light fa-angle-right\\\" aria-hidden=\\\"true\\\"><\\/span><\\/button><ol class=\\\"caro