px 24px;background-color: #fff;}.pricing-table-design-2 .section-container {max-width: 1320px;margin: 0 auto;}.pricing-table-design-2 .desc {color: #4C5A73;font-size: 14px;font-style: normal;font-weight: 400;line-height: 22px;}.pricing-table-design-2 .section-desc {font-size: 16px;line-height: 24px;}.pricing-table-design-2 .pricing-wrapper {display: flex;gap: 30px 60px;flex-wrap: wrap;margin-top: 30px;}.pricing-table-design-2 .accordion-box {width: calc(60% - 30px);display: flex;flex-direction: column;gap: 24px;}.pricing-table-design-2 .pricing-texts-wrapper {gap: 14px;justify-content: flex-end;}.pricing-table-design-2 .pricing-texts-wrapper .price {font-size: 24px;font-weight: 700;line-height: 32px;}.pricing-table-design-2 .pricing-texts-wrapper:not(:has(.strike)) .desc {color: #313848;}.pricing-table-design-2 .pricing-texts-wrapper .strike {color: #313848;}.pricing-table-design-2 .pricing-texts-wrapper .strike .price {text-decoration: line-through;}.pricing-table-design-2 .courses-heading {color: #313848;font-family: Inter;font-size: 16px;font-style: normal;font-weight: 600;line-height: 24px;margin-bottom: 5px;}.pricing-table-design-2 .course-lists {display: flex;flex-direction: column;}.pricing-table-design-2 .check-circle-icon {margin-top: 7px;}.pricing-table-design-2 .course-link {display: flex;}.pricing-table-design-2 .course-link .desc {color: #313848;margin: 0 10px 0 6px;text-decoration: none;padding: 5px 0;}.pricing-table-design-2 .course-link img {max-width: 16px;max-height: 16px;object-fit: contain;}.pricing-table-design-2 .btn-wrapper {overflow: hidden;margin-top: 12px;transition: all 0.3s ease;}.pricing-table-design-2 .pricing-btn {min-width: 128px;min-height: 40px;height: fit-content;font-size: 14px;font-style: normal;font-weight: 600;line-height: normal;display: flex;align-items: center;justify-content: center;}.pricing-table-design-2 .pricing-btn.btn-primary {background-color: #0051F9;}.pricing-table-design-2 .pricing-btn.btn-primary:hover {background: #0041C7;}.pricing-table-design-2 .pricing-btn.btn-secondary {background-color: #fff;border: 1px solid #0051F9;color: #0051F9;}.pricing-table-design-2 .pricing-btn.btn-secondary:hover {background-color: #0051F9;color: #fff;}.pricing-table-design-2 .ribbon {clip-path: polygon(100% 0, calc(100% - 8px) 50%, 100% 100%, 0 100%, 0 0);background-color: #0051F9;padding: 5px 17px 5px 12px;border-top-left-radius: 5px;border-bottom-left-radius: 5px;color: #FFF;font-size: 12px;font-style: normal;font-weight: 400;line-height: normal;}.pricing-table-design-2 .pricing-card {border-radius: 4px;border: 1px solid #D5DDEA;background: #FFF;padding: 0 24px 24px;transition: all 0.3s ease;}.pricing-table-design-2 .pricing-card .pricing-card-header {width: 100%;cursor: pointer;padding-top: 24px;}.pricing-table-design-2 .pricing-card .title-with-img {display: flex;gap: 12px;align-items: center;}.pricing-table-design-2 .pricing-card .title-with-img .img-box {width: 32px;height: 32px;display: flex;justify-content: center;align-items: center;padding: 4px;border-radius: 4px;background: #F5F8FD;}.pricing-table-design-2 .pricing-card .title-with-img .title {color: #313848;font-size: 20px;font-style: normal;font-weight: 700;line-height: 28px;}.pricing-table-design-2 .pricing-card .arrow-icon {max-width: 24px;max-height: 24px;}.pricing-table-design-2 .pricing-card .course-count-tag {padding: 6px 10px;margin: 24px 0 10px;border-radius: 4px;background: #F5F8FD;width: max-content;color: #647390;font-size: 12px;font-style: normal;font-weight: 400;line-height: normal;}.pricing-table-design-2 .pricing-card .sub-desc {margin: 0 0 24px;}.pricing-table-design-2 .pricing-card .pricing-card-body {padding-bottom: 24px;border-bottom: 1px solid #EBF0F9;}.pricing-table-design-2 .pricing-card .course-link:hover .desc {text-decoration-line: underline;text-underline-offset: 2px;}.pricing-table-design-2 .pricing-card:hover {border-color: #0051F9;box-shadow: 0px 8px 22px 0px rgba(0, 0, 0, 0.12);}.pricing-table-desig