INSERT INTO `mdl_edw_page_blocks` (`id`, `title`, `label`, `thumbnail`, `content`, `version`, `updateavailable`, `visible`, `type`, `categories`) VALUES
(133, 'pricingtabledesign3', 'Pricing Table Design 3', '{{>cdnurl}}pricingtabledesign3/thumbnail.png', '{\"html\":\"<section class=\\\"pricing-table-design-3\\\" ><div class=\\\"section-container wrapper\\\"><p class=\\\"desc section-desc\\\">Select the perfect plan that suits your needs from our comprehensive pricing table. Whether you\'re an individual seeking essential features or a business requiring advanced capabilities, our transparent pricing structure ensures flexibility and value. Explore the details below to find the ideal package that propels your goals forward.<\\/p><div class=\\\"pricing-wrapper\\\"><div class=\\\"pricing-card\\\"><div class=\\\"pricing-card-header\\\"><p class=\\\"title m-0\\\">Digital Marketing<\\/p><p class=\\\"course-count-tag\\\">6 courses<\\/p><\\/div><div class=\\\"pricing-card-body\\\"><p class=\\\"desc\\\">Explore digital marketing\'s dynamic landscape, mastering social media and SEO strategies for essential skill development.<\\/p><p class=\\\"courses-heading\\\">Modules<\\/p><div class=\\\"course-lists\\\"><div class=\\\"d-flex gap-24 justify-content-between\\\"><div class=\\\"course-link d-flex\\\"><img class=\\\"check-circle-icon\\\" src=\\\"{{>cdnurl}}pricingtabledesign3\\/images\\/icons\\/check-circle.svg\\\" alt=\\\"basic icon\\\"><a href=\\\"#\\\" class=\\\"desc\\\">Introduction to Digital Marketing: Overview of key concepts and strategies. <img src=\\\"{{>cdnurl}}pricingtabledesign3\\/images\\/icons\\/shortcut-link.svg\\\" alt=\\\"basic icon\\\"><\\/a><\\/div><p class=\\\"desc desc-bold m-0\\\" style=\\\"padding:5px 0\\\">$25<\\/p><\\/div><div class=\\\"d-flex gap-24 justify-content-between\\\"><div class=\\\"course-link d-flex\\\"><img class=\\\"check-circle-icon\\\" src=\\\"{{>cdnurl}}pricingtabledesign3\\/images\\/icons\\/check-circle.svg\\\" alt=\\\"basic icon\\\"><a href=\\\"#\\\" class=\\\"desc\\\">Social Media Marketing Mastery: Harnessing the power of social platforms. <img src=\\\"{{>cdnurl}}pricingtabledesign3\\/images\\/icons\\/shortcut-link.svg\\\" alt=\\\"basic icon\\\"><\\/a><\\/div><p class=\\\"desc desc-bold m-0\\\" style=\\\"padding:5px 0\\\">$20<\\/p><\\/div><div class=\\\"d-flex gap-24 justify-content-between\\\"><div class=\\\"course-link d-flex\\\"><img class=\\\"check-circle-icon\\\" src=\\\"{{>cdnurl}}pricingtabledesign3\\/images\\/icons\\/check-circle.svg\\\" alt=\\\"basic icon\\\"><a href=\\\"#\\\" class=\\\"desc\\\">Search Engine Optimization (SEO) <img src=\\\"{{>cdnurl}}pricingtabledesign3\\/images\\/icons\\/shortcut-link.svg\\\" alt=\\\"basic icon\\\"><\\/a><\\/div><p class=\\\"desc desc-bold m-0\\\" style=\\\"padding:5px 0\\\">$30<\\/p><\\/div><div class=\\\"d-flex gap-24 justify-content-between\\\"><div class=\\\"course-link d-flex\\\"><img class=\\\"check-circle-icon\\\" src=\\\"{{>cdnurl}}pricingtabledesign3\\/images\\/icons\\/check-circle.svg\\\" alt=\\\"basic icon\\\"><a href=\\\"#\\\" class=\\\"desc\\\">Content Marketing Strategies: Crafting compelling and effective content. <img src=\\\"{{>cdnurl}}pricingtabledesign3\\/images\\/icons\\/shortcut-link.svg\\\" alt=\\\"basic icon\\\"><\\/a><\\/div><p class=\\\"desc desc-bold m-0\\\" style=\\\"padding:5px 0\\\">$25<\\/p><\\/div><div class=\\\"d-flex gap-24 justify-content-between\\\"><div class=\\\"course-link d-flex\\\"><img class=\\\"check-circle-icon\\\" src=\\\"{{>cdnurl}}pricingtabledesign3\\/images\\/icons\\/check-circle.svg\\\" alt=\\\"basic icon\\\"><a href=\\\"#\\\" class=\\\"desc\\\">Email Marketing Fundamentals: Building successful email campaigns. <img src=\\\"{{>cdnurl}}pricingtabledesign3\\/images\\/icons\\/shortcut-link.svg\\\" alt=\\\"basic icon\\\"><\\/a><\\/div><p class=\\\"desc desc-bold m-0\\\" style=\\\"padding:5px 0\\\">$30<\\/p><\\/div><div class=\\\"d-flex gap-24 justify-content-between\\\"><div class=\\\"course-link d-flex\\\"><img class=\\\"check-circle-icon\\\" class=\\\"check-circle-icon\\\" src=\\\"{{>cdnurl}}pricingtabledesign3\\/images\\/icons\\/check-circle.svg\\\" alt=\\\"basic icon\\\"><a href=\\\"#\\\" class=\\\"desc\\\">Analytics and Performance Measurement <img src=\\\"{{>cdnurl}}pricingtabledesign3\\/images\\/icons\\/shortcut-link.svg\\\" alt=\\\"basic icon\\\"><\\/a><\\/div><p class=\\\"desc desc-bold m-0\\\" style=\\\"padding:5px 0\\\">$20<\\/p><\\/div><\\/div><\\/div><div class=\\\"pricing-card-footer\\\"><div class=\\\"pricing-texts-wrapper d-flex align-items-center\\\"><p class=\\\"desc m-0\\\"><span class=\\\"price\\\">$99<\\/span><span>\\/ Year<\\/span><\\/p><p class=\\\"desc strike m-0\\\"><span class=\\\"price\\\">$144<\\/span><span>\\/ Year<\\/span><\\/p><\\/div><div class=\\\"d-flex btn-wrapper\\\"><a href=\\\"#\\\" class=\\\"btn btn-primary pricing-btn ml-auto\\\">Buy<\\/a><\\/div><\\/div><\\/div><div class=\\\"pricing-card\\\"><div class=\\\"pricing-card-header\\\"><p class=\\\"title m-0\\\">Subscription<\\/p><p class=\\\"course-count-tag\\\">1 Year<\\/p><img class=\\\"premium-pattern\\\" src=\\\"{{>cdnurl}}pricingtabledesign3\\/images\\/premium-pattern.png\\\" alt=\\\"pattern\\\"><\\/div><div class=\\\"pricing-card-body\\\"><p class=\\\"desc\\\">Unlock premium content with tailored subscription plans, offering unlimited access, flexible learning options and updates.<\\/p><p class=\\\"courses-heading\\\">Benefits<\\/p><div class=\\\"course-lists\\\"><div href=\\\"#\\\" class=\\\"course-link d-flex\\\"><img class=\\\"check-circle-icon\\\" src=\\\"{{>cdnurl}}pricingtabledesign3\\/images\\/icons\\/check-circle.svg\\\" alt=\\\"basic icon\\\"><p class=\\\"desc\\\">Flexible Learning: Tailor your schedule with on-demand access.<\\/p><\\/div><div href=\\\"#\\\" class=\\\"course-link d-flex\\\"><img class=\\\"check-circle-icon\\\" src=\\\"{{>cdnurl}}pricingtabledesign3\\/images\\/icons\\/check-circle.svg\\\" alt=\\\"basic icon\\\"><p class=\\\"desc\\\">Personalized Guidance: Receive expert support for individualized learning paths.<\\/p><\\/div><div href=\\\"#\\\" class=\\\"course-link d-flex\\\"><img class=\\\"check-circle-icon\\\" src=\\\"{{>cdnurl}}pricingtabledesign3\\/images\\/icons\\/check-circle.svg\\\" alt=\\\"basic icon\\\"><p class=\\\"desc\\\">Diverse Subject Coverage: Explore a wide range of topics and specialties.<\\/p><\\/div><div href=\\\"#\\\" class=\\\"course-link d-flex\\\"><img class=\\\"check-circle-icon\\\" src=\\\"{{>cdnurl}}pricingtabledesign3\\/images\\/icons\\/check-circle.svg\\\" alt=\\\"basic icon\\\"><p class=\\\"desc\\\">Interactive Community: Engage with a vibrant learning community for networking.<\\/p><\\/div><div href=\\\"#\\\" class=\\\"course-link d-flex\\\"><img class=\\\"check-circle-icon\\\" src=\\\"{{>cdnurl}}pricingtabledesign3\\/images\\/icons\\/check-circle.svg\\\" alt=\\\"basic icon\\\"><p class=\\\"desc\\\">Convenient Accessibility: Learn from anywhere with seamless online access.<\\/p><\\/div><div href=\\\"#\\\" class=\\\"course-link d-flex\\\"><img class=\\\"check-circle-icon\\\" src=\\\"{{>cdnurl}}pricingtabledesign3\\/images\\/icons\\/check-circle.svg\\\" alt=\\\"basic icon\\\"><p class=\\\"desc\\\">Career Advancement: Boost your career prospects with enhanced skills and knowledge.<\\/p><\\/div><div href=\\\"#\\\" class=\\\"course-link d-flex\\\"><img class=\\\"check-circle-icon\\\" src=\\\"{{>cdnurl}}pricingtabledesign3\\/images\\/icons\\/check-circle.svg\\\" alt=\\\"basic icon\\\"><p class=\\\"desc\\\">Career Advancement: Boost your career prospects with enhanced skills and knowledge.<\\/p><\\/div><\\/div><\\/div><div class=\\\"pricing-card-footer\\\"><div class=\\\"pricing-texts-wrapper d-flex align-items-center\\\"><p class=\\\"desc m-0\\\"><span class=\\\"price\\\">$199<\\/span><span>\\/ Year<\\/span><\\/p><p class=\\\"desc strike m-0\\\"><span class=\\\"price\\\">$299<\\/span><span>\\/ Year<\\/span><\\/p><\\/div><div class=\\\"d-flex btn-wrapper\\\"><a href=\\\"#\\\" class=\\\"btn btn-secondary pricing-btn ml-auto\\\">Subscribe<\\/a><\\/div><\\/div><\\/div><\\/div><\\/div><\\/section>\",\"css\":\" .pricing-table-design-3 {pa