t: 400;line-height: 24px;margin: 4px 0 0;}.section-team-design-2 .team-card:hover {filter: drop-shadow(0px 6px 30px rgba(0, 0, 0, 0.15));}@media screen and (min-width: 1024px) {.edw-limitedwidth-block .section-team-design-2 .section-container {max-width: 820px;}.edw-limitedwidth-block .section-team-design-2 .box {width: calc(50% - 12px);}}@media screen and (max-width: 1024px) {.section-team-design-2 .section-container {max-width: 820px;}.section-team-design-2 .box {width: calc(50% - 12px);}}@media screen and (max-width: 767px) {.section-team-design-2 .section-container {max-width: 600px;}.section-team-design-2 .card-container {justify-content: center;display: grid;grid-template-columns: repeat(auto-fit, minmax(280px, 1fr));row-gap: 30px;}.section-team-design-2 .box {width: unset;max-width: 430px;margin: 0 auto;}}\",\"js\":\"\"}', 2021071606, 0, 1, 'block', 'Teams'),
