ction-team-design-6 .team-card {width: calc(25% - 18px);background: #FFF;overflow: hidden;}.section-team-design-6 .team-card .card-head {border: 1px solid #EBEBEB;border-bottom: 0;padding-top: 15px;height: 240px;}.section-team-design-6 .team-card .img-box {width: fit-content;height: 100%;margin: 0 auto;}.section-team-design-6 .team-card .img-box img {height: 100%;width: 100%;object-fit: cover;}.section-team-design-6 .team-card .name, .section-team-design-6 .team-card .desc {padding: 6px 0px;background: #F6F6F6;text-align: center;color: #444;font-size: 16px;font-weight: 500;line-height: 22px;margin: 0;}.section-team-design-6 .team-card .name {color: #313848;transition: background 0.3s ease, color 0.3s ease;}.section-team-design-6 .team-card .desc {border: 1px solid #EBEBEB;border-top: 0;background: #FFF;margin: 0;color: #4c5a73;font-weight: 400;}.section-team-design-6 .team-card:hover .name {background: #9A3CDF;color: #FFF;}@media screen and (min-width: 1024px) {.edw-limitedwidth-block .section-team-design-6 .section-container {max-width: 820px;}.edw-limitedwidth-block .section-team-design-6 .team-card {width: calc(50% - 12px);}}@media screen and (max-width: 1024px) {.section-team-design-6 .section-container {max-width: 820px;}.section-team-design-6 .team-card {width: calc(50% - 12px);}}@media screen and (max-width: 767px) {.section-team-design-6 .section-container {max-width: 600px;}.section-team-design-6 .section-container .team-card {max-width: 350px;}.section-team-design-6 .card-container {justify-content: center;}.section-team-design-6 .team-card {flex: 1 1 230px;width: unset;}}\",\"js\":\"\"}', 2021071607, 0, 1, 'block', 'Teams');
