(171, 'recentforums', 'Recent Forums', '{{>cdnurl}}recentforums/thumbnail.png', '{\"html\":\"<div class=\\\"wrapper\\\"><h3 class=\\\"section-heading\\\">Recent Forums<\\/h3><div class=\\\"edwiser-recentforums\\\" data-edwiser-dynamic data-shortcode=\\\"edwiser-recentforums\\\" data-vvveb-disabled-area contenteditable=\\\"false\\\">[edwiser-remuiblck-recentforums layout=\\\"recentforums\\\"]<\\/div><\\/div>\",\"css\":\".wrapper{max-width: 1320px; margin: 0 auto; }.wrapper:has(.only-available-for-admins-and-managers) { display: none !important;}h3.section-heading {font-size: 1.5rem;font-weight: 700;}.section-heading {color: #2f3847;margin: 48px 24px 0px 24px;}\",\"js\":\"\"}', 2021071610, 0, 1, 'dynamic', 'Dashboard blocks'),
(172, 'todolist', 'To Do List', '{{>cdnurl}}todolist/thumbnail.png', '{\"html\":\"<div class=\\\"wrapper\\\"><h3 class=\\\"section-heading\\\">To Do List<\\/h3><div class=\\\"edwiser-todolist\\\" data-edwiser-dynamic data-shortcode=\\\"edwiser-todolist\\\" data-vvveb-disabled-area contenteditable=\\\"false\\\">[edwiser-remuiblck-todolist layout=\\\"todolist\\\"]<\\/div><\\/div>\",\"css\":\".wrapper{max-width: 1320px; margin: 0 auto;}.wrapper:has(.only-available-for-admins-and-managers) { display: none !important;}h3.section-heading {font-size: 1.5rem;font-weight: 700;}.section-heading {color: #2f3847;margin: 48px 24px 0px 24px;}\",\"js\":\"\"}', 2021071610, 0, 1, 'dynamic', 'Dashboard blocks'),
(173, 'importblock', 'Import block', '{{>cdnurl}}html/thumbnail.png', '{\"html\":\"<section class=\\\"section-importblock\\\"><div class=\\\"section-container\\\"><p class=\\\"heading\\\"><strong>Import Block:<\\/strong>Please choose an Edwiser JSON block file that you have downloaded or exported to proceed with the import.<\\/p><form class=\\\"block_json_upload_form\\\" action=\\\"\\/upload\\\" method=\\\"post\\\" enctype=\\\"multipart\\/form-data\\\"><input type=\\\"file\\\" class=\\\"form-control jsonfileholder\\\" name=\\\"file\\\" required=\\\"\\\"><button type=\\\"submit\\\" class=\\\"btn btn-primary import-block-submit-btn\\\">Submit<\\/button><\\/form><p class=\\\"heading mt-2\\\"><strong>NOTE:<\\/strong>If the JSON file is not from a hosted site or was exported from a local site, the media files must be uploaded manually.<\\/p><\\/div><\\/section>\",\"css\":\".section-importblock {padding: 20px 24px;background-color: #ffffff;}.section-importblock .section-container {max-width: 1320px;margin: 0 auto;}.section-importblock .heading {color: #343A40;font-size: 16px;font-style: normal;font-weight: 400;line-height: 24px;margin: 0 0 10px;}.section-importblock .import-block-submit-btn {margin-top: 12px;}.section-importblock input[type=\\\"file\\\"] {border: 1px solid #D9DEE3;background-color: #FFF;height: unset;padding: 9px;color: #000;font-size: 12px;font-style: normal;font-weight: 400;line-height: normal;cursor: pointer;}.section-importblock input[type=\\\"file\\\"]::-webkit-file-upload-button, .section-importblock input[type=\\\"file\\\"]::file-selector-button {background-color: #D9D9D9;border: 0;border-radius: 3px;padding: 5px 8px;margin-right: 12px;cursor: pointer;}.section-importblock input[type=\\\"file\\\"]:hover::-webkit-file-upload-button, .section-importblock input[type=\\\"file\\\"]:hover::file-selector-button {background-color: #cccccc;}\",\"js\":\"function remove_liveCustomizer_exportblock_btn(){let e=document.querySelector(\\\"#inst[[inst]] .block_exporter_btn\\\"),t=document.querySelector(\\\"#inst[[inst]] .live-customizer-btn\\\"),s=document.querySelector(\\\"#inst[[inst]]\\\");e&&t&&(e.classList.remove(\\\"d-flex\\\"),t.classList.remove(\\\"d-flex\\\"),e.classList.add(\\\"d-none\\\"),t.classList.add(\\\"d-none\\\")),document.body.classList.contains(\\\"editing\\\")||s.classList.add(\\\"d-none\\\")}remove_liveCustomizer_exportblock_btn();\"}', 2025010615, 0, 1, 'block', NULL);
INSERT INTO `mdl_edw_page_block_layouts` (`id`, `title`, `belongsto`, `label`, `thumbnail`, `content`, `version`, `updateavailable`, `visible`) VALUES
(1, 'cldefault', 'courses', 'Courses Grid Layout', '{{>cdnurl}}cldefault/thumbnail.png', '{\"html\":\"<section class=\'py-5 section-[[inst]]\'><div class=\'container\'><div class=\'row\'><div class=\'col-12\'><div id=\'epb-carousel-[[inst]]\' class=\'carousel slide\' data-ride=\'carousel\' data-bs-ride=\'carousel\'><div class=\'carousel-inner\'>{{#item}}<div class=\'carousel-item {{#isactive}}active{{\\/isactive}}\'><div class=\'row card-deck\'>{{#courses}}<div class=\'col-md-4 mb-3 px-md-0\'><div class=\'card\'><a href=\'{{courseurl}}\' class=\'epb-card-img\' style=\'background-image:url({{{courseimage}}})\'><\\/a><div class=\'card-body border\'><small class=\'text-secondary ellipsis ellipsis-1\'>{{categoryname}}<\\/small><h4 class=\'card-title ellipsis ellipsis-2\' title=\'{{fullname}}\'>{{{fullname}}}<\\/h4><p class=\'card-text ellipsis ellipsis-3 font-size-16\'>{{shortsummary}}<\\/p><div class=\'card-footer p-0 bg-transparent border-0\'><small class=\'text-secondary\'>Last updated on {{lastmodified}}<\\/small><\\/div><\\/div><\\/div><\\/div>{{\\/courses}}<\\/div><\\/div>{{\\/item}}<\\/div><\\/div><\\/div>{{#shownav}}<div class=\'col-12 d-flex justify-content-center align-items-center my-3\'><a class=\'btn btn-primary d-flex justify-content-center align-items-center carousel-btn mr-1\' href=\'#epb-carousel-[[inst]]\' role=\'button\' data-target=\'#epb-carousel-[[inst]]\' data-bs-target=\'#epb-carousel-[[inst]]\' data-slide=\'prev\' data-bs-slide=\'prev\'><i class=\'fa fa-arrow-left\'><\\/i><\\/a><a class=\'btn btn-primary d-flex justify-content-center align-items-center carousel-btn\' href=\'#epb-carousel-[[inst]]\' role=\'button\' data-target=\'#epb-carousel-[[inst]]\' data-bs-target=\'#epb-carousel-[[inst]]\' data-slide=\'next\' data-bs-slide=\'next\'><i class=\'fa fa-arrow-right\'><\\/i><\\/a><\\/div>{{\\/shownav}}<\\/div><\\/div><\\/section>\",\"css\":\".epb-card-img{min-height: 200px;background-size: cover;background-position: center;} .carousel-btn{width:40px;height:40px;border-radius:50%;}.ellipsis-3{min-height:70px;} .ellipsis-2{max-height:50px;}.card-footer{position:absolute;bottom:10px;}\",\"js\":\"\",\"constraints\":{\"limit\":-1,\"group\":3}}', 2021071518, 0, 1),
(2, 'clcoursedesign1', 'courses', 'Courses Design 1', '{{>cdnurl}}clcoursedesign1/thumbnail.png', '{\"html\":\"<section class=\'py-5 section-[[inst]]\'><div class=\'container\'><div class=\'row\'><div class=\'col-12\'><div id=\'epb-carousel-[[inst]]\' class=\'carousel slide\' data-ride=\'carousel\' data-bs-ride=\'carousel\'><div class=\'carousel-inner\'>{{#item}}<div class=\'carousel-item {{#isactive}}active{{\\/isactive}}\'><div class=\'row card-deck\'>{{#courses}}<div class=\'col-md-3 p-md-0 mb-5\'><div class=\'card\'><div class=\'card-image\'><img loading=\'lazy\' src=\'{{{courseimage}}}\' style=\'max-height:180px;min-height:180px;width:100%\'><\\/div>{{#teacher}}<a class=\'card-action\' href=\'{{{url}}}\'><img loading=\'lazy\' src=\'{{{picture}}}\' title=\'{{{name}}}\'><\\/a>{{\\/teacher}}<div class=\'card-body p-0\'><h4 class=\'m-3 ellipsis ellipsis-2\' title=\'{{{fullname}}}\'>{{{fullname}}}<\\/h4><div class=\'card-text ellipsis ellipsis-3 m-3 p-0\'>{{{shortsummary}}}<\\/div><\\/div><div class=\'card-footer bg-white p-0 border-0\'><small class=\'d-block text-secondary px-3 py-2\'>Last updated on {{lastmodified}}<\\/small><a href=\'{{{courseurl}}}\' class=\'card-button\'>View Course<\\/a><\\/div><\\/div><\\/div>{{\\/courses}}<\\/div><\\/div>{{\\/item}}<\\/div><\\/div><\\/div>{{#shownav}}<div class=\'col-12 d-flex justify-content-center align-items-center my-3\'><a class=\'btn btn-primary d-flex justify-content-center align-items-center carousel-btn mr-1\' href=\'#epb-carousel-[[inst]]\' role=\'button\' data-target=\'#epb-carousel-[[inst]]\' data-bs-target=\'#epb-carousel-[[inst]]\' data-slide=\'prev\' data-bs-slide=\'prev\'><i class=\'fa fa-arrow-left\'><\\/i><\\/a><a class=\'btn btn-primary d-flex justify-content-center align-items-center carousel-btn\' href=\'#epb-carousel-[[inst]]\' role=\'button\' data-target=\'#epb-carousel-[[inst]]\' data-bs-target=\'#epb-carousel-[[inst]]\' data-slide=\'next\' data-bs-slide=\'next\'><i class=\'fa fa-arrow-right\'><\\/i><\\/a><\\/div>{{\\/shownav}}<\\/div><\\/div><\\/section>\",\"css\":\".card{border-radius:8px;box-shadow:0 4px 8px 0 rgba(0,0,0,.2),0 6px 20px 0 rgba(0,0,0,.19)}.card-image img{max-height:100%;max-width:100%;border-radius:0 0 calc(.215rem - 1px) calc(.215rem - 1px)}.card-action{position: absolute;top: 135px;right: 15px;display: flex;width: 50px;z-index: 2;color: #e26d5c;background: #fff;border-radius: 100%;padding: 15px;font-size: 15px;box-shadow: 0 1px 2px 0 rgb(0 0 0 \\/ 20%), 0 1px 2px 0 rgb(0 0 0 \\/ 19%);justify-content: center;height: 50px;align-items: center;margin-left: 20px;} .card-action:hover {color:#fff;background:#e26d5c; -webkit-animation:pulse 1.5s infinite}.card-action img {width:50px;height:50px;border-radius:50%;}.card-heading{font-size:18px;font-weight:700;background:#fff;padding:10px 15px}.card-text{padding:10px 15px;background:#fff;font-size:14px; color:#636262} .card-button{display:flex;justify-content:center;padding:10px 0;width:100%;background-color:#1f487e; color:#fff;border-radius:0 0 calc(.215rem - 1px) calc(.215rem - 1px)}.card-button:hover{text-decoration:none;background-color:#1d3461;color:#fff} @-webkit-keyframes pulse{0%{-moz-transform:scale(.9);-ms-transform:scale(.9);-webkit-transform:scale(.9);transform:scale(.9)}70%{-moz-transform:scale(1);-ms-transform:scale(1);-webkit-transform:scale(1);transform:scale(1);box-shadow:0 0 0 50px rgba(90,153,212,0)}100%{-moz-transform:scale(.9);-ms-transform:scale(.9);-webkit-transform:scale(.9);transform:scale(.9);box-shadow:0 0 0 0 rgba(90,153,212,0)}}.card-text {margin-bottom:5px;}.ellipsis-2{max-height:50px;min-height:50px;}.ellipsis-3{max-height: 60px;min-height:60px;}.carousel-btn{width:40px;height:40px;border-radius:50%;}@media (max-width:480px) {.ellipsis-3{max-height: 70px;min-height: 70px;}}\",\"js\":\"\",\"constraints\":{\"limit\":-1,\"group\":4}}', 2021071819, 0, 1),
(3, 'clcoursedesign2', 'courses', 'Courses Design 2', '{{>cdnurl}}clcoursedesign2/thumbnail.png', '{\"html\":\"<section class=\'pt-5 pb-5 section-[[inst]]\'><div class=\'container\'><div class=\'row\'><div class=\'col-12\'><div id=\'epb-carousel-[[inst]]\' class=\'carousel slide\' data-ride=\'carousel\' data-bs-ride=\'carousel\'><div class=\'carousel-inner latest-cards grid-view\'>{{#item}}<div class=\'carousel-item {{#isactive}}active{{\\/isactive}}\'><div class=\'row card-deck\'>{{#courses}}<div class=\'course_card col-md-3 my-3 card px-0 mr-2\' data-plugin=\'appear\' data-animate=\'{{animation}}\' data-course-id=\'{{id}}\'><div class=\'wrapper\' style=\'background-image:url({{{courseimage}}});background-size:cover;background-position:center;position:relative\'><a href=\'{{ courseurl }}\' class=\'card-link\' aria-label=\'Course - {{{ fullname }}}\'><\\/a>{{#startdate}}<div class=\'date btn-primary\'><span class=\'day\'>{{day}}<\\/span><span class=\'month\'>{{month}}<\\/span><span class=\'year\'>{{year}}<\\/span><\\/div>{{\\/startdate}}{{# teacher }}<a href=\'{{ url }}\' class=\'d-flex justify-content-end instructor-img {{ imgStyle }}\' data-toggle=\'tooltip\' title=\'{{{name}}}\' aria-label=\'Instructor for {{fullname}} is - {{name}}\'><img src=\'{{ picture }}\' style=\'border:2px solid #fff;cursor:pointer\' class=\'rounded-circle\' alt=\'{{ name }}\'><\\/a>{{\\/ teacher }}<div class=\'data\'><div class=\'content\' title=\'{{{fullname}}}\'><span class=\'author ellipsis ellipsis-1\' style=\'-webkit-box-orient:vertical\'>{{{categoryname}}}<\\/span><a href=\'{{ courseurl }}\' class=\'font-weight-400 text-dark font-size-18 card-title my-1 ellipsis ellipsis-2 title\' style=\'-webkit-box-orient:vertical\'>{{{fullname}}}<\\/a><p class=\'text\' style=\'-webkit-box-orient:vertical\'>{{{shortsummary}}}<\\/p><\\/div><\\/div><\\/div><\\/div>{{\\/courses}}<\\/div><\\/div>{{\\/item}}<\\/div><\\/div><\\/div>{{#shownav}}<div class=\'col-12 d-flex justify-content-center align-items-center my-3\'><a class=\'btn btn-primary d-flex justify-content-center align-items-center carousel-btn mr-1\' href=\'#epb-carousel-[[inst]]\' role=\'button\' data-target=\'#epb-carousel-[[inst]]\' data-bs-target=\'#epb-carousel-[[inst]]\' data-slide=\'prev\' data-bs-slide=\'prev\'><i class=\'fa fa-arrow-left\'><\\/i><\\/a><a class=\'btn btn-primary d-flex justify-content-center align-items-center carousel-btn\' href=\'#epb-carousel-[[inst]]\' role=\'button\' data-target=\'#epb-carousel-[[inst]]\' data-bs-target=\'#epb-carousel-[[inst]]\' data-slide=\'next\' data-bs-slide=\'next\'><i class=\'fa fa-arrow-right\'><\\/i><\\/a><\\/div>{{\\/shownav}}<\\/div><\\/div><\\/section>\",\"css\":\".course_card{max-width:250px}.course_card .wrapper{background-color:#fff;min-height:350px;position:relative;overflow:hidden;box-shadow:0 2px 2px rgba(0,0,0,.1);border-radius:3px}.course_card .wrapper .menu-picker-select:hover>.menu-content{transform:translateX(-100%);transition:transform .3s,-webkit-transform .3s}.course_card .wrapper .menu-picker-select .menu-picker{position:absolute;top:0;right:0;width:20%;z-index:1}.course_card .wrapper .menu-picker-select .menu-picker .menu-button{position:absolute;z-index:999;top:16px;right:16px;width:25px;text-align:center;cursor:pointer}.course_card .wrapper .menu-picker-select .menu-picker .menu-button span{width:5px;height:5px;background-color:#fff;color:#fff;position:relative;display:inline-block;border-radius:50%}.course_card .wrapper .menu-picker-select .menu-picker .menu-button span::before{left:-10px;content:\'\';display:block;width:5px;height:5px;background-color:#fff;position:absolute;border-radius:50%}.course_card .wrapper .menu-picker-select .menu-picker .menu-button span::after{right:-10px;content:\'\';display:block;width:5px;height:5px;background-color:#fff;position:absolute;border-radius:50%}.course_card .wrapper .menu-picker-select .menu-content{text-align:center;position:absolute;top:0;right:-21%;width:20%;z-index:2;transition:transform .3s;transform:translateX(0)}.course_card .wrapper .instructor-img{position:absolute;top:175px;right:10px}.course_card .wrapper .instructor-img img{height:50px;width:50px}.course_card .wrapper .date{position:absolute;top:0;left:0;color:#fff;padding:.4em}.course_card .wrapper .date span{display:block;text-align:center}.course_card .wrapper .date .day{font-weight:100;font-size:20px;text-shadow:2px 3px 2px rgba(0,0,0,.18)}.course_card .wrapper .date .month{text-transform:uppercase;font-size:12px}.course_card .wrapper .date .year{font-size:12px}.course_card .wrapper .data{position:absolute;bottom:0;width:100%;transform:translateY(86px);transition:transform .3s}.course_card .wrapper .data:hover{transform:translateY(0)}.course_card .wrapper .data:hover .course-stat{transform:translateY(0)!important}.course_card .wrapper .data .course-stat{transition:transform .3s,-webkit-transform .3s;transform:translateY(42px)}.course_card .wrapper .data .course-stat .card-footer.activity-btn{position:absolute;width:100%;bottom:0;right:0}.course_card .wrapper .data .content{padding:1em;position:relative;z-index:1;min-height:200px;background-color:#fff;box-shadow:0 5px 25px 5px rgba(0,0,0,.2);min-height:160px}.course_card .wrapper .data .content .author{font-size:12px}.course_card .wrapper .data .content .text{font-size:12px;height:70px;margin:0}.course_card .wrapper .data .content .card-title{min-height:56px}\",\"js\":\"\",\"constraints\":{\"limit\":-1,\"group\":3}}', 2021071811, 0, 1),
