lements\":[{\"x\":19.202363367799116,\"y\":16.61807580174927,\"width\":59.527326440177255,\"height\":64.13994169096209,\"action\":{\"library\":\"H5P.Image 1.1\",\"params\":{\"contentName\":\"Image\",\"file\":{\"path\":\"images\\/file-5f2690b593278.jpg\",\"mime\":\"image\\/jpeg\",\"copyright\":{\"license\":\"U\"},\"width\":2560,\"height\":1600}},\"subContentId\":\"b7eed78f-1039-4905-b9e7-c32b3940bb7b\",\"metadata\":{\"contentType\":\"Image\",\"license\":\"U\",\"title\":\"Untitled Image\"}},\"alwaysDisplayComments\":false,\"backgroundOpacity\":0,\"displayAsButton\":false,\"buttonSize\":\"big\",\"goToSlideType\":\"specified\",\"invisible\":false,\"solution\":\"\"},{\"x\":73.8552437223043,\"y\":75.80174927113703,\"width\":40,\"height\":40,\"action\":{\"library\":\"H5P.AdvancedText 1.1\",\"params\":{\"text\":\"<p>I like this Place&nbsp;<\\/p>\\n\"},\"subContentId\":\"a73d7a51-df71-4589-871d-1dc6a91f7adb\",\"metadata\":{\"contentType\":\"Text\",\"license\":\"U\",\"title\":\"Untitled Text\"}},\"alwaysDisplayComments\":false,\"backgroundOpacity\":0,\"displayAsButton\":true,\"buttonSize\":\"big\",\"goToSlideType\":\"specified\",\"invisible\":false,\"solution\":\"\"}],\"slideBackgroundSelector\":{}}],\"keywordListEnabled\":true,\"globalBackgroundSelector\":{\"fillGlobalBackground\":\"#c2ccf0\"},\"keywordListAlwaysShow\":false,\"keywordListAutoHide\":false,\"keywordListOpacity\":90},\"override\":{\"activeSurface\":false,\"hideSummarySlide\":false,\"summarySlideSolutionButton\":true,\"summarySlideRetryButton\":true,\"enablePrintButton\":false,\"social\":{\"showFacebookShare\":false,\"facebookShare\":{\"url\":\"@currentpageurl\",\"quote\":\"I scored @score out of @maxScore on a task at @currentpageurl.\"},\"showTwitterShare\":false,\"twitterShare\":{\"statement\":\"I scored @score out of @maxScore on a task at @currentpageurl.\",\"url\":\"@currentpageurl\",\"hashtags\":\"h5p, course\"},\"showGoogleShare\":false,\"googleShareUrl\":\"@currentpageurl\"}},\"l10n\":{\"slide\":\"Slide\",\"score\":\"Score\",\"yourScore\":\"Your Score\",\"maxScore\":\"Max Score\",\"total\":\"Total\",\"totalScore\":\"Total Score\",\"showSolutions\":\"Show solutions\",\"retry\":\"Retry\",\"exportAnswers\":\"Export text\",\"hideKeywords\":\"Hide sidebar navigation menu\",\"showKeywords\":\"Show sidebar navigation menu\",\"fullscreen\":\"Fullscreen\",\"exitFullscreen\":\"Exit fullscreen\",\"prevSlide\":\"Previous slide\",\"nextSlide\":\"Next slide\",\"currentSlide\":\"Current slide\",\"lastSlide\":\"Last slide\",\"solutionModeTitle\":\"Exit solution mode\",\"solutionModeText\":\"Solution Mode\",\"summaryMultipleTaskText\":\"Multiple tasks\",\"scoreMessage\":\"You achieved:\",\"shareFacebook\":\"Share on Facebook\",\"shareTwitter\":\"Share on Twitter\",\"shareGoogle\":\"Share on Google+\",\"summary\":\"Summary\",\"solutionsButtonTitle\":\"Show comments\",\"printTitle\":\"Print\",\"printIngress\":\"How would you like to print this presentation?\",\"printAllSlides\":\"Print all slides\",\"printCurrentSlide\":\"Print current slide\",\"noTitle\":\"No title\",\"accessibilitySlideNavigationExplanation\":\"Use left and right arrow to change slide in that direction whenever canvas is selected.\",\"accessibilityCanvasLabel\":\"Presentation canvas. Use left and right arrow to move between slides.\",\"containsNotCompleted\":\"@slideName contains not completed interaction\",\"containsCompleted\":\"@slideName contains completed interaction\",\"slideCount\":\"Slide @index of @total\",\"containsOnlyCorrect\":\"@slideName only has correct answers\",\"containsIncorrectAnswers\":\"@slideName has incorrect answers\",\"shareResult\":\"Share Result\",\"accessibilityTotalScore\":\"You got @score of @maxScore points in total\",\"accessibilityEnteredFullscreen\":\"Entered fullscreen\",\"accessibilityExitedFullscreen\":\"Exited fullscreen\"}}', 1761797772, 1761797772);
INSERT INTO `mdl_h5p` (`id`, `jsoncontent`, `mainlibraryid`, `displayoptions`, `pathnamehash`, `contenthash`, `filtered`, `timecreated`, `timemodified`) VALUES
(4, '{\"showCoverPage\":true,\"bookCover\":{\"coverDescription\":\"<p>Browse the book of berries<\\/p>\\n\",\"coverImage\":{\"path\":\"images\\/coverImage-5eeca85d1c7b8.jpeg\",\"mime\":\"image\\/jpeg\",\"copyright\":{\"license\":\"U\"},\"width\":2250,\"height\":1500},\"coverAltText\":\"Bowl of berries\"},\"chapters\":[{\"params\":{\"content\":[{\"content\":{\"params\":{\"contentName\":\"Image\",\"file\":{\"path\":\"images\\/file-5eecbc7ecafb0.jpg\",\"mime\":\"image\\/jpeg\",\"copyright\":{\"license\":\"U\"},\"width\":2028,\"height\":444},\"alt\":\"Strawberries header\"},\"library\":\"H5P.Image 1.1\",\"metadata\":{\"contentType\":\"Image\",\"license\":\"U\",\"title\":\"Untitled Image\"},\"subContentId\":\"aa822251-c18a-42f8-a738-e2353bffb0ed\"},\"useSeparator\":\"auto\"},{\"content\":{\"params\":{\"text\":\"<h2>Strawberries<\\/h2>\\n\\n<p><br>\\nThe garden strawberry is a widely grown hybrid species of the genus Fragaria, collectively known as the strawberries, which are cultivated worldwide for their fruit. The fruit is widely appreciated for its characteristic aroma, bright red color, juicy texture, and sweetness<\\/p>\\n\"},\"library\":\"H5P.AdvancedText 1.1\",\"metadata\":{\"contentType\":\"Text\",\"license\":\"U\",\"title\":\"Untitled Text\"},\"subContentId\":\"2f7f1d68-e61c-4069-991a-955f2c9d7864\"},\"useSeparator\":\"auto\"},{\"content\":{\"params\":{\"iconType\":\"icon\",\"icon\":\"plus\",\"color\":\"#ec2b14\",\"hotspots\":[{\"position\":{\"x\":31.534569983137,\"y\":24.233291059},\"alwaysFullscreen\":false,\"content\":[{\"params\":{\"text\":\"<p>Strawberry cultivars vary widely in size, color, flavor, shape, degree of fertility, season of ripening, liability to disease and constitution of plant. On average, a strawberry has about 200 seeds on its external membrane.&nbsp;Some vary in foliage, and some vary materially in the relative development of their sexual organs. In most cases, the flowers appear hermaphroditic in structure, but function as either male or female.&nbsp;For purposes of commercial production, plants are propagated from runners and, in general, distributed as either bare root plants or plugs. Cultivation follows one of two general models\\u2014annual plasticulture,&nbsp;or a perennial system of matted rows or mounds.&nbsp;Greenhouses produce a small amount of strawberries during the off season.<\\/p>\\n\\n<p>The bulk of modern commercial production uses the plasticulture system. In this method, raised beds are formed each year,&nbsp;fumigated, and covered with plastic to prevent weed growth and erosion. Plants, usually obtained from northern nurseries, are planted through holes punched in this covering, and irrigation tubing is run underneath. Runners are removed from the plants as they appear, in order to encourage the plants to put most of their energy into fruit development. At the end of the harvest season, the plastic is removed and the plants are plowed into the ground.<\\/p>\\n\\n<p>Because strawberry plants more than a year or two old begin to decline in productivity and fruit quality, this system of replacing the plants each year allows for improved yields and denser plantings.&nbsp;However, because it requires a longer growing season to allow for establishment of the plants each year, and because of the increased costs in terms of forming and covering the mounds and purchasing plants each year, it is not always practical in all areas.<\\/p>\\n\\n<p>The other major method, which uses the same plants from year to year growing in rows or on mounds, is most common in colder climates.&nbsp;It has lower investment costs, and lower overall maintenance requirements.&nbsp;Yields are typically lower than in plasticulture.<\\/p>\\n\\n<p>Another method uses a compost sock. Plants grown in compost socks have been shown to produce significantly higher oxygen radical absorbance capacity (ORAC),&nbsp;flavonoids,&nbsp;anthocyanins,&nbsp;fructose,&nbsp;glucose,&nbsp;sucrose,&nbsp;malic acid, and citric acid than fruit produced in the black plastic mulch or matted row systems.&nbsp;Similar results in an earlier 2003 study conducted by the US Dept of Agriculture, at the Agricultural Research Service, in Beltsville Maryland, confirms how compost plays a role in the bioactive qualities of two strawberry cultivars.<\\/p>\\n\\n<p>Strawberries are often grouped according to their flowering habit. Traditionally, this has consisted of a division between \\\"June-bearing\\\" strawberries, which bear their fruit in the early summer and \\\"ever-bearing\\\" strawberries, which often bear several crops of fruit throughout the season.&nbsp;One plant throughout a season may produce 50 to 60 times or roughly once every three days.<\\/p>\\n\\n<p>Research published in 2001 showed that strawberries actually occur in three basic flowering habits: short-day, long-day, and day-neutral. These refer to the day-length sensitivity of the plant and the type of photoperiod that induces flower formation. Day-neutral cultivars produce flowers regardless of the photoperiod.<\\/p>\\n\\n<p>Strawberries may also be propagated by seed, though this is primarily a hobby activity, and is not widely practiced commercially. A few seed-propagated cultivars have been developed for home use, and research into growing from seed commercially is ongoing.&nbsp;Seeds (achenes) are acquired either via commercial seed suppliers, or by collecting and saving them from the fruit.<\\/p>\\n\\n<p>Strawberries can also be grown indoors in strawberry pots.&nbsp;Although the plant may not naturally grow indoors in the winter, use of LED lighting in combination of blue and red light can allow the plant to grow during the winter.&nbsp;Additionally, in certain areas like the state of Florida, winter is the natural growing season where harvesting starts in mid-November.<\\/p>\\n\\n<p>In continental Europe, particularly in Ukraine, strawberry harvesting in hoophouses is widespread.<\\/p>\\n\\n<h3>&nbsp;<\\/h3>\\n\\n<h3>Manuring and harvesting<\\/h3>\\n\\n<p>A diorama created from beeswax by Dr. Henry Brainerd Wright at the Louisiana State Exhibit Museum in Shreveport, Louisiana, depicts strawberry harvesting. Strawberries are particularly grown in the southeastern portion of the state around Hammond.<\\/p>\\n\\n<p>Most strawberry plants are now fed with artificial fertilizers, both before and after harvesting, and often before planting in plasticulture.<\\/p>\\n\\n<p>To maintain top quality, berries are harvested at least every other day. The berries are picked with the caps still attached and with at least half an inch of stem left. Strawberries need to remain on the plant to fully ripen because they do not continue to ripen after being picked. Rotted and overripe berries are removed to minimize insect and disease problems. The berries do not get washed until just before consumption.<\\/p>\\n\\n<p>Strawberries are usually picked and placed in shallow boxes in the field.<br>\\nSoil test information and plant analysis results are used to determine fertility practices. Nitrogen fertilizer is needed at the beginning of every planting year. There are normally adequate levels of phosphorus and potash when fields have been fertilized for top yields. In order to provide more organic matter, a cover crop of wheat or rye is planted in the winter before planting the strawberries. Strawberries prefer a pH from 5.5 to 6.5, so lime is usually not applied.<\\/p>\\n\\n<p>The harvesting and cleaning process has not changed substantially over time. The delicate strawberries are still harvested by hand.&nbsp;Grading and packing often occurs in the field, rather than in a processing facility.&nbsp;In large operations, strawberries are cleaned by means of water streams and shaking conveyor belts.<\\/p>\\n\\n<h3>&nbsp;<\\/h3>\\n\\n<h3>Diseases<\\/h3>\\n\\n<p>Strawberry plants can fall victim to a number of diseases, especially when subjected to stress.&nbsp;The leaves may be infected by powdery mildew,&nbsp;leaf spot (caused by the fungus Sphaerella fragariae),&nbsp;leaf blight (caused by the fungus Phomopsis obscurans), and by a variety of slime molds.&nbsp;The crown and roots may fall victim to red stele,&nbsp;verticillium wilt,&nbsp;black root rot, and nematodes.&nbsp;The fruits are subject to damage from gray mold,&nbsp;rhizopus rot, and leather rot.&nbsp;To prevent root-rotting, strawberries should be planted every four to five years in a new bed, at a different site.<\\/p>\\n\\n<p>The plants can also develop disease from temperature extremes during winter.&nbsp;When watering strawberries, advice has been given to water only the roots and not the leaves, as moisture on the leaves encourages growth of fungus.<\\/p>\\n\\n<h3>&nbsp;<\\/h3>\\n\\n<h3>Domestic cultivation<\\/h3>\\n\\n<p>Strawberries are popular and rewarding plants to grow in the domestic environment, be it for consumption or exhibition purposes, almost anywhere in the world. The best time to plant is in late summer or spring. Plant in full sun or dappled shade, and in somewhat sandy soil. The addition of manure and a balanced fertilizer aids strong growth. Alternatively they can be planted in pots or special planters using compost. Fibre mats placed under each plant will protect fruits from touching the ground, and will act as a weed barrier.<\\/p>\\n\\n<p>Strawberries are tough and will survive many conditions, but during fruit formation, moisture is vital, especially if growing in containers. Moreover, protection must be provided against slugs and snails which attack the ripe fruit. The fruit matures in midsummer (wild varieties can mature earlier) and should be picked when fully ripe \\u2014 that is, the fruit is a uniform bright red colour. The selection of different varieties can extend the season in both directions.<\\/p>\\n\"},\"library\":\"H5P.Text 1.1\",\"metadata\":{\"contentType\":\"Text\",\"license\":\"U\",\"title\":\"Untitled Text\"},\"subContentId\":\"3d55f1d0-de8c-44c9-9460-66512e5806f0\"}],\"header\":\"Cultivation\"},{\"position\":{\"x\":78.414839797639,\"y\":48.384858086881},\"alwaysFullscreen\":false,\"content\":[{\"params\":{\"text\":\"<p>The very first garden strawberry was grown in Brittany,&nbsp;France, during the late 18th century.&nbsp;Prior to this,&nbsp;wild strawberries and cultivated selections from wild strawberry species were the common source of the fruit.<\\/p>\\n\\n<p>The strawberry fruit was mentioned in ancient Roman literature in reference to its medicinal use. The French began taking the strawberry from the forest to their gardens for harvest in the 14th century.&nbsp;Charles V, France\'s king from 1364 to 1380, had 1,200 strawberry plants in his royal garden. In the early 15th century western European monks were using the wild strawberry in their illuminated manuscripts. The strawberry is found in Italian, Flemish, and German art, and in English miniatures.&nbsp;The entire strawberry plant was used to treat depressive illnesses.<\\/p>\\n\\n<p>By the 16th century, references of cultivation of the strawberry became more common. People began using it for its supposed medicinal properties and botanists began naming the different species. In England the demand for regular strawberry farming had increased by the mid-16th century.<\\/p>\\n\\n<p>The combination of strawberries and cream was created by Thomas Wolsey in the court of King Henry VIII.&nbsp;Instructions for growing and harvesting strawberries showed up in writing in 1578. By the end of the 16th century three European species had been cited:&nbsp;F. vesca,&nbsp;F. moschata, and F. viridis. The garden strawberry was transplanted from the forests and then the plants would be propagated asexually by cutting off the runners.<\\/p>\\n\\n<p>Two subspecies of F. vesca were identified:&nbsp;F. sylvestris alba and F. sylvestris semperflorens. The introduction of F. virginiana from Eastern North America to Europe in the 17th century is an important part of history because this species gave rise to the modern strawberry. The new species gradually spread through the continent and did not become completely appreciated until the end of the 18th century. When a French excursion journeyed to Chile in 1712, it introduced the North American strawberry plant with female flowers that resulted in the common strawberry that we have today.<\\/p>\\n\\n<p>The Mapuche and Huilliche Indians of Chile cultivated the female strawberry species until 1551, when the Spanish came to conquer the land. In 1765, a European explorer recorded the cultivation of F. chiloensis, the Chilean strawberry. At first introduction to Europe, the plants grew vigorously but produced no fruit. It was discovered in 1766 that the female plants could only be pollinated by plants that produced large fruit:&nbsp;F. moschata,&nbsp;F. virginiana, and F. ananassa. This is when the Europeans became aware that plants had the ability to produce male-only or female-only flowers. As more large-fruit producing plants were cultivated the Chilean strawberry slowly decreased in population in Europe, except for around Brest where the Chilean strawberry thrived. The decline of the Chilean strawberry was caused by F. ananassa.<\\/p>\\n\"},\"library\":\"H5P.Text 1.1\",\"metadata\":{\"contentType\":\"Text\",\"license\":\"U\",\"title\":\"Untitled Text\"},\"subContentId\":\"877d0be7-c2f2-4b6a-ac82-0b379907583b\"}],\"header\":\"History\"},{\"position\":{\"x\":34.738617200675,\"y\":80.178679940554},\"alwaysFullscreen\":false,\"content\":[{\"params\":{\"text\":\"<h3>Strawberries and cream<\\/h3>\\n\\n<p>In addition to being consumed fresh, strawberries can be frozen or made into jam or preserves,&nbsp;as well as dried and used in prepared foods, such as cereal bars.&nbsp;Strawberries and strawberry flavorings are a popular addition to dairy products, such as strawberry milk,&nbsp;strawberry ice cream,&nbsp;strawberry milkshakes\\/smoothies and strawberry yogurts.<\\/p>\\n\\n<p>In the United Kingdom, \\\"strawberries and cream\\\" is a popular dessert consumed at the Wimbledon tennis tournament.&nbsp;Strawberries and cream is also a staple snack in Mexico, usually available at ice cream parlors. In Sweden, strawberries are a traditional dessert served on St John\'s Day, also known as Midsummer\'s Eve. Depending on area,&nbsp;strawberry pie,&nbsp;strawberry rhubarb pie, or strawberry shortcake are also common. In Greece, strawberries may be sprinkled with sugar and then dipped in Metaxa, a brandy, and served as a dessert. In Italy, strawberries are used for various desserts and as a common flavoring for gelato (gelato alla fragola).<\\/p>\\n\"},\"library\":\"H5P.Text 1.1\",\"metadata\":{\"contentType\":\"Text\",\"license\":\"U\",\"title\":\"Untitled Text\"},\"subContentId\":\"570ebd7d-0b0f-42de-b3ff-bb4894cb8611\"},{\"params\":{\"text\":\"<h3>Strawberry milkshake<\\/h3>\\n\\n<ul>\\n\\t<li>Blend half of strawberries, <strong>1\\/4 tsp<\\/strong>. vanilla, <strong>1 cup<\\/strong> ice cream and <strong>2 Tbsp<\\/strong>. milk in blender until smooth.<\\/li>\\n\\t<li>Pour into 2 glasses.<\\/li>\\n\\t<li>Repeat with remaining strawberries, vanilla, ice cream and milk.<\\/li>\\n\\t<li>Serve immediately.<\\/li>\\n<\\/ul>\\n\"},\"library\":\"H5P.Text 1.1\",\"metadata\":{\"contentType\":\"Text\",\"license\":\"U\",\"title\":\"Untitled Text\"},\"subContentId\":\"09e65354-c951-4e68-855b-64b7d51bea40\"}],\"header\":\"Culinary\"}],\"hotspotNumberLabel\":\"Hotspot #num\",\"closeButtonLabel\":\"Close\",\"image\":{\"path\":\"images\\/image-5efc479aa54d6.PNG\",\"mime\":\"image\\/png\",\"copyright\":{\"license\":\"U\"},\"width\":1581,\"height\":972},\"backgroundImageAltText\":\"Strawberries chart\"},\"library\":\"H5P.ImageHotspots 1.8\",\"metadata\":{\"contentType\":\"Image Hotspots\",\"license\":\"U\",\"title\":\"Untitled Image Hotspots\"},\"subContentId\":\"5d98084a-95c3-4494-bcf3-aedb608816f6\"},\"useSeparator\":\"auto\"},{\"content\":{\"library\":\"H5P.Table 1.1\",\"params\":{\"text\":\"<div><span style=\\\"color:#dd300e;\\\"><strong>Nutrition Facts<\\/strong><\\/span><\\/div>\\n\\n<div>\\n<table border=\\\"1\\\" cellpadding=\\\"5\\\" cellspacing=\\\"0\\\" class=\\\"h5p-table\\\">\\n\\t<thead>\\n\\t<\\/thead>\\n\\t<tbody>\\n\\t\\t<tr>\\n\\t\\t\\t<td><strong>Amount per<\\/strong><\\/td>\\n\\t\\t\\t<td>100 gr<\\/td>\\n\\t\\t<\\/tr>\\n\\t\\t<tr>\\n\\t\\t\\t<td><strong>Calories<\\/strong><\\/td>\\n\\t\\t\\t<td>33<\\/td>\\n\\t\\t<\\/tr>\\n\\t\\t<tr>\\n\\t\\t\\t<td><strong>Total fat<\\/strong><\\/td>\\n\\t\\t\\t<td>0.3 g<\\/td>\\n\\t\\t<\\/tr>\\n\\t\\t<tr>\\n\\t\\t\\t<td><strong>Cholesterol<\\/strong><\\/td>\\n\\t\\t\\t<td>0 mg<\\/td>\\n\\t\\t<\\/tr>\\n\\t\\t<tr>\\n\\t\\t\\t<td><strong>Sodium<\\/strong><\\/td>\\n\\t\\t\\t<td>1mg<\\/td>\\n\\t\\t<\\/tr>\\n\\t\\t<tr>\\n\\t\\t\\t<td><strong>Potassium<\\/strong><\\/td>\\n\\t\\t\\t<td>153mg<\\/td>\\n\\t\\t<\\/tr>\\n\\t\\t<tr>\\n\\t\\t\\t<td><strong>Total Carbohydrate<\\/strong><\\/td>\\n\\t\\t\\t<td>8g<\\/td>\\n\\t\\t<\\/tr>\\n\\t\\t<tr>\\n\\t\\t\\t<td><strong>Protein<\\/strong><\\/td>\\n\\t\\t\\t<td>0.7g<\\/td>\\n\\t\\t<\\/tr>\\n\\t<\\/tbody>\\n<\\/table>\\n\\n<div><br>\\n<span style=\\\"color:#dd300e;\\\"><strong>Vitamins<\\/strong><\\/span><\\/div>\\n\\n<div>\\n<table border=\\\"1\\\" cellpadding=\\\"5\\\" cellspacing=\\\"0\\\">\\n\\t<tbody>\\n\\t\\t<tr>\\n\\t\\t\\t<td><strong>Vitamin A<\\/strong><\\/td>\\n\\t\\t\\t<td>0%<\\/td>\\n\\t\\t\\t<td><strong>Vitamin C<\\/strong><\\/td>\\n\\t\\t\\t<td>97%<\\/td>\\n\\t\\t<\\/tr>\\n\\t\\t<tr>\\n\\t\\t\\t<td><strong>Calcium<\\/strong><\\/td>\\n\\t\\t\\t<td>1%<\\/td>\\n\\t\\t\\t<td><strong>Iron<\\/strong><\\/td>\\n\\t\\t\\t<td>2%<\\/td>\\n\\t\\t<\\/tr>\\n\\t\\t<tr>\\n\\t\\t\\t<td><strong>Vitalin D<\\/strong><\\/td>\\n\\t\\t\\t<td>0%<\\/td>\\n\\t\\t\\t<td>\\n\\t\\t\\t<table>\\n\\t\\t\\t\\t<tbody>\\n\\t\\t\\t\\t\\t<tr>\\n\\t\\t\\t\\t\\t\\t<td role=\\\"listitem\\\"><strong>Vitamin B-6<\\/strong><\\/td>\\n\\t\\t\\t\\t\\t<\\/tr>\\n\\t\\t\\t\\t<\\/tbody>\\n\\t\\t\\t<\\/table>\\n\\t\\t\\t<\\/td>\\n\\t\\t\\t<td>0%<\\/td>\\n\\t\\t<\\/tr>\\n\\t\\t<tr>\\n\\t\\t\\t<td><strong>Cobalamin<\\/strong><\\/td>\\n\\t\\t\\t<td>0%<\\/td>\\n\\t\\t\\t<td><strong>Magnesium<\\/strong><\\/td>\\n\\t\\t\\t<td>\\n\\t\\t\\t<div>3%<\\/div>\\n\\t\\t\\t<\\/td>\\n\\t\\t<\\/tr>\\n\\t<\\/tbody>\\n<\\/table>\\n\\n<div>&nbsp;<\\/div>\\n<\\/div>\\n<\\/div>\\n\"},\"metadata\":{\"contentType\":\"Table\",\"license\":\"CC BY-SA\",\"title\":\"Wikipedia: Nutrition facts about strawberries\",\"authors\":[{\"name\":\"Wikipedia\",\"role\":\"Author\"}],\"licenseVersion\":\"3.0\",\"source\":\"https:\\/\\/en.wikipedia.org\\/wiki\\/Strawberry\"},\"subContentId\":\"28c3c35d-ba20-48ab-a315-07fa2a181303\"},\"useSeparator\":\"auto\"},{\"content\":{\"library\":\"H5P.SingleChoiceSet 1.11\",\"params\":{\"choices\":[{\"answers\":[\"<p>Brittany,&nbsp;France<\\/p>\\n\",\"<p>London,&nbsp;UK<\\/p>\\n\",\"<p>Vienna, Austria<\\/p>\\n\",\"<p>Lima, Peru<\\/p>\\n\"],\"question\":\"<p>The very first garden strawberry was grown in:<\\/p>\\n\",\"subContentId\":\"0a5f12b1-c025-4a19-9771-d31d58511438\"},{\"answers\":[\"<p>the 14th century<\\/p>\\n\",\"<p>the 12th century<\\/p>\\n\",\"<p>the 16th century<\\/p>\\n\",\"<p>the 18th century<\\/p>\\n\"],\"question\":\"<p>The French began taking the strawberry from the forest to their gardens for harvest in:<\\/p>\\n\",\"subContentId\":\"bb04138f-ecf9-45ea-a2ac-735f8797e7a9\"},{\"answers\":[\"<p>Potassium<\\/p>\\n\",\"<p>Cholesterol<\\/p>\\n\",\"<p>Sodium<\\/p>\\n\",\"<p>Vitamin D<\\/p>\\n\"],\"question\":\"<p>Strawberries are very rich with:<\\/p>\\n\",\"subContentId\":\"5bbb8c42-699a-4d4d-aa4e-5dd8f876bf4a\"}],\"behaviour\":{\"timeoutCorrect\":0,\"timeoutWrong\":0,\"soundEffectsEnabled\":true,\"enableRetry\":true,\"enableSolutionsButton\":true,\"passPercentage\":100,\"autoContinue\":false},\"l10n\":{\"showSolutionButtonLabel\":\"Show solution\",\"retryButtonLabel\":\"Retry\",\"solutionViewTitle\":\"Solution\",\"correctText\":\"Correct!\",\"incorrectText\":\"Incorrec