(11, 'H5P.DragQuestion', 'Drag and Drop', 1, 13, 11, 1, 0, 'iframe', 'h5p-drag-question.js', 'css/dragquestion.css', '', '[\n  {\n    \"name\": \"scoreShow\",\n    \"type\": \"text\",\n    \"label\": \"Check answer button\",\n    \"importance\": \"low\",\n    \"default\": \"Check\",\n    \"common\": true\n  },\n  {\n    \"name\": \"tryAgain\",\n    \"type\": \"text\",\n    \"label\": \"Retry button\",\n    \"importance\": \"low\",\n    \"default\": \"Retry\",\n    \"common\": true,\n    \"optional\": true\n  },\n  {\n    \"label\": \"Score explanation text\",\n    \"importance\": \"low\",\n    \"name\": \"scoreExplanation\",\n    \"type\": \"text\",\n    \"default\": \"Correct answers give +1 point. Incorrect answers give -1 point. The lowest possible score is 0.\",\n    \"common\": true,\n    \"optional\": true\n  },\n  {\n    \"name\": \"question\",\n    \"importance\": \"high\",\n    \"type\": \"group\",\n    \"widget\": \"wizard\",\n    \"fields\": [\n      {\n        \"name\": \"settings\",\n        \"type\": \"group\",\n        \"label\": \"Settings\",\n        \"importance\": \"high\",\n        \"fields\": [\n          {\n            \"name\": \"background\",\n            \"type\": \"image\",\n            \"label\": \"Background image\",\n            \"importance\": \"low\",\n            \"optional\": true,\n            \"description\": \"Optional. Select an image to use as background for your drag and drop task.\"\n          },\n          {\n            \"name\": \"size\",\n            \"type\": \"group\",\n            \"widget\": \"dimensions\",\n            \"label\": \"Task size\",\n            \"importance\": \"low\",\n            \"description\": \"Specify how large (in px) the play area should be.\",\n            \"default\": {\n              \"width\": 620,\n              \"height\": 310,\n              \"field\": \"background\"\n            },\n            \"fields\": [\n              {\n                \"name\": \"width\",\n                \"type\": \"number\"\n              },\n              {\n                \"name\": \"height\",\n                \"type\": \"number\"\n              }\n            ]\n          }\n        ]\n      },\n      {\n        \"name\": \"task\",\n        \"type\": \"group\",\n        \"widget\": \"dragQuestion\",\n        \"label\": \"Task\",\n        \"importance\": \"high\",\n        \"description\": \"Start by placing your drop zones.<br/>Next, place your droppable elements and check off the appropriate drop zones.<br/>Last, edit your drop zone again and check off the correct answers.\",\n        \"fields\": [\n          {\n            \"name\": \"elements\",\n            \"type\": \"list\",\n            \"label\": \"Elements\",\n            \"importance\": \"high\",\n            \"entity\": \"element\",\n            \"field\": {\n              \"type\": \"group\",\n              \"label\": \"Element\",\n              \"importance\": \"high\",\n              \"fields\": [\n                {\n                  \"name\": \"type\",\n                  \"type\": \"library\",\n                  \"description\": \"Choose the type of content you would like to add.\",\n                  \"importance\": \"medium\",\n                  \"options\": [\n                      \"H5P.AdvancedText 1.1\",\n                      \"H5P.Image 1.1\"\n                  ]\n                },\n                {\n                  \"name\": \"x\",\n                  \"type\": \"number\",\n                  \"widget\": \"none\"\n                },\n                {\n                  \"name\": \"y\",\n                  \"type\": \"number\",\n                  \"widget\": \"none\"\n                },\n                {\n                  \"name\": \"height\",\n                  \"type\": \"number\",\n                  \"widget\": \"none\"\n                },\n                {\n                  \"name\": \"width\",\n                  \"type\": \"number\",\n                  \"widget\": \"none\"\n                },\n                {\n                  \"name\": \"dropZones\",\n                  \"type\": \"select\",\n                  \"widget\": \"dynamicCheckboxes\",\n                  \"label\": \"Select drop zones\",\n                  \"importance\": \"high\",\n                  \"multiple\": true\n                },\n                {\n                  \"name\": \"backgroundOpacity\",\n                  \"type\": \"number\",\n                  \"label\": \"Background Opacity\",\n                  \"importance\": \"low\",\n                  \"min\": 0,\n                  \"max\": 100,\n                  \"step\": 5,\n                  \"default\": 100,\n                  \"optional\": true\n                },\n                {\n                  \"name\": \"multiple\",\n                  \"type\": \"boolean\",\n                  \"label\": \"Infinite number of element instances\",\n                  \"importance\": \"low\",\n                  \"description\": \"Clones this element so that it can be dragged to multiple drop zones.\",\n                  \"default\": false\n                }\n              ]\n            }\n          },\n          {\n            \"name\": \"dropZones\",\n            \"type\": \"list\",\n            \"label\": \"Drop Zones\",\n            \"importance\": \"high\",\n            \"entity\": \"Drop Zone\",\n            \"field\": {\n              \"type\": \"group\",\n              \"label\": \"Drop Zone\",\n              \"importance\": \"high\",\n              \"fields\": [\n                {\n                  \"name\": \"label\",\n                  \"type\": \"text\",\n                  \"widget\": \"html\",\n                  \"label\": \"Label\",\n                  \"importance\": \"medium\",\n                  \"enterMode\": \"div\",\n                  \"tags\": [\n                    \"strong\",\n                    \"em\",\n                    \"del\",\n                    \"code\"\n                  ]\n                },\n                {\n                  \"name\": \"showLabel\",\n                  \"type\": \"boolean\",\n                  \"label\": \"Show label\",\n                  \"importance\": \"low\"\n                },\n                {\n                  \"name\": \"x\",\n                  \"type\": \"number\",\n                  \"widget\": \"none\"\n                },\n                {\n                  \"name\": \"y\",\n                  \"type\": \"number\",\n                  \"widget\": \"none\"\n                },\n                {\n                  \"name\": \"height\",\n                  \"type\": \"number\",\n                  \"widget\": \"none\"\n                },\n                {\n                  \"name\": \"width\",\n                  \"type\": \"number\",\n                  \"widget\": \"none\"\n                },\n                {\n                  \"name\": \"correctElements\",\n                  \"type\": \"select\",\n                  \"widget\": \"dynamicCheckboxes\",\n                  \"label\": \"Select correct elements\",\n                  \"importance\": \"low\",\n                  \"multiple\": true\n                },\n                {\n                  \"name\": \"backgroundOpacity\",\n                  \"type\": \"number\",\n                  \"label\": \"Background Opacity\",\n                  \"importance\": \"low\",\n                  \"min\": 0,\n                  \"max\": 100,\n                  \"step\": 5,\n                  \"default\": 100,\n                  \"optional\": true\n                },\n                {\n                  \"name\": \"tipsAndFeedback\",\n                  \"type\": \"group\",\n                  \"label\": \"Tips and feedback\",\n                  \"importance\": \"low\",\n                  \"optional\": true,\n                  \"fields\": [\n                    {\n                      \"name\": \"tip\",\n                      \"label\": \"Tip text\",\n                      \"importance\": \"low\",\n                      \"type\": \"text\",\n                      \"widget\": \"html\",\n                      \"tags\": [\n                        \"p\",\n                        \"br\",\n                        \"strong\",\n                        \"em\",\n                        \"code\"\n                      ],\n                      \"optional\": true\n                    },\n                    {\n                      \"name\": \"feedbackOnCorrect\",\n                      \"type\": \"text\",\n                      \"label\": \"Message displayed on correct match\",\n                      \"importance\": \"low\",\n                      \"description\": \"Message will appear below the task on \\\"check\\\" if correct droppable is matched.\",\n                      \"optional\": true\n                    },\n                    {\n                      \"name\": \"feedbackOnIncorrect\",\n                      \"type\": \"text\",\n                      \"label\": \"Message displayed on incorrect match\",\n                      \"importance\": \"low\",\n                      \"description\": \"Message will appear below the task on \\\"check\\\" if the match is incorrect.\",\n                      \"optional\": true\n                    }\n                  ]\n                },\n                {\n                  \"name\": \"single\",\n                  \"type\": \"boolean\",\n                  \"label\": \"This drop zone can only contain one element\",\n                  \"description\": \"Make sure there is only one correct answer for this dropzone\",\n                  \"importance\": \"low\",\n                  \"default\": false\n                },\n                {\n                  \"name\": \"autoAlign\",\n                  \"type\": \"boolean\",\n                  \"label\": \"Enable Auto-Align\",\n                  \"importance\": \"low\",\n                  \"description\": \"Will auto-align all draggables dropped in this zone.\"\n                }\n              ]\n            }\n          }\n        ]\n      }\n    ]\n  },\n  {\n    \"name\": \"overallFeedback\",\n    \"type\": \"group\",\n    \"label\": \"Overall Feedback\",\n    \"importance\": \"low\",\n    \"expanded\": true,\n    \"fields\": [\n      {\n        \"name\": \"overallFeedback\",\n        \"type\": \"list\",\n        \"widgets\": [\n          {\n            \"name\": \"RangeList\",\n            \"label\": \"Default\"\n          }\n        ],\n        \"importance\": \"high\",\n        \"label\": \"Define custom feedback for any score range\",\n        \"description\": \"Click the \\\"Add range\\\" button to add as many ranges as you need. Example: 0-20% Bad score, 21-91% Average Score, 91-100% Great Score!\",\n        \"entity\": \"range\",\n        \"min\": 1,\n        \"defaultNum\": 1,\n        \"optional\": true,\n        \"field\": {\n          \"name\": \"overallFeedback\",\n          \"type\": \"group\",\n          \"importance\": \"low\",\n          \"fields\": [\n            {\n              \"name\": \"from\",\n              \"type\": \"number\",\n              \"label\": \"Score Range\",\n              \"min\": 0,\n              \"max\": 100,\n              \"default\": 0,\n              \"unit\": \"%\"\n            },\n            {\n              \"name\": \"to\",\n              \"type\": \"number\",\n              \"min\": 0,\n              \"max\": 100,\n              \"default\": 100,\n              \"unit\": \"%\"\n            },\n            {\n              \"name\": \"feedback\",\n              \"type\": \"text\",\n              \"label\": \"Feedback for defined score range\",\n              \"importance\": \"low\",\n              \"placeholder\": \"Fill in the feedback\",\n              \"optional\": true\n            }\n          ]\n        }\n      }\n    ]\n  },\n  {\n    \"name\": \"behaviour\",\n    \"type\": \"group\",\n    \"label\": \"Behavioural settings\",\n    \"importance\": \"low\",\n    \"description\": \"These options will let you control how the task behaves.\",\n    \"optional\": true,\n    \"fields\": [\n      {\n        \"name\": \"enableRetry\",\n        \"type\": \"boolean\",\n        \"label\": \"Enable \\\"Retry\\\"\",\n        \"importance\": \"low\",\n        \"default\": true\n      },\n      {\n        \"name\": \"enableCheckButton\",\n        \"type\": \"boolean\",\n        \"label\": \"Enable \\\"Check\\\" button\",\n        \"widget\": \"none\",\n        \"importance\": \"low\",\n        \"default\": true,\n        \"optional\": true\n      },\n      {\n        \"label\": \"Require user input before the solution can be viewed\",\n        \"importance\": \"low\",\n        \"name\": \"showSolutionsRequiresInput\",\n        \"type\": \"boolean\",\n        \"default\": true\n      },\n      {\n        \"name\": \"singlePoint\",\n        \"type\": \"boolean\",\n        \"label\": \"Give one point for the whole task\",\n        \"importance\": \"low\",\n        \"description\": \"Disable to give one point for each draggable that is placed correctly.\",\n        \"default\": false\n      },\n      {\n        \"label\": \"Apply penalties\",\n        \"name\": \"applyPenalties\",\n        \"type\": \"boolean\",\n        \"description\": \"Apply penalties for elements dropped in the wrong drop zones. This must be enabled when the same element(s) are able to be dropped into multiple drop zones, or if there is only one drop-zone. If this is not enabled, learners may match all items to all drop-zones and always receive a full score.\",\n        \"default\": true\n      },\n      {\n        \"name\": \"enableScoreExplanation\",\n        \"type\": \"boolean\",\n        \"label\": \"Enable score explanation\",\n        \"description\": \"Display a score explanation to user when checking their answers (if the \'Apply penalties\' option has been selected).\",\n        \"importance\": \"low\",\n        \"default\": true,\n        \"optional\": true,\n        \"widget\": \"showWhen\",\n        \"showWhen\": {\n          \"rules\": [\n            {\n              \"field\": \"singlePoint\",\n              \"equals\": false\n            }\n          ]\n        }\n      },\n      {\n        \"name\": \"backgroundOpacity\",\n        \"type\": \"text\",\n        \"label\": \"Background opacity for draggables\",\n        \"importance\": \"low\",\n        \"description\": \"If this field is set, it will override opacity set on all draggable elements. This should be a number between 0 and 100, where 0 means full transparency and 100 means no transparency\",\n        \"optional\": true\n      },\n      {\n        \"name\": \"dropZoneHighlighting\",\n        \"type\": \"select\",\n        \"label\": \"Drop Zone Highlighting\",\n        \"importance\": \"low\",\n        \"description\": \"Choose when to highlight drop zones.\",\n        \"default\": \"dragging\",\n        \"options\": [\n          {\n            \"value\": \"dragging\",\n            \"label\": \"When dragging\"\n          },\n          {\n            \"value\": \"always\",\n            \"label\": \"Always\"\n          },\n          {\n            \"value\": \"never\",\n            \"label\": \"Never\"\n          }\n        ]\n      },\n      {\n        \"name\": \"autoAlignSpacing\",\n        \"type\": \"number\",\n        \"label\": \"Spacing for Auto-Align (in px)\",\n        \"importance\": \"low\",\n        \"min\": 0,\n        \"default\": 2,\n        \"optional\": true\n      },\n      {\n        \"name\": \"enableFullScreen\",\n        \"label\": \"Enable FullScreen\",\n        \"importance\": \"low\",\n        \"type\": \"boolean\",\n        \"description\": \"Check this option to enable the full screen button.\",\n        \"default\": false\n      },\n      {\n        \"name\": \"showScorePoints\",\n        \"type\": \"boolean\",\n        \"label\": \"Show score points\",\n        \"description\": \"Show points earned for each answer. Not available when the \'Give one point for the whole task\' option is enabled.\",\n        \"importance\": \"low\",\n        \"default\": true\n      },\n      {\n        \"name\": \"showTitle\",\n        \"type\": \"boolean\",\n        \"label\": \"Show Title\",\n        \"importance\": \"low\",\n        \"description\": \"Uncheck this option if you do not want this title to be displayed. The title will only be displayed in summaries, statistics etc.\",\n        \"default\": true\n      }\n    ]\n  },\n  {\n    \"name\": \"localize\",\n    \"type\": \"group\",\n    \"label\": \"Localize\",\n    \"common\": true,\n    \"fields\": [\n      {\n        \"name\": \"fullscreen\",\n        \"type\": \"text\",\n        \"label\": \"Fullscreen label\",\n        \"default\": \"Fullscreen\"\n      },\n      {\n        \"name\": \"exitFullscreen\",\n        \"type\": \"text\",\n        \"label\": \"Exit fullscreen label\",\n        \"default\": \"Exit fullscreen\"\n      }\n    ]\n  },\n  {\n    \"name\": \"grabbablePrefix\",\n    \"type\": \"text\",\n    \"label\": \"Grabbable prefix\",\n    \"importance\": \"low\",\n    \"default\": \"Grabbable {num} of {total}.\",\n    \"common\": true\n  },\n  {\n    \"name\": \"grabbableSuffix\",\n    \"type\": \"text\",\n    \"label\": \"Grabbable suffix\",\n    \"importance\": \"low\",\n    \"default\": \"Placed in dropzone {num}.\",\n    \"common\": true\n  },\n  {\n    \"name\": \"dropzonePrefix\",\n    \"type\": \"text\",\n    \"label\": \"Dropzone prefix\",\n    \"importance\": \"low\",\n    \"default\": \"Dropzone {num} of {total}.\",\n    \"common\": true\n  },\n  {\n    \"name\": \"noDropzone\",\n    \"type\": \"text\",\n    \"label\": \"No dropzone selection label\",\n    \"importance\": \"low\",\n    \"default\": \"No dropzone.\",\n    \"common\": true\n  },\n  {\n    \"name\": \"tipLabel\",\n    \"type\": \"text\",\n    \"label\": \"Label for show tip button\",\n    \"importance\": \"low\",\n    \"default\": \"Show tip.\",\n    \"common\": true\n  },\n  {\n    \"name\": \"tipAvailable\",\n    \"type\": \"text\",\n    \"label\": \"Label for tip available\",\n    \"importance\": \"low\",\n    \"default\": \"Tip available\",\n    \"common\": true\n  },\n  {\n    \"name\": \"correctAnswer\",\n    \"type\": \"text\",\n    \"label\": \"Label for correct answer\",\n    \"importance\": \"low\",\n    \"default\": \"Correct answer\",\n    \"common\": true\n  },\n  {\n    \"name\": \"wrongAnswer\",\n    \"type\": \"text\",\n    \"label\": \"Label for incorrect answer\",\n    \"importance\": \"low\",\n    \"default\": \"Wrong answer\",\n    \"common\": true\n  },\n  {\n    \"name\": \"feedbackHeader\",\n    \"type\": \"text\",\n    \"label\": \"Header for panel containing feedback for correct/incorrect answers\",\n    \"importance\": \"low\",\n    \"default\": \"Feedback\",\n    \"common\": true\n  },\n  {\n    \"name\": \"scoreBarLabel\",\n    \"type\": \"text\",\n    \"label\": \"Textual representation of the score bar for those using a readspeaker\",\n    \"default\": \"You got :num out of :total points\",\n    \"importance\": \"low\",\n    \"common\": true\n  },\n  {\n    \"name\": \"scoreExplanationButtonLabel\",\n    \"type\": \"text\",\n    \"label\": \"Textual representation of the score explanation button\",\n    \"default\": \"Show score explanation\",\n    \"importance\": \"low\",\n    \"common\": true\n  }\n]\n', NULL, 1, 23, NULL, NULL, NULL, 1),
(12, 'H5P.DragText', 'Drag Text', 1, 8, 9, 1, 0, 'iframe', 'dist/h5p-drag-text.js', 'dist/h5p-drag-text.css', '', '[\n  {\n    \"label\": \"Task description\",\n    \"importance\": \"high\",\n    \"name\": \"taskDescription\",\n    \"type\": \"text\",\n    \"widget\": \"html\",\n    \"description\": \"Describe how the user should solve the task.\",\n    \"default\": \"Drag the words into the correct boxes\",\n    \"enterMode\": \"p\",\n    \"tags\": [\n      \"strong\",\n      \"em\",\n      \"u\",\n      \"a\",\n      \"ul\",\n      \"ol\",\n      \"h2\",\n      \"h3\",\n      \"hr\",\n      \"pre\",\n      \"code\"\n    ]\n  },\n  {\n    \"label\": \"Text\",\n    \"importance\": \"high\",\n    \"name\": \"textField\",\n    \"type\": \"text\",\n    \"widget\": \"textarea\",\n    \"placeholder\": \"*Oslo* is the capital of Norway, *Stockholm* is the capital of Sweden and *Copenhagen* is the capital of Denmark. All cities are located in the *Scandinavian:Northern Part of Europe* peninsula.\",\n    \"description\": \"\",\n    \"important\": {\n      \"description\": \"<ul><li>Droppable words are added with an asterisk (*) in front and behind the correct word/phrase.</li><li>You may add a textual tip, using a colon (:) in front of the tip.</li><li>For every empty spot there is only one correct word.</li><li>You may add feedback to be displayed when a task is completed. Use \'\\\\+\' for correct and \'\\\\-\' for incorrect feedback.</li></ul>\",\n      \"example\": \"H5P content may be edited using a *browser:What type of program is Chrome?*. </br> H5P content is *interactive\\\\+Correct! \\\\-Incorrect, try again!*\"\n    }\n  },\n  {\n    \"name\": \"overallFeedback\",\n    \"type\": \"group\",\n    \"label\": \"Overall Feedback\",\n    \"importance\": \"low\",\n    \"expanded\": true,\n    \"fields\": [\n      {\n        \"name\": \"overallFeedback\",\n        \"type\": \"list\",\n        \"widgets\": [\n          {\n            \"name\": \"RangeList\",\n            \"label\": \"Default\"\n          }\n        ],\n        \"importance\": \"high\",\n        \"label\": \"Define custom feedback for any score range\",\n        \"description\": \"Click the \\\"Add range\\\" button to add as many ranges as you need. Example: 0-20% Bad score, 21-91% Average Score, 91-100% Great Score!\",\n        \"entity\": \"range\",\n        \"min\": 1,\n        \"defaultNum\": 1,\n        \"optional\": true,\n        \"field\": {\n          \"name\": \"overallFeedback\",\n          \"type\": \"group\",\n          \"importance\": \"low\",\n          \"fields\": [\n            {\n              \"name\": \"from\",\n              \"type\": \"number\",\n              \"label\": \"Score Range\",\n              \"min\": 0,\n              \"max\": 100,\n              \"default\": 0,\n              \"unit\": \"%\"\n            },\n            {\n              \"name\": \"to\",\n              \"type\": \"number\",\n              \"min\": 0,\n              \"max\": 100,\n              \"default\": 100,\n              \"unit\": \"%\"\n            },\n            {\n              \"name\": \"feedback\",\n              \"type\": \"text\",\n              \"label\": \"Feedback for defined score range\",\n              \"importance\": \"low\",\n              \"placeholder\": \"Fill in the feedback\",\n              \"optional\": true\n            }\n          ]\n        }\n      }\n    ]\n  },\n  {\n    \"label\": \"Text for \\\"Check\\\" button\",\n    \"importance\": \"low\",\n    \"name\": \"checkAnswer\",\n    \"type\": \"text\",\n    \"default\": \"Check\",\n    \"common\": true\n  },\n  {\n    \"label\": \"Text for \\\"Retry\\\" button\",\n    \"importance\": \"low\",\n    \"name\": \"tryAgain\",\n    \"type\": \"text\",\n    \"default\": \"Retry\",\n    \"common\": true\n  },\n  {\n    \"label\": \"Text for \\\"Show Solution\\\" button\",\n    \"importance\": \"low\",\n    \"name\": \"showSolution\",\n    \"type\": \"text\",\n    \"default\": \"Show solution\",\n    \"common\": true\n  },\n  {\n    \"label\": \"Numbered Drop zone label\",\n    \"importance\": \"low\",\n    \"name\": \"dropZoneIndex\",\n    \"type\": \"text\",\n    \"default\": \"Drop Zone @index.\",\n    \"description\": \"Label used for accessibility, where the Read speaker will read the index of a drop zone. Variable available: @index\",\n    \"common\": true\n  },\n  {\n    \"label\": \"Empty Drop Zone label\",\n    \"importance\": \"low\",\n    \"name\": \"empty\",\n    \"type\": \"text\",\n    \"default\": \"Drop Zone @index is empty.\",\n    \"description\": \"Label used for accessibility, where the Read speaker will read that the drop zone is empty\",\n    \"common\": true\n  },\n  {\n    \"label\": \"Contains Drop Zone label\",\n    \"importance\": \"low\",\n    \"name\": \"contains\",\n    \"type\": \"text\",\n    \"default\": \"Drop Zone @index contains draggable @draggable.\",\n    \"description\": \"Label used for accessibility, where the Read speaker will read that the drop zone contains a draggable\",\n    \"common\": true\n  },\n  {\n    \"label\": \"Draggable elements label\",\n    \"importance\": \"low\",\n    \"name\": \"ariaDraggableIndex\",\n    \"type\": \"text\",\n    \"default\": \"@index of @count draggables.\",\n    \"description\": \"Label used for accessibility, where the Read speaker reads that this is a draggable element. Variable available: @index, @count\",\n    \"common\": true\n  },\n  {\n    \"label\": \"Label for show tip button\",\n    \"importance\": \"low\",\n    \"name\": \"tipLabel\",\n    \"type\": \"text\",\n    \"default\": \"Show tip\",\n    \"description\": \"Label used for accessibility, where the Read speaker reads it before the tip is read out\",\n    \"common\": true\n  },\n  {\n    \"name\": \"correctText\",\n    \"type\": \"text\",\n    \"label\": \"Readspeaker text for correct answer\",\n    \"importance\": \"low\",\n    \"default\": \"Correct!\",\n    \"common\": true\n  },\n  {\n    \"name\": \"incorrectText\",\n    \"type\": \"text\",\n    \"label\": \"Readspeaker text for incorrect answer\",\n    \"importance\": \"low\",\n    \"default\": \"Incorrect!\",\n    \"common\": true\n  },\n  {\n    \"name\": \"resetDropTitle\",\n    \"type\": \"text\",\n    \"label\": \"Confirmation dialog title that user wants to reset a droppable\",\n    \"importance\": \"low\",\n    \"default\": \"Reset drop\",\n    \"common\": true\n  },\n  {\n    \"name\": \"resetDropDescription\",\n    \"type\": \"text\",\n    \"label\": \"Confirmation dialog description that user wants to reset a droppable\",\n    \"importance\": \"low\",\n    \"default\": \"Are you sure you want to reset this drop zone?\",\n    \"common\": true\n  },\n  {\n    \"name\": \"grabbed\",\n    \"type\": \"text\",\n    \"label\": \"Label used for accessibility, where the read speaker indicates that dragging is initiated\",\n    \"importance\": \"low\",\n    \"default\": \"Draggable is grabbed.\",\n    \"common\": true\n  },\n  {\n    \"name\": \"cancelledDragging\",\n    \"type\": \"text\",\n    \"label\": \"Label used for accessibility, where the read speaker indicates that dragging is canceled\",\n    \"importance\": \"low\",\n    \"default\": \"Cancelled dragging.\",\n    \"common\": true\n  },\n  {\n    \"name\": \"correctAnswer\",\n    \"type\": \"text\",\n    \"label\": \"Label used for accessibility, where the read speaker indicates that a text is the correct answer\",\n    \"importance\": \"low\",\n    \"default\": \"Correct answer:\",\n    \"common\": true\n  },\n  {\n    \"name\": \"feedbackHeader\",\n    \"type\": \"text\",\n    \"label\": \"Header for panel containing feedback for correct/incorrect answers\",\n    \"importance\": \"low\",\n    \"default\": \"Feedback\",\n    \"common\": true\n  },\n  {\n    \"name\": \"behaviour\",\n    \"type\": \"group\",\n    \"label\": \"Behavioural settings.\",\n    \"importance\": \"low\",\n    \"description\": \"These options will let you control how the task behaves.\",\n    \"optional\": true,\n    \"fields\": [\n      {\n        \"label\": \"Enable \\\"Retry\\\"\",\n        \"importance\": \"low\",\n        \"name\": \"enableRetry\",\n        \"type\": \"boolean\",\n        \"default\": true\n      },\n      {\n        \"label\": \"Enable \\\"Show Solution\\\" button\",\n        \"importance\": \"low\",\n        \"name\": \"enableSolutionsButton\",\n        \"type\": \"boolean\",\n        \"default\": true\n      },\n      {\n        \"name\": \"enableCheckButton\",\n        \"type\": \"boolean\",\n        \"label\": \"Enable \\\"Check\\\" button\",\n        \"widget\": \"none\",\n        \"importance\": \"low\",\n        \"default\": true,\n        \"optional\": true\n      },\n      {\n        \"label\": \"Instant feedback\",\n        \"importance\": \"low\",\n        \"name\": \"instantFeedback\",\n        \"type\": \"boolean\",\n        \"default\": false,\n        \"optional\": true\n      }\n    ]\n  },\n  {\n    \"name\": \"scoreBarLabel\",\n    \"type\": \"text\",\n    \"label\": \"Textual representation of the score bar for those using a readspeaker\",\n    \"default\": \"You got :num out of :total points\",\n    \"importance\": \"low\",\n    \"common\": true\n  }\n]\n', NULL, 1, 19, NULL, NULL, NULL, 1),
(13, 'H5P.FontIcons', 'H5P.FontIcons', 1, 0, 6, 0, 0, '', '', 'styles/h5p-font-icons.css', '', '', NULL, NULL, NULL, NULL, NULL, NULL, 1);
INSERT INTO `mdl_h5p_libraries` (`id`, `machinename`, `title`, `majorversion`, `minorversion`, `patchversion`, `runnable`, `fullscreen`, `embedtypes`, `preloadedjs`, `preloadedcss`, `droplibrarycss`, `semantics`, `addto`, `coremajor`, `coreminor`, `metadatasettings`, `tutorial`, `example`, `enabled`) VALUES
(14, 'H5P.FreeTextQuestion', 'Free Text Question', 1, 0, 16, 0, 0, '', 'h5p-free-text-question.js', 'h5p-free-text-question.css', '', '[\n  {\n    \"label\": \"Question\",\n    \"name\": \"question\",\n    \"type\": \"text\",\n    \"importance\": \"high\"\n  },\n  {\n    \"label\": \"Placeholder text\",\n    \"name\": \"placeholder\",\n    \"type\": \"text\",\n    \"importance\": \"high\",\n    \"default\": \"Enter your response here\",\n    \"description\": \"Text that initially will be shown in the input field. Will be removed automatically when the user starts writing.\"\n  },\n  {\n    \"label\": \"Max score\",\n    \"name\": \"maxScore\",\n    \"type\": \"number\",\n    \"importance\": \"high\",\n    \"description\": \"Used for grading and not shown to the learner\",\n    \"default\": 1\n  },\n  {\n    \"label\": \"Required\",\n    \"name\": \"isRequired\",\n    \"type\": \"boolean\",\n    \"importance\": \"high\",\n    \"description\": \"Learners must provide an answer in order to proceed\"\n  },\n  {\n    \"label\": \"Localize Free Text Question buttons\",\n    \"name\": \"i10n\",\n    \"type\": \"group\",\n    \"common\": true,\n    \"collapsed\": true,\n    \"importance\": \"low\",\n    \"fields\": [\n      {\n        \"label\": \"Required text label\",\n        \"name\": \"requiredText\",\n        \"type\": \"text\",\n        \"description\": \"Text shown to notify learner that input is required before proceeding\",\n        \"default\": \"required\",\n        \"importance\": \"low\"\n      },\n      {\n        \"label\": \"Required message\",\n        \"name\": \"requiredMessage\",\n        \"type\": \"text\",\n        \"importance\": \"low\",\n        \"default\": \"This question requires an answer\",\n        \"description\": \"Will display if this field is unanswered and required by a wrapper content type\"\n      },\n      {\n        \"label\": \"Skip button label\",\n        \"name\": \"skipButtonLabel\",\n        \"type\": \"text\",\n        \"default\": \"Skip Question\",\n        \"importance\": \"low\"\n      },\n      {\n        \"label\": \"Proceed button label\",\n        \"name\": \"submitButtonLabel\",\n        \"type\": \"text\",\n        \"default\": \"Answer and proceed\",\n        \"importance\": \"low\"\n      },\n      {\n        \"name\": \"language\",\n        \"type\": \"select\",\n        \"label\": \"Wysiwyg editor language\",\n        \"importance\": \"medium\",\n        \"description\": \"The language of the wysiwyg user interface\",\n        \"options\": [\n          {\n            \"value\": \"af\",\n            \"label\": \"Afrikaans\"\n          },\n          {\n            \"value\": \"ar\",\n            \"label\": \"Arabic\"\n          },\n          {\n            \"value\": \"az\",\n            \"label\": \"Azerbaijani\"\n          },\n          {\n            \"value\": \"bg\",\n            \"label\": \"Bulgarian\"\n          },\n          {\n            \"value\": \"bn\",\n            \"label\": \"Bengali\"\n          },\n          {\n            \"value\": \"bs\",\n            \"label\": \"Bosnian\"\n          },\n          {\n            \"value\": \"ca\",\n            \"label\": \"Catalan\"\n          },\n          {\n            \"value\": \"cs\",\n            \"label\": \"Czech\"\n          },\n          {\n            \"value\": \"cy\",\n            \"label\": \"Welsh\"\n          },\n          {\n            \"value\": \"da\",\n            \"label\": \"Danish\"\n          },\n          {\n            \"value\": \"de-ch\",\n            \"label\": \"German (Switzerland)\"\n          },\n          {\n            \"value\": \"de\",\n            \"label\": \"German\"\n          },\n          {\n            \"value\": \"el\",\n            \"label\": \"Greek\"\n          },\n          {\n            \"value\": \"en-au\",\n            \"label\": \"English (Australia)\"\n          },\n          {\n            \"value\": \"en-ca\",\n            \"label\": \"English (Canada)\"\n          },\n          {\n            \"value\": \"en-gb\",\n            \"label\": \"English (United Kingdom)\"\n          },\n          {\n            \"value\": \"en\",\n            \"label\": \"English\"\n          },\n          {\n            \"value\": \"eo\",\n            \"label\": \"Esperanto\"\n          },\n          {\n            \"value\": \"es-mx\",\n            \"label\": \"Spanish (Mexico)\"\n          },\n          {\n            \"value\": \"es\",\n            \"label\": \"Spanish (Spain)\"\n          },\n          {\n            \"value\": \"et\",\n            \"label\": \"Estonian\"\n          },\n          {\n            \"value\": \"eu\",\n            \"label\": \"Basque\"\n          },\n          {\n            \"value\": \"fa\",\n            \"label\": \"Farsi\"\n          },\n          {\n            \"value\": \"fi\",\n            \"label\": \"Finnish\"\n          },\n          {\n            \"value\": \"fo\",\n            \"label\": \"Faeroese\"\n          },\n          {\n            \"value\": \"fr-ca\",\n            \"label\": \"French (Canada)\"\n          },\n          {\n            \"value\": \"fr\",\n            \"label\": \"French (Standard)\"\n          },\n          {\n            \"value\": \"gl\",\n            \"label\": \"Galician\"\n          },\n          {\n            \"value\": \"gu\",\n            \"label\": \"Gujarati\"\n          },\n          {\n            \"value\": \"he\",\n            \"label\": \"Hebrew (modern)\"\n          },\n          {\n            \"value\": \"hi\",\n            \"label\": \"Hindi\"\n          },\n          {\n            \"value\": \"hr\",\n            \"label\": \"Croatian\"\n          },\n          {\n            \"value\": \"hu\",\n            \"label\": \"Hungarian\"\n          },\n          {\n            \"value\": \"id\",\n            \"label\": \"Indonesian\"\n          },\n          {\n            \"value\": \"is\",\n            \"label\": \"Icelandic\"\n          },\n          {\n            \"value\": \"it\",\n            \"label\": \"Italian (Standard)\"\n          },\n          {\n            \"value\": \"ja\",\n            \"label\": \"Japanese\"\n          },\n          {\n            \"value\": \"ka\",\n            \"label\": \"Georgian\"\n          },\n          {\n            \"value\": \"km\",\n            \"label\": \"Central Khmer\"\n          },\n          {\n            \"value\": \"ko\",\n            \"label\": \"Korean\"\n          },\n          {\n            \"value\": \"ku\",\n            \"label\": \"Kurdish\"\n          },\n          {\n            \"value\": \"lt\",\n            \"label\": \"Lithuanian\"\n          },\n          {\n            \"value\": \"lv\",\n            \"label\": \"Latvian\"\n          },\n          {\n            \"value\": \"mk\",\n            \"label\": \"Macedonian\"\n          },\n          {\n            \"value\": \"mn\",\n            \"label\": \"Mongolian\"\n          },\n          {\n            \"value\": \"ms\",\n            \"label\": \"Malay\"\n          },\n          {\n            \"value\": \"nb\",\n            \"label\": \"Norwegian Bokmål\"\n          },\n          {\n            \"value\": \"nl\",\n            \"label\": \"Dutch (Standard)\"\n          },\n          {\n            \"value\": \"no\",\n            \"label\": \"Norwegian\"\n          },\n          {\n            \"value\": \"oc\",\n            \"label\": \"Occitan\"\n          },\n          {\n            \"value\": \"pl\",\n            \"label\": \"Polish\"\n          },\n          {\n            \"value\": \"pt-br\",\n            \"label\": \"Portuguese (Brazil)\"\n          },\n          {\n            \"value\": \"pt\",\n            \"label\": \"Portuguese (Portugal)\"\n          },\n          {\n            \"value\": \"ro\",\n            \"label\": \"Romanian\"\n          },\n          {\n            \"value\": \"ru\",\n            \"label\": \"Russian\"\n          },\n          {\n            \"value\": \"si\",\n            \"label\": \"Sinhala/Sinhalese\"\n          },\n          {\n            \"value\": \"sk\",\n            \"label\": \"Slovak\"\n          },\n          {\n            \"value\": \"sl\",\n            \"label\": \"Slovenian\"\n          },\n          {\n            \"value\": \"sq\",\n            \"label\": \"Albanian\"\n          },\n          {\n            \"value\": \"sr-latn\",\n            \"label\": \"Serbian (Latin)\"\n          },\n          {\n            \"value\": \"sr\",\n            \"label\": \"Serbian\"\n          },\n          {\n            \"value\": \"sv\",\n            \"label\": \"Swedish\"\n          },\n          {\n            \"value\": \"th\",\n            \"label\": \"Thai\"\n          },\n          {\n            \"value\": \"tr\",\n            \"label\": \"Turkish\"\n          },\n          {\n            \"value\": \"tt\",\n            \"label\": \"Tatar\"\n          },\n          {\n            \"value\": \"ug\",\n            \"label\": \"Uighur/Uyghur\"\n          },\n          {\n            \"value\": \"uk\",\n            \"label\": \"Ukrainian\"\n          },\n          {\n            \"value\": \"vi\",\n            \"label\": \"Vietnamese\"\n          },\n          {\n            \"value\": \"zh-cn\",\n            \"label\": \"Chinese (PRC)\"\n          }\n        ],\n        \"default\": \"en\"\n      }\n    ]\n  }\n]\n', NULL, 1, 13, NULL, NULL, NULL, 1),
(15, 'H5P.GoToQuestion', 'Crossroads', 1, 3, 15, 0, 0, '', 'scripts/go-to-question.js', 'styles/go-to-question.css', '', '[\n  {\n    \"name\": \"text\",\n    \"type\": \"text\",\n    \"label\": \"Question Text\",\n    \"importance\": \"high\",\n    \"description\": \"The question that the user will make a choice based upon.\"\n  },\n  {\n    \"name\": \"choices\",\n    \"type\": \"list\",\n    \"label\": \"Choices\",\n    \"importance\": \"high\",\n    \"entity\": \"choice\",\n    \"min\": 2,\n    \"field\": {\n      \"name\": \"choice\",\n      \"type\": \"group\",\n      \"fields\": [\n        {\n          \"name\": \"text\",\n          \"type\": \"text\",\n          \"label\": \"Choice Text\",\n          \"importance\": \"high\",\n          \"description\": \"The label that will displayed on the choice button.\"\n        },\n        {\n          \"name\": \"goTo\",\n          \"type\": \"number\",\n          \"widget\": \"timecode\",\n          \"label\": \"Go To\",\n          \"importance\": \"high\",\n          \"description\": \"The target time the user will be taken to upon pressing the choice button. Enter timecode in the format M:SS.\"\n        },\n        {\n          \"name\": \"ifChosenText\",\n          \"type\": \"text\",\n          \"optional\": true,\n          \"label\": \"If Chosen Text\",\n          \"importance\": \"low\",\n          \"description\": \"An optional confirmation text that will be displayed after the user has pressed the choice button.\"\n        }\n      ]\n    }\n  },\n  {\n    \"name\": \"continueButtonLabel\",\n    \"type\": \"text\",\n    \"label\": \"Continue Button Label\",\n    \"importance\": \"low\",\n    \"default\": \"Continue\",\n    \"common\": true\n  }\n]', NULL, 1, 6, '{\"disable\":true,\"disableExtraTitleField\":true}', NULL, NULL, 1),
(16, 'H5P.GuidedTour', 'Guided tour', 1, 0, 6, 0, 0, '', 'scripts/h5p-guided-tour.js', 'styles/h5p-guided-tour.css', '', '', NULL, NULL, NULL, NULL, NULL, NULL, 1),
(17, 'H5P.Image', 'Image', 1, 1, 22, 0, 0, '', 'image.js', 'image.css', '', '[\n  {\n    \"name\": \"file\",\n    \"type\": \"image\",\n    \"label\": \"Image\",\n    \"importance\": \"high\",\n    \"disableCopyright\": true\n  },\n  {\n    \"name\": \"decorative\",\n    \"type\": \"boolean\",\n    \"label\": \"Decorative only\",\n    \"default\": false,\n    \"description\": \"Enable this option if the image is purely decorative and does not add any information to the content on the page. It will be ignored by screen readers and not given any alternative text.\"\n  },\n  {\n    \"name\": \"alt\",\n    \"type\": \"text\",\n    \"label\": \"Alternative text\",\n    \"importance\": \"high\",\n    \"description\": \"Required. If the browser can\'t load the image this text will be displayed instead. Also used by \\\"text-to-speech\\\" readers.\",\n    \"widget\": \"showWhen\",\n    \"showWhen\": {\n      \"rules\": [\n        {\n          \"field\": \"decorative\",\n          \"equals\": false\n        }\n      ],\n      \"nullWhenHidden\": true\n    }\n  },\n  {\n    \"name\": \"title\",\n    \"type\": \"text\",\n    \"label\": \"Hover text\",\n    \"importance\": \"low\",\n    \"description\": \"Optional. This text is displayed when the users hover their pointing device over the image.\",\n    \"optional\": true\n  },\n  {\n    \"name\": \"contentName\",\n    \"type\": \"text\",\n    \"label\": \"Image content name\",\n    \"importance\": \"low\",\n    \"common\": true,\n    \"default\": \"Image\"\n  },\n  {\n    \"name\": \"expandImage\",\n    \"type\": \"text\",\n    \"label\": \"Expand Image\",\n    \"importance\": \"low\",\n    \"common\": true,\n    \"default\": \"Expand Image\"\n  },\n  {\n    \"name\": \"minimizeImage\",\n    \"type\": \"text\",\n    \"label\": \"Minimize Image\",\n    \"importance\": \"low\",\n    \"common\": true,\n    \"default\": \"Minimize Image\"\n  }\n]\n', NULL, 1, 19, '{\"disable\":false,\"disableExtraTitleField\":true}', NULL, NULL, 1);
INSERT INTO `mdl_h5p_libraries` (`id`, `machinename`, `title`, `majorversion`, `minorversion`, `patchversion`, `runnable`, `fullscreen`, `embedtypes`, `preloadedjs`, `preloadedcss`, `droplibrarycss`, `semantics`, `addto`, `coremajor`, `coreminor`, `metadatasettings`, `tutorial`, `example`, `enabled`) VALUES
(18, 'H5P.InteractiveVideo', 'Interactive Video', 1, 22, 0, 1, 1, 'iframe', 'dist/h5p-interactive-video.js', 'dist/h5p-interactive-video.css', '', '[\n  {\n    \"name\": \"interactiveVideo\",\n    \"type\": \"group\",\n    \"widget\": \"wizard\",\n    \"label\": \"Interactive Video Editor\",\n    \"importance\": \"high\",\n    \"fields\": [\n      {\n        \"name\": \"video\",\n        \"type\": \"group\",\n        \"label\": \"Upload/embed video\",\n        \"importance\": \"high\",\n        \"fields\": [\n          {\n            \"name\": \"files\",\n            \"type\": \"video\",\n            \"label\": \"Add a video\",\n            \"importance\": \"high\",\n            \"description\": \"Click below to add a video you wish to use in your interactive video. You can add a video link or upload video files. It is possible to add several versions of the video with different qualities. To ensure maximum support in browsers at least add a version in webm and mp4 formats.\",\n            \"extraAttributes\": [\n              \"metadata\"\n            ],\n            \"enableCustomQualityLabel\": true\n          },\n          {\n            \"name\": \"startScreenOptions\",\n            \"type\": \"group\",\n            \"label\": \"Start screen options (unsupported for YouTube videos)\",\n            \"importance\": \"low\",\n            \"fields\": [\n              {\n                \"name\": \"title\",\n                \"type\": \"text\",\n                \"label\": \"The title of this interactive video\",\n                \"importance\": \"low\",\n                \"maxLength\": 60,\n                \"default\": \"Interactive Video\",\n                \"description\": \"Used in summaries, statistics etc.\"\n              },\n              {\n                \"name\": \"hideStartTitle\",\n                \"type\": \"boolean\",\n                \"label\": \"Hide title on video start screen\",\n                \"importance\": \"low\",\n                \"optional\": true,\n                \"default\": false\n              },\n              {\n                \"name\": \"shortStartDescription\",\n                \"type\": \"text\",\n                \"label\": \"Short description (Optional)\",\n                \"importance\": \"low\",\n                \"optional\": true,\n                \"maxLength\": 120,\n                \"description\": \"Optional. Display a short description text on the video start screen. Does not work for YouTube videos.\"\n              },\n              {\n                \"name\": \"poster\",\n                \"type\": \"image\",\n                \"label\": \"Poster image\",\n                \"importance\": \"low\",\n                \"optional\": true,\n                \"description\": \"Image displayed before the user launches the video. Does not work for YouTube Videos.\"\n              }\n            ]\n          },\n          {\n            \"name\": \"textTracks\",\n            \"type\": \"group\",\n            \"label\": \"Text tracks (unsupported for YouTube videos)\",\n            \"importance\": \"low\",\n            \"fields\": [\n              {\n                \"name\": \"videoTrack\",\n                \"type\": \"list\",\n                \"label\": \"Available text tracks\",\n                \"importance\": \"low\",\n                \"optional\": true,\n                \"entity\": \"Track\",\n                \"min\": 0,\n                \"defaultNum\": 1,\n                \"field\": {\n                  \"name\": \"track\",\n                  \"type\": \"group\",\n                  \"label\": \"Track\",\n                  \"importance\": \"low\",\n                  \"expanded\": false,\n                  \"fields\": [\n                    {\n                      \"name\": \"label\",\n                      \"type\": \"text\",\n                      \"label\": \"Track label\",\n                      \"description\": \"Used if you offer multiple tracks and the user has to choose a track. For instance \'Spanish subtitles\' could be the label of a Spanish subtitle track.\",\n                      \"importance\": \"low\",\n                      \"default\": \"Subtitles\",\n                      \"optional\": true\n                    },\n                    {\n                      \"name\": \"kind\",\n                      \"type\": \"select\",\n                      \"label\": \"Type of text track\",\n                      \"importance\": \"low\",\n                      \"default\": \"subtitles\",\n                      \"options\": [\n                        {\n                          \"value\": \"subtitles\",\n                          \"label\": \"Subtitles\"\n                        },\n                        {\n                          \"value\": \"captions\",\n                          \"label\": \"Captions\"\n                        },\n                        {\n                          \"value\": \"descriptions\",\n                          \"label\": \"Descriptions\"\n                        }\n                      ]\n                    },\n                    {\n                      \"name\": \"srcLang\",\n                      \"type\": \"text\",\n                      \"label\": \"Source language, must be defined for subtitles\",\n                      \"importance\": \"low\",\n                      \"default\": \"en\",\n                      \"description\": \"Must be a valid BCP 47 language tag. If \'Subtitles\' is the type of text track selected, the source language of the track must be defined.\"\n                    },\n                    {\n                      \"name\": \"track\",\n                      \"type\": \"file\",\n                      \"label\": \"Track source (WebVTT file)\",\n                      \"importance\": \"low\"\n                    }\n                  ]\n                }\n              },\n              {\n                \"name\": \"defaultTrackLabel\",\n                \"type\": \"text\",\n                \"label\": \"Default text track\",\n                \"description\": \"If left empty or not matching any of the text tracks the first text track will be used as the default.\",\n                \"importance\": \"low\",\n                \"optional\": true\n              }\n            ]\n          }\n        ]\n      },\n      {\n        \"name\": \"assets\",\n        \"type\": \"group\",\n        \"label\": \"Add interactions\",\n        \"importance\": \"high\",\n        \"widget\": \"interactiveVideo\",\n        \"video\": \"video/files\",\n        \"poster\": \"video/startScreenOptions/poster\",\n        \"fields\": [\n          {\n            \"name\": \"interactions\",\n            \"type\": \"list\",\n            \"field\": {\n              \"name\": \"interaction\",\n              \"type\": \"group\",\n              \"fields\": [\n                {\n                  \"name\": \"duration\",\n                  \"type\": \"group\",\n                  \"widget\": \"duration\",\n                  \"label\": \"Display time\",\n                  \"importance\": \"low\",\n                  \"fields\": [\n                    {\n                      \"name\": \"from\",\n                      \"type\": \"number\"\n                    },\n                    {\n                      \"name\": \"to\",\n                      \"type\": \"number\"\n                    }\n                  ]\n                },\n                {\n                  \"name\": \"pause\",\n                  \"label\": \"Pause video\",\n                  \"importance\": \"low\",\n                  \"type\": \"boolean\"\n                },\n                {\n                  \"name\": \"displayType\",\n                  \"label\": \"Display as\",\n                  \"importance\": \"low\",\n                  \"description\": \"<b>Button</b> is a collapsed interaction the user must press to open. <b>Poster</b> is an expanded interaction displayed directly on top of the video\",\n                  \"type\": \"select\",\n                  \"widget\": \"imageRadioButtonGroup\",\n                  \"options\": [\n                    {\n                      \"value\": \"button\",\n                      \"label\": \"Button\"\n                    },\n                    {\n                      \"value\": \"poster\",\n                      \"label\": \"Poster\"\n                    }\n                  ],\n                  \"default\": \"button\"\n                },\n                {\n                  \"name\": \"buttonOnMobile\",\n                  \"label\": \"Turn into button on small screens\",\n                  \"importance\": \"low\",\n                  \"type\": \"boolean\",\n                  \"default\": false\n                },\n                {\n                  \"name\": \"label\",\n                  \"type\": \"text\",\n                  \"widget\": \"html\",\n                  \"label\": \"Label\",\n                  \"importance\": \"low\",\n                  \"description\": \"Label displayed next to interaction icon.\",\n                  \"optional\": true,\n                  \"enterMode\": \"p\",\n                  \"tags\": [\n                    \"p\"\n                  ]\n                },\n                {\n                  \"name\": \"x\",\n                  \"type\": \"number\",\n                  \"importance\": \"low\",\n                  \"widget\": \"none\"\n                },\n                {\n                  \"name\": \"y\",\n                  \"type\": \"number\",\n                  \"importance\": \"low\",\n                  \"widget\": \"none\"\n                },\n                {\n                  \"name\": \"width\",\n                  \"type\": \"number\",\n                  \"widget\": \"none\",\n                  \"importance\": \"low\",\n                  \"optional\": true\n                },\n                {\n                  \"name\": \"height\",\n                  \"type\": \"number\",\n                  \"widget\": \"none\",\n                  \"importance\": \"low\",\n                  \"optional\": true\n                },\n                {\n                  \"name\": \"libraryTitle\",\n                  \"type\": \"text\",\n                  \"importance\": \"low\",\n                  \"optional\": true,\n                  \"widget\": \"none\"\n                },\n                {\n                  \"name\": \"action\",\n                  \"type\": \"library\",\n                  \"importance\": \"low\",\n                  \"options\": [\n                    \"H5P.Nil 1.0\",\n                    \"H5P.Text 1.1\",\n                    \"H5P.Table 1.1\",\n                    \"H5P.Link 1.3\",\n                    \"H5P.Image 1.1\",\n                    \"H5P.Summary 1.10\",\n                    \"H5P.SingleChoiceSet 1.11\",\n                    \"H5P.MultiChoice 1.14\",\n                    \"H5P.TrueFalse 1.6\",\n                    \"H5P.Blanks 1.12\",\n                    \"H5P.DragQuestion 1.13\",\n                    \"H5P.MarkTheWords 1.9\",\n                    \"H5P.DragText 1.8\",\n                    \"H5P.GoToQuestion 1.3\",\n                    \"H5P.IVHotspot 1.2\",\n                    \"H5P.Questionnaire 1.3\",\n                    \"H5P.FreeTextQuestion 1.0\"\n                  ]\n                },\n                {\n                  \"name\": \"adaptivity\",\n                  \"type\": \"group\",\n                  \"label\": \"Adaptivity\",\n                  \"importance\": \"low\",\n                  \"optional\": true,\n                  \"fields\": [\n                    {\n                      \"name\": \"correct\",\n                      \"type\": \"group\",\n                      \"label\": \"Action on all correct\",\n                      \"fields\": [\n                        {\n                          \"name\": \"seekTo\",\n                          \"type\": \"number\",\n                          \"widget\": \"timecode\",\n                          \"label\": \"Seek to\",\n                          \"description\": \"Enter timecode in the format M:SS\"\n                        },\n                        {\n                          \"name\": \"allowOptOut\",\n                          \"type\": \"boolean\",\n                          \"label\": \"Allow the user to opt out and continue\"\n                        },\n                        {\n                          \"name\": \"message\",\n                          \"type\": \"text\",\n                          \"widget\": \"html\",\n                          \"enterMode\": \"p\",\n                          \"tags\": [\n                            \"strong\",\n                            \"em\",\n                            \"del\",\n                            \"a\",\n                            \"code\"\n                          ],\n                          \"label\": \"Message\"\n                        },\n                        {\n                          \"name\": \"seekLabel\",\n                          \"type\": \"text\",\n                          \"label\": \"Label for seek button\"\n                        }\n                      ]\n                    },\n                    {\n                      \"name\": \"wrong\",\n                      \"type\": \"group\",\n                      \"label\": \"Action on wrong\",\n                      \"fields\": [\n                        {\n                          \"name\": \"seekTo\",\n                          \"type\": \"number\",\n                          \"widget\": \"timecode\",\n                          \"label\": \"Seek to\",\n                          \"description\": \"Enter timecode in the format M:SS\"\n                        },\n                        {\n                          \"name\": \"allowOptOut\",\n                          \"type\": \"boolean\",\n                          \"label\": \"Allow the user to opt out and continue\"\n                        },\n                        {\n                          \"name\": \"message\",\n                          \"type\": \"text\",\n                          \"widget\": \"html\",\n                          \"enterMode\": \"p\",\n                          \"tags\": [\n                            \"strong\",\n                            \"em\",\n                            \"del\",\n                            \"a\",\n                            \"code\"\n                          ],\n                          \"label\": \"Message\"\n                        },\n                        {\n                          \"name\": \"seekLabel\",\n                          \"type\": \"text\",\n                          \"label\": \"Label for seek button\"\n                        }\n                      ]\n                    },\n                    {\n                      \"name\": \"requireCompletion\",\n                      \"type\": \"boolean\",\n                      \"label\": \"Require full score for task before proceeding\",\n                      \"description\": \"For best functionality this option should be used in conjunction with the \\\"Prevent skipping forward in a video\\\" option of Interactive Video.\"\n                    }\n                  ]\n                },\n                {\n                  \"name\": \"visuals\",\n                  \"label\": \"Visuals\",\n                  \"importance\": \"low\",\n                  \"type\": \"group\",\n                  \"fields\": [\n                    {\n                      \"name\": \"backgroundColor\",\n                      \"type\": \"text\",\n                      \"label\": \"Background color\",\n                      \"widget\": \"colorSelector\",\n                      \"default\": \"rgb(255, 255, 255)\",\n                      \"spectrum\": {\n                        \"showInput\": true,\n                        \"showAlpha\": true,\n                        \"preferredFormat\": \"rgb\",\n                        \"showPalette\": true,\n                        \"palette\": [\n                          [\n                            \"rgba(0, 0, 0, 0)\"\n                          ],\n                          [\n                            \"rgb(67, 67, 67)\",\n                            \"rgb(102, 102, 102)\",\n                            \"rgb(204, 204, 204)\",\n                            \"rgb(217, 217, 217)\",\n                            \"rgb(255, 255, 255)\"\n                          ],\n                          [\n                            \"rgb(152, 0, 0)\",\n                            \"rgb(255, 0, 0)\",\n                            \"rgb(255, 153, 0)\",\n                            \"rgb(255, 255, 0)\",\n                            \"rgb(0, 255, 0)\",\n                            \"rgb(0, 255, 255)\",\n                            \"rgb(74, 134, 232)\",\n                            \"rgb(0, 0, 255)\",\n                            \"rgb(153, 0, 255)\",\n                            \"rgb(255, 0, 255)\"\n                          ],\n                          [\n                            \"rgb(230, 184, 175)\",\n                            \"rgb(244, 204, 204)\",\n                            \"rgb(252, 229, 205)\",\n                            \"rgb(255, 242, 204)\",\n                            \"rgb(217, 234, 211)\",\n                            \"rgb(208, 224, 227)\",\n                            \"rgb(201, 218, 248)\",\n                            \"rgb(207, 226, 243)\",\n                            \"rgb(217, 210, 233)\",\n                            \"rgb(234, 209, 220)\",\n                            \"rgb(221, 126, 107)\",\n                            \"rgb(234, 153, 153)\",\n                            \"rgb(249, 203, 156)\",\n                            \"rgb(255, 229, 153)\",\n                            \"rgb(182, 215, 168)\",\n                            \"rgb(162, 196, 201)\",\n                            \"rgb(164, 194, 244)\",\n                            \"rgb(159, 197, 232)\",\n                            \"rgb(180, 167, 214)\",\n                            \"rgb(213, 166, 189)\",\n                            \"rgb(204, 65, 37)\",\n                            \"rgb(224, 102, 102)\",\n                            \"rgb(246, 178, 107)\",\n                            \"rgb(255, 217, 102)\",\n                            \"rgb(147, 196, 125)\",\n                            \"rgb(118, 165, 175)\",\n                            \"rgb(109, 158, 235)\",\n                            \"rgb(111, 168, 220)\",\n                            \"rgb(142, 124, 195)\",\n                            \"rgb(194, 123, 160)\",\n                            \"rgb(166, 28, 0)\",\n                            \"rgb(204, 0, 0)\",\n                            \"rgb(230, 145, 56)\",\n                            \"rgb(241, 194, 50)\",\n                            \"rgb(106, 168, 79)\",\n                            \"rgb(69, 129, 142)\",\n                            \"rgb(60, 120, 216)\",\n                            \"rgb(61, 133, 198)\",\n                            \"rgb(103, 78, 167)\",\n                            \"rgb(166, 77, 121)\",\n                            \"rgb(91, 15, 0)\",\n                            \"rgb(102, 0, 0)\",\n                            \"rgb(120, 63, 4)\",\n                            \"rgb(127, 96, 0)\",\n                            \"rgb(39, 78, 19)\",\n                            \"rgb(12, 52, 61)\",\n                            \"rgb(28, 69, 135)\",\n                            \"rgb(7, 55, 99)\",\n                            \"rgb(32, 18, 77)\",\n                            \"rgb(76, 17, 48)\"\n                          ]\n                        ]\n                      }\n                    },\n                    {\n                      \"name\": \"boxShadow\",\n                      \"type\": \"boolean\",\n                      \"label\": \"Box shadow\",\n                      \"default\": true,\n                      \"description\": \"Adds a subtle shadow around the interaction. You might want to disable this for completely transparent interactions\"\n                    }\n                  ]\n                },\n                {\n                  \"name\": \"goto\",\n                  \"label\": \"Go to on click\",\n                  \"importance\": \"low\",\n                  \"type\": \"group\",\n                  \"fields\": [\n                    {\n                      \"name\": \"type\",\n                      \"label\": \"Type\",\n                      \"type\": \"select\",\n                      \"widget\": \"selectToggleFields\",\n                      \"options\": [\n                        {\n                          \"value\": \"timecode\",\n                          \"label\": \"Timecode\",\n                          \"hideFields\": [\n                            \"url\"\n                          ]\n                        },\n                        {\n                          \"value\": \"url\",\n                          \"label\": \"Another page (URL)\",\n                          \"hideFields\": [\n                            \"time\"\n                          ]\n                        }\n                      ],\n                      \"optional\": true\n                    },\n                    {\n                      \"name\": \"time\",\n                      \"type\": \"number\",\n                      \"widget\": \"timecode\",\n                      \"label\": \"Go To\",\n                      \"description\": \"The target time the user will be taken to upon pressing the hotspot. Enter timecode in the format M:SS.\",\n                      \"optional\": true\n                    },\n                    {\n                      \"name\": \"url\",\n                      \"type\": \"group\",\n                      \"label\": \"URL\",\n                      \"widget\": \"linkWidget\",\n                      \"optional\": true,\n                      \"fields\": [\n                        {\n                          \"name\": \"protocol\",\n                          \"type\": \"select\",\n                          \"label\": \"Protocol\",\n                          \"options\": [\n                            {\n                              \"value\": \"http://\",\n                              \"label\": \"http://\"\n                            },\n                            {\n                              \"value\": \"https://\",\n                              \"label\": \"https://\"\n                            },\n                            {\n                              \"value\": \"/\",\n                              \"label\": \"(root relative)\"\n                            },\n                            {\n                              \"value\": \"other\",\n                              \"label\": \"other\"\n                            }\n                          ],\n                          \"optional\": true,\n                          \"default\": \"http://\"\n                        },\n                        {\n                          \"name\": \"url\",\n                          \"type\": \"text\",\n                          \"label\": \"URL\",\n                          \"optional\": true\n                        }\n                      ]\n                    },\n                    {\n                      \"name\": \"visualize\",\n                      \"type\": \"boolean\",\n                      \"label\": \"Visualize\",\n                      \"description\": \"Show that interaction can be clicked by adding a border and an icon\"\n                    }\n                  ]\n                }\n              ]\n            }\n          },\n          {\n            \"name\": \"bookmarks\",\n            \"importance\": \"low\",\n            \"type\": \"list\",\n            \"field\": {\n              \"name\": \"bookmark\",\n              \"type\": \"group\",\n              \"fields\": [\n                {\n                  \"name\": \"time\",\n                  \"type\": \"number\"\n                },\n                {\n                  \"name\": \"label\",\n                  \"type\": \"text\"\n                }\n              ]\n            }\n          },\n          {\n            \"name\": \"endscreens\",\n            \"importance\": \"low\",\n            \"type\": \"list\",\n            \"field\": {\n              \"name\": \"endscreen\",\n              \"type\": \"group\",\n              \"fields\": [\n                {\n                  \"name\": \"time\",\n                  \"type\": \"number\"\n                },\n                {\n                  \"name\": \"label\",\n                  \"type\": \"text\"\n                }\n              ]\n            }\n          }\n        ]\n      },\n      {\n        \"name\": \"summary\",\n        \"type\": \"group\",\n        \"label\": \"Summary task\",\n        \"importance\": \"high\",\n        \"fields\": [\n          {\n            \"name\": \"task\",\n            \"type\": \"library\",\n            \"options\": [\n              \"H5P.Summary 1.10\"\n            ],\n            \"default\": {\n              \"library\": \"H5P.Summary 1.10\",\n              \"params\": {}\n            }\n          },\n          {\n            \"name\": \"displayAt\",\n            \"type\": \"number\",\n            \"label\": \"Display at\",\n            \"description\": \"Number of seconds before the video ends.\",\n            \"default\": 3\n          }\n        ]\n      }\n    ]\n  },\n  {\n    \"name\": \"override\",\n    \"type\": \"group\",\n    \"label\": \"Behavioural settings\",\n    \"importance\": \"low\",\n    \"optional\": true,\n    \"fields\": [\n      {\n        \"name\": \"startVideoAt\",\n        \"type\": \"number\",\n        \"widget\": \"timecode\",\n        \"label\": \"Start video at\",\n        \"importance\": \"low\",\n        \"optional\": true,\n        \"description\": \"Enter timecode in the format M:SS\"\n      },\n      {\n        \"name\": \"autoplay\",\n        \"type\": \"boolean\",\n        \"label\": \"Auto-play video\",\n        \"default\": false,\n        \"optional\": true,\n        \"description\": \"Start playing the video automatically\"\n      },\n      {\n        \"name\": \"loop\",\n        \"type\": \"boolean\",\n        \"label\": \"Loop the video\",\n        \"default\": false,\n        \"optional\": true,\n        \"description\": \"Check if video should run in a loop\"\n      },\n      {\n        \"name\": \"showSolutionButton\",\n        \"type\": \"select\",\n        \"label\": \"Override \\\"Show Solution\\\" button\",\n        \"importance\": \"low\",\n        \"description\": \"This option determines if the \\\"Show Solution\\\" button will be shown for all questions, disabled for all or configured for each question individually.\",\n        \"optional\": true,\n        \"options\": [\n          {\n            \"value\": \"on\",\n            \"label\": \"Enabled\"\n          },\n          {\n            \"value\": \"off\",\n            \"label\": \"Disabled\"\n          }\n        ]\n      },\n      {\n        \"name\": \"retryButton\",\n        \"type\": \"select\",\n        \"label\": \"Override \\\"Retry\\\" button\",\n        \"importance\": \"low\",\n        \"description\": \"This option determines if the \\\"Retry\\\" button will be shown for all questions, disabled for all or configured for each question individually.\",\n        \"optional\": true,\n        \"options\": [\n          {\n            \"value\": \"on\",\n            \"label\": \"Enabled\"\n          },\n          {\n            \"value\": \"off\",\n            \"label\": \"Disabled\"\n          }\n        ]\n      },\n      {\n        \"name\": \"showBookmarksmenuOnLoad\",\n        \"type\": \"boolean\",\n        \"label\": \"Start with bookmarks menu open\",\n        \"importance\": \"low\",\n        \"default\": false,\n        \"description\": \"This function is not available on iPad when using YouTube as video source.\"\n      },\n      {\n        \"name\": \"showRewind10\",\n        \"type\": \"boolean\",\n        \"label\": \"Show button for rewinding 10 seconds\",\n        \"importance\": \"low\",\n        \"default\": false\n      },\n      {\n        \"name\": \"preventSkipping\",\n        \"type\": \"boolean\",\n        \"default\": false,\n        \"label\": \"Prevent skipping forward in a video\",\n        \"importance\": \"low\",\n        \"description\": \"Enabling this options will disable user video navigation through default controls.\"\n      },\n      {\n        \"name\": \"deactivateSound\",\n        \"type\": \"boolean\",\n        \"default\": false,\n        \"label\": \"Deactivate sound\",\n        \"importance\": \"low\",\n        \"description\": \"Enabling this option will deactivate the video\'s sound and prevent it from being switched on.\"\n      }\n    ]\n  },\n  {\n    \"name\": \"l10n\",\n    \"type\": \"group\",\n    \"label\": \"Localize\",\n    \"importance\": \"low\",\n    \"common\": true,\n    \"optional\": true,\n    \"fields\": [\n      {\n        \"name\": \"interaction\",\n        \"type\": \"text\",\n        \"label\": \"Interaction title\",\n        \"importance\": \"low\",\n        \"default\": \"Interaction\",\n        \"optional\": true\n      },\n      {\n        \"name\": \"play\",\n        \"type\": \"text\",\n        \"label\": \"Play title\",\n        \"importance\": \"low\",\n        \"default\": \"Play\",\n        \"optional\": true\n      },\n      {\n        \"name\": \"pause\",\n        \"type\": \"text\",\n        \"label\": \"Pause title\",\n        \"importance\": \"low\",\n        \"default\": \"Pause\",\n        \"optional\": true\n      },\n      {\n        \"name\": \"mute\",\n        \"type\": \"text\",\n        \"label\": \"Mute title\",\n        \"importance\": \"low\",\n        \"default\": \"Mute\",\n        \"optional\": true\n      },\n      {\n        \"name\": \"unmute\",\n        \"type\": \"text\",\n        \"label\": \"Unmute title\",\n        \"importance\": \"low\",\n        \"default\": \"Unmute\",\n        \"optional\": true\n      },\n      {\n        \"name\": \"quality\",\n        \"type\": \"text\",\n        \"label\": \"Video quality title\",\n        \"importance\": \"low\",\n        \"default\": \"Video Quality\",\n        \"optional\": true\n      },\n      {\n        \"name\": \"captions\",\n        \"type\": \"text\",\n        \"label\": \"Video captions title\",\n        \"importance\": \"low\",\n        \"default\": \"Captions\",\n        \"optional\": true\n      },\n      {\n        \"name\": \"close\",\n        \"type\": \"text\",\n        \"label\": \"Close button text\",\n        \"importance\": \"low\",\n        \"default\": \"Close\",\n        \"optional\": true\n      },\n      {\n        \"name\": \"fullscreen\",\n        \"type\": \"text\",\n        \"label\": \"Fullscreen title\",\n        \"importance\": \"low\",\n        \"default\": \"Fullscreen\",\n        \"optional\": true\n      },\n      {\n        \"name\": \"exitFullscreen\",\n        \"type\": \"text\",\n        \"label\": \"Exit fullscreen title\",\n        \"importance\": \"low\",\n        \"default\": \"Exit Fullscreen\",\n        \"optional\": true\n      },\n      {\n        \"name\": \"summary\",\n        \"type\": \"text\",\n        \"label\": \"Summary title\",\n        \"importance\": \"low\",\n        \"default\": \"Open summary dialog\",\n        \"optional\": true\n      },\n      {\n        \"name\": \"bookmarks\",\n        \"type\": \"text\",\n        \"label\": \"Bookmarks title\",\n        \"importance\": \"low\",\n        \"default\": \"Bookmarks\",\n        \"optional\": true\n      },\n      {\n        \"name\": \"endscreen\",\n        \"type\": \"text\",\n        \"label\": \"Submit screen title\",\n        \"importance\": \"low\",\n        \"default\": \"Submit screen\",\n        \"optional\": true\n      },\n      {\n        \"name\": \"defaultAdaptivitySeekLabel\",\n        \"type\": \"text\",\n        \"label\": \"Default label for adaptivity seek button\",\n        \"importance\": \"low\",\n        \"default\": \"Continue\",\n        \"optional\": true\n      },\n      {\n        \"name\": \"continueWithVideo\",\n        \"type\": \"text\",\n        \"label\": \"Default label for continue video button\",\n        \"importance\": \"low\",\n        \"default\": \"Continue with video\",\n        \"optional\": true\n      },\n      {\n        \"name\": \"playbackRate\",\n        \"type\": \"text\",\n        \"label\": \"Set playback rate\",\n        \"importance\": \"low\",\n        \"default\": \"Playback Rate\",\n        \"optional\": true\n      },\n      {\n        \"name\": \"rewind10\",\n        \"type\": \"text\",\n        \"label\": \"Rewind 10 Seconds\",\n        \"importance\": \"low\",\n        \"default\": \"Rewind 10 Seconds\",\n        \"optional\": true\n      },\n      {\n        \"name\": \"navDisabled\",\n        \"type\": \"text\",\n        \"label\": \"Navigation is disabled text\",\n        \"importance\": \"low\",\n        \"default\": \"Navigation is disabled\",\n        \"optional\": true\n      },\n      {\n        \"name\": \"sndDisabled\",\n        \"type\": \"text\",\n        \"label\": \"Sound is disabled text\",\n        \"importance\": \"low\",\n        \"default\": \"Sound is disabled\",\n        \"optional\": true\n      },\n      {\n        \"name\": \"requiresCompletionWarning\",\n        \"type\": \"text\",\n        \"label\": \"Warning that the user must answer the question correctly before continuing\",\n        \"importance\": \"low\",\n        \"default\": \"You need to answer all the questions correctly before continuing.\",\n        \"optional\": true\n      },\n      {\n        \"name\": \"back\",\n        \"type\": \"text\",\n        \"label\": \"Back button\",\n        \"importance\": \"low\",\n        \"default\": \"Back\",\n        \"optional\": true\n      },\n      {\n        \"name\": \"hours\",\n        \"type\": \"text\",\n        \"label\": \"Passed time hours\",\n        \"importance\": \"low\",\n        \"default\": \"Hours\",\n        \"optional\": true\n      },\n      {\n        \"name\": \"minutes\",\n        \"type\": \"text\",\n        \"label\": \"Passed time minutes\",\n        \"importance\": \"low\",\n        \"default\": \"Minutes\",\n        \"optional\": true\n      },\n      {\n        \"name\": \"seconds\",\n        \"type\": \"text\",\n        \"label\": \"Passed time seconds\",\n        \"importance\": \"low\",\n        \"default\": \"Seconds\",\n        \"optional\": true\n      },\n      {\n        \"name\": \"currentTime\",\n        \"type\": \"text\",\n        \"label\": \"Label for current time\",\n        \"importance\": \"low\",\n        \"default\": \"Current time:\",\n        \"optional\": true\n      },\n      {\n        \"name\": \"totalTime\",\n        \"type\": \"text\",\n        \"label\": \"Label for total time\",\n        \"importance\": \"low\",\n        \"default\": \"Total time:\",\n        \"optional\": true\n      },\n      {\n        \"name\": \"singleInteractionAnnouncement\",\n        \"type\": \"text\",\n        \"label\": \"Text explaining that a single interaction with a name has come into view\",\n        \"importance\": \"low\",\n        \"default\": \"Interaction appeared:\",\n        \"optional\": true\n      },\n      {\n        \"name\": \"multipleInteractionsAnnouncement\",\n        \"type\": \"text\",\n        \"label\": \"Text for explaining that multiple interactions have come into view\",\n        \"importance\": \"low\",\n        \"default\": \"Multiple interactions appeared.\",\n        \"optional\": true\n      },\n      {\n        \"name\": \"videoPausedAnnouncement\",\n        \"type\": \"text\",\n        \"label\": \"Video is paused announcement\",\n        \"importance\": \"low\",\n        \"default\": \"Video is paused\",\n        \"optional\": true\n      },\n      {\n        \"name\": \"content\",\n        \"type\": \"text\",\n        \"label\": \"Content label\",\n        \"importance\": \"low\",\n        \"default\": \"Content\",\n        \"optional\": true\n      },\n      {\n        \"name\": \"answered\",\n        \"type\": \"text\",\n        \"label\": \"Answered message (@answered will be replaced with the number of answered questions)\",\n        \"importance\": \"low\",\n        \"default\": \"@answered answered\",\n        \"optional\": true\n      },\n      {\n        \"name\": \"endcardTitle\",\n        \"type\": \"text\",\n        \"label\": \"Submit screen title\",\n        \"importance\": \"low\",\n        \"default\": \"@answered Question(s) answered\",\n        \"description\": \"@answered will be replaced by the number of answered questions.\",\n        \"optional\": true\n      },\n      {\n        \"name\": \"endcardInformation\",\n        \"type\": \"text\",\n        \"label\": \"Submit screen information\",\n        \"importance\": \"low\",\n        \"default\": \"You have answered @answered questions, click below to submit your answers.\",\n        \"description\": \"@answered will be replaced by the number of answered questions.\",\n        \"optional\": true\n      },\n      {\n        \"name\": \"endcardInformationNoAnswers\",\n        \"type\": \"text\",\n        \"label\": \"Submit screen information for missing answers\",\n        \"importance\": \"low\",\n        \"default\": \"You have not answered any questions.\",\n        \"optional\": true\n      },\n      {\n        \"name\": \"endcardInformationMustHaveAnswer\",\n        \"type\": \"text\",\n        \"label\": \"Submit screen information for answer needed\",\n        \"importance\": \"low\",\n        \"default\": \"You have to answer at least one question before you can submit your answers.\",\n        \"optional\": true\n      },\n      {\n        \"name\": \"endcardSubmitButton\",\n        \"type\": \"text\",\n        \"label\": \"Submit screen submit button\",\n        \"importance\": \"low\",\n        \"default\": \"Submit Answers\",\n        \"optional\": true\n      },\n      {\n        \"name\": \"endcardSubmitMessage\",\n        \"type\": \"text\",\n        \"label\": \"Submit screen submit message\",\n        \"importance\": \"low\",\n        \"default\": \"Your answers have been submitted!\",\n        \"optional\": true\n      },\n      {\n        \"name\": \"endcardTableRowAnswered\",\n        \"type\": \"text\",\n        \"label\": \"Submit screen table row title: Answered questions\",\n        \"importance\": \"low\",\n        \"default\": \"Answered questions\",\n        \"optional\": true\n      },\n      {\n        \"name\": \"endcardTableRowScore\",\n        \"type\": \"text\",\n        \"label\": \"Submit screen table row title: Score\",\n        \"importance\": \"low\",\n        \"default\": \"Score\",\n        \"optional\": true\n      },\n      {\n        \"name\": \"endcardAnsweredScore\",\n        \"type\": \"text\",\n        \"label\": \"Submit screen answered score\",\n        \"importance\": \"low\",\n        \"default\": \"answered\",\n        \"optional\": true\n      },\n      {\n        \"name\": \"endCardTableRowSummaryWithScore\",\n        \"type\": \"text\",\n        \"label\": \"Submit screen row summary including score (for readspeakers)\",\n        \"importance\": \"low\",\n        \"default\": \"You got @score out of @total points for the @question that appeared after @minutes minutes and @seconds seconds.\",\n        \"optional\": true\n      },\n      {\n        \"name\": \"endCardTableRowSummaryWithoutScore\",\n        \"type\": \"text\",\n        \"label\": \"Submit screen row summary for no score (for readspeakers)\",\n        \"importance\": \"low\",\n        \"default\": \"You have answered the @question that appeared after @minutes minutes and @seconds seconds.\",\n        \"optional\": true\n      }\n    ]\n  }\n]', NULL, 1, 23, NULL, NULL, NULL, 1);
