(31, 'H5P.Summary', 'Summary', 1, 10, 22, 1, 0, 'iframe', 'js/stop-watch.js, js/xapi-event-builder.js, js/summary.js', 'css/summary.css', '', '[\n  {\n    \"name\": \"intro\",\n    \"type\": \"text\",\n    \"widget\": \"html\",\n    \"label\": \"Introduction text\",\n    \"importance\": \"high\",\n    \"default\": \"Choose the correct statement.\",\n    \"description\": \"Will be displayed above the summary task.\",\n    \"enterMode\": \"p\",\n    \"tags\": [\n      \"strong\",\n      \"em\",\n      \"u\",\n      \"a\",\n      \"ul\",\n      \"ol\",\n      \"h2\",\n      \"h3\",\n      \"hr\",\n      \"pre\",\n      \"code\"\n    ],\n    \"common\": false\n  },\n  {\n    \"name\": \"summaries\",\n    \"importance\": \"high\",\n    \"type\": \"list\",\n    \"widgets\": [\n      {\n        \"name\": \"ListEditor\",\n        \"label\": \"Default\"\n      },\n      {\n        \"name\": \"SummaryTextualEditor\",\n        \"label\": \"Textual\"\n      }\n    ],\n    \"label\": \"Summary\",\n    \"entity\": \"statements\",\n    \"max\": 100,\n    \"min\": 1,\n    \"field\": {\n      \"name\": \"statements\",\n      \"type\": \"group\",\n      \"label\": \"Set of statements\",\n      \"importance\": \"high\",\n      \"isSubContent\": true,\n      \"fields\": [\n        {\n          \"name\": \"summary\",\n          \"type\": \"list\",\n          \"label\": \"List of statements for the summary - the first statement is correct.\",\n          \"entity\": \"statement\",\n          \"importance\": \"medium\",\n          \"min\": 2,\n          \"field\": {\n            \"name\": \"text\",\n            \"type\": \"text\",\n            \"label\": \"Statement\",\n            \"importance\": \"medium\",\n            \"widget\": \"html\",\n            \"enterMode\": \"p\",\n            \"tags\": []\n          }\n        },\n        {\n          \"name\": \"tip\",\n          \"type\": \"group\",\n          \"label\": \"Tip\",\n          \"importance\": \"low\",\n          \"optional\": true,\n          \"fields\": [\n            {\n              \"name\": \"tip\",\n              \"label\": \"Tip text\",\n              \"importance\": \"low\",\n              \"type\": \"text\",\n              \"widget\": \"html\",\n              \"tags\": [\n                \"p\",\n                \"br\",\n                \"strong\",\n                \"em\",\n                \"code\"\n              ],\n              \"optional\": true\n            }\n          ]\n        }\n      ]\n    }\n  },\n  {\n    \"name\": \"overallFeedback\",\n    \"type\": \"group\",\n    \"label\": \"Overall Feedback\",\n    \"importance\": \"low\",\n    \"expanded\": true,\n    \"fields\": [\n      {\n        \"name\": \"overallFeedback\",\n        \"type\": \"list\",\n        \"widgets\": [\n          {\n            \"name\": \"RangeList\",\n            \"label\": \"Default\"\n          }\n        ],\n        \"importance\": \"high\",\n        \"label\": \"Define custom feedback for any score range\",\n        \"description\": \"Click the \\\"Add range\\\" button to add as many ranges as you need. Example: 0-20% Bad score, 21-91% Average Score, 91-100% Great Score!\",\n        \"entity\": \"range\",\n        \"min\": 1,\n        \"defaultNum\": 1,\n        \"optional\": true,\n        \"field\": {\n          \"name\": \"overallFeedback\",\n          \"type\": \"group\",\n          \"importance\": \"low\",\n          \"fields\": [\n            {\n              \"name\": \"from\",\n              \"type\": \"number\",\n              \"label\": \"Score Range\",\n              \"min\": 0,\n              \"max\": 100,\n              \"default\": 0,\n              \"unit\": \"%\"\n            },\n            {\n              \"name\": \"to\",\n              \"type\": \"number\",\n              \"min\": 0,\n              \"max\": 100,\n              \"default\": 100,\n              \"unit\": \"%\"\n            },\n            {\n              \"name\": \"feedback\",\n              \"type\": \"text\",\n              \"label\": \"Feedback for defined score range\",\n              \"importance\": \"low\",\n              \"placeholder\": \"Fill in the feedback\",\n              \"optional\": true\n            }\n          ]\n        }\n      }\n    ]\n  },\n  {\n    \"name\": \"solvedLabel\",\n    \"type\": \"text\",\n    \"label\": \"Text displayed before number of statements solved in the summary task.\",\n    \"importance\": \"low\",\n    \"default\": \"Progress:\",\n    \"description\": \"Will be displayed above the statements. Example: \'Progress: 2/5\'\",\n    \"common\": true\n  },\n  {\n    \"name\": \"scoreLabel\",\n    \"type\": \"text\",\n    \"label\": \"Text displayed before number of wrong statements selected in the summary task.\",\n    \"importance\": \"low\",\n    \"default\": \"Wrong answers:\",\n    \"description\": \"Will be displayed above the statements. Example: \'Wrong answers: 4\'\",\n    \"common\": true\n  },\n  {\n    \"name\": \"resultLabel\",\n    \"type\": \"text\",\n    \"label\": \"Summary feedback header\",\n    \"importance\": \"low\",\n    \"default\": \"Your result\",\n    \"description\": \"Will be displayed above the summary feedback.\",\n    \"common\": true\n  },\n  {\n    \"name\": \"labelCorrect\",\n    \"type\": \"text\",\n    \"label\": \"Readspeaker text for correct answer\",\n    \"importance\": \"low\",\n    \"default\": \"Correct.\",\n    \"common\": true\n  },\n  {\n    \"name\": \"labelIncorrect\",\n    \"type\": \"text\",\n    \"label\": \"Readspeaker text for announcing incorrect answer\",\n    \"importance\": \"low\",\n    \"default\": \"Incorrect! Please try again.\",\n    \"common\": true\n  },\n  {\n    \"name\": \"alternativeIncorrectLabel\",\n    \"type\": \"text\",\n    \"label\": \"Readspeaker label for incorrect answer\",\n    \"importance\": \"low\",\n    \"default\": \"Incorrect\",\n    \"common\": true\n  },\n  {\n    \"name\": \"labelCorrectAnswers\",\n    \"type\": \"text\",\n    \"label\": \"Label list of correct answers\",\n    \"importance\": \"low\",\n    \"default\": \"Correct answers.\",\n    \"common\": true\n  },\n  {\n    \"name\": \"tipButtonLabel\",\n    \"type\": \"text\",\n    \"label\": \"Label for the show tip button\",\n    \"importance\": \"low\",\n    \"default\": \"Show tip\",\n    \"common\": true\n  },\n  {\n    \"name\": \"scoreBarLabel\",\n    \"type\": \"text\",\n    \"label\": \"Textual representation of the score bar for those using a readspeaker\",\n    \"description\": \":num and :total are special keywords which are programmatically updated\",\n    \"default\": \"You got :num out of :total points\",\n    \"importance\": \"low\",\n    \"common\": true\n  },\n  {\n    \"name\": \"progressText\",\n    \"type\": \"text\",\n    \"label\": \"Text used for readspeakers to communicate progress\",\n    \"description\": \":num and :total are special keywords which are programmatically updated\",\n    \"default\": \"Progress :num of :total\",\n    \"importance\": \"low\",\n    \"common\": true\n  }\n]\n', NULL, 1, 19, NULL, NULL, NULL, 1),
(32, 'H5P.Table', 'Table', 1, 1, 15, 0, 0, '', 'scripts/table.js', 'styles/table.css', '', '[\n  {\n    \"name\": \"text\",\n    \"type\": \"text\",\n    \"widget\": \"html\",\n    \"label\": \"Table\",\n    \"importance\": \"high\",\n    \"default\": \"<table class=\\\"h5p-table\\\"><thead><tr><th scope=\\\"col\\\">Heading Column 1</th><th scope=\\\"col\\\">Heading Column 2</th></tr></thead><tbody><tr><td>Row 1 Col 1</td><td>Row 1 Col 2</td></tr><tr><td>Row 2 Col 1</td><td>Row 2 Col 2</td></tr></tbody></table>\",\n    \"tags\": [\n      \"strong\",\n      \"em\",\n      \"del\",\n      \"a\",\n      \"table\",\n      \"code\"\n    ],\n    \"font\": {\n      \"color\": true\n    }\n  }\n]\n', NULL, NULL, NULL, NULL, NULL, NULL, 1),
