(58, 'H5P.DocumentExportPage', 'Document Export Page', 1, 5, 19, 0, 0, '', 'dist/h5p-document-export-page.js', 'dist/h5p-document-export-page.css', '', '[\n  {\n    \"name\": \"description\",\n    \"label\": \"Description\",\n    \"importance\": \"medium\",\n    \"type\": \"text\",\n    \"widget\": \"html\",\n    \"description\": \"Description of the export page.\",\n    \"default\": \"On this page you can choose to export your text, goals and goals assessments.\",\n    \"enterMode\": \"p\",\n    \"tags\": [\n      \"strong\",\n      \"em\",\n      \"u\",\n      \"a\",\n      \"ul\",\n      \"ol\",\n      \"h2\",\n      \"h3\",\n      \"hr\",\n      \"pre\",\n      \"code\"\n    ],\n    \"optional\": true\n  },\n  {\n    \"name\": \"createDocumentLabel\",\n    \"label\": \"Create document button label\",\n    \"importance\": \"low\",\n    \"type\": \"text\",\n    \"description\": \"Text that will be displayed on the \\\"Create document\\\"-button.\",\n    \"default\": \"Create document\"\n  },\n  {\n    \"name\": \"submitTextLabel\",\n    \"label\": \"Submit text button\",\n    \"importance\": \"low\",\n    \"type\": \"text\",\n    \"description\": \"Text that will be displayed on the \\\"Submit\\\"-button.\",\n    \"default\": \"Submit\"\n  },\n  {\n    \"name\": \"submitSuccessTextLabel\",\n    \"type\": \"text\",\n    \"label\": \"Submit success label\",\n    \"optional\": false,\n    \"default\": \"Your report was submitted successfully!\"\n  },\n  {\n    \"name\": \"selectAllTextLabel\",\n    \"label\": \"Select all exportable text button label\",\n    \"importance\": \"low\",\n    \"type\": \"text\",\n    \"description\": \"Text that will be displayed on the \\\"Select all text\\\"-button.\",\n    \"default\": \"Select\"\n  },\n  {\n    \"name\": \"exportTextLabel\",\n    \"label\": \"Export text button label\",\n    \"importance\": \"low\",\n    \"type\": \"text\",\n    \"description\": \"Text that will be displayed on the \\\"Export text\\\"-button.\",\n    \"default\": \"Export\"\n  },\n  {\n    \"name\": \"helpTextLabel\",\n    \"label\": \"Label for help text\",\n    \"importance\": \"low\",\n    \"type\": \"text\",\n    \"description\": \"Label for showing additional helpful information to the user.\",\n    \"default\": \"More information\"\n  },\n  {\n    \"name\": \"helpText\",\n    \"label\": \"Fill in additional help information\",\n    \"importance\": \"low\",\n    \"type\": \"text\",\n    \"widget\": \"html\",\n    \"description\": \"Here you can fill in additional helpful information for the user.\",\n    \"enterMode\": \"p\",\n    \"optional\": true,\n    \"tags\": [\n      \"strong\",\n      \"em\",\n      \"u\",\n      \"a\",\n      \"ul\",\n      \"ol\",\n      \"h2\",\n      \"h3\",\n      \"hr\",\n      \"pre\",\n      \"code\"\n    ]\n  },\n  {\n    \"name\": \"requiresInputErrorMessage\",\n    \"label\": \"Required input missing text\",\n    \"importance\": \"low\",\n    \"type\": \"text\",\n    \"description\": \"An error message which will be displayed if one or more required input fields have not been filled. @pages will be replaced with the titles of affected pages.\",\n    \"default\": \"The following pages contain required fields that need to be filled in order to review or submit this document: @pages\"\n  }\n]\n', NULL, 1, 27, NULL, NULL, NULL, 1),
(59, 'H5P.GoalsAssessmentPage', 'Goals assessment page', 1, 4, 17, 0, 0, '', 'goals-assessment-page.js', 'goals-assessment-page.css', '', '[\n  {\n    \"name\": \"description\",\n    \"label\": \"Description\",\n    \"importance\": \"medium\",\n    \"type\": \"text\",\n    \"widget\": \"html\",\n    \"description\": \"Description of the goals assessment page.\",\n    \"default\": \"Rate the goals that you have chosen in the goals page.\",\n    \"enterMode\": \"p\",\n    \"tags\": [\n      \"strong\",\n      \"em\",\n      \"u\",\n      \"a\",\n      \"ul\",\n      \"ol\",\n      \"h2\",\n      \"h3\",\n      \"hr\",\n      \"pre\",\n      \"code\"\n    ],\n    \"optional\": true\n  },\n  {\n    \"name\": \"lowRating\",\n    \"label\": \"Low rating text\",\n    \"importance\": \"low\",\n    \"type\": \"text\",\n    \"description\": \"Text for worst rating.\",\n    \"default\": \"Learned little\"\n  },\n  {\n    \"name\": \"midRating\",\n    \"label\": \"Medium rating text\",\n    \"importance\": \"low\",\n    \"type\": \"text\",\n    \"description\": \"Text for middle rating.\",\n    \"default\": \"Learned something\"\n  },\n  {\n    \"name\": \"highRating\",\n    \"label\": \"High rating text\",\n    \"importance\": \"low\",\n    \"type\": \"text\",\n    \"description\": \"Text for great rating.\",\n    \"default\": \"Learned a lot\"\n  },\n  {\n    \"name\": \"noGoalsText\",\n    \"label\": \"No goals text\",\n    \"importance\": \"low\",\n    \"type\": \"text\",\n    \"description\": \"Feedback text when no goals have been created.\",\n    \"default\": \"You have not chosen any goals yet.\"\n  },\n  {\n    \"name\": \"helpTextLabel\",\n    \"label\": \"Label for help text\",\n    \"importance\": \"low\",\n    \"type\": \"text\",\n    \"description\": \"Label for showing additional helpful information to the user.\",\n    \"default\": \"More information\"\n  },\n  {\n    \"name\": \"helpText\",\n    \"label\": \"Fill in additional help information\",\n    \"importance\": \"low\",\n    \"type\": \"text\",\n    \"widget\": \"html\",\n    \"description\": \"Here you can fill in additional helpful information for the user.\",\n    \"enterMode\": \"p\",\n    \"optional\": true,\n    \"tags\": [\n      \"strong\",\n      \"em\",\n      \"u\",\n      \"a\",\n      \"ul\",\n      \"ol\",\n      \"h2\",\n      \"h3\",\n      \"hr\",\n      \"pre\",\n      \"code\"\n    ]\n  },\n  {\n    \"name\": \"legendHeader\",\n    \"label\": \"Legend header\",\n    \"importance\": \"low\",\n    \"type\": \"text\",\n    \"default\": \"Possible ratings:\"\n  },\n  {\n    \"name\": \"goalHeader\",\n    \"label\": \"Goal header\",\n    \"importance\": \"low\",\n    \"type\": \"text\",\n    \"default\": \"Goals\"\n  },\n  {\n    \"name\": \"ratingHeader\",\n    \"label\": \"Rating header\",\n    \"importance\": \"low\",\n    \"type\": \"text\",\n    \"default\": \"Rating\"\n  }\n]', NULL, 1, 19, NULL, NULL, NULL, 1);
INSERT INTO `mdl_h5p_libraries` (`id`, `machinename`, `title`, `majorversion`, `minorversion`, `patchversion`, `runnable`, `fullscreen`, `embedtypes`, `preloadedjs`, `preloadedcss`, `droplibrarycss`, `semantics`, `addto`, `coremajor`, `coreminor`, `metadatasettings`, `tutorial`, `example`, `enabled`) VALUES
(60, 'H5P.GoalsPage', 'Goals page', 1, 5, 21, 0, 0, '', 'goals-page.js, goal-instance.js', 'goals-page.css', '', '[\n  {\n    \"name\": \"description\",\n    \"label\": \"Description\",\n    \"importance\": \"medium\",\n    \"type\": \"text\",\n    \"widget\": \"html\",\n    \"description\": \"Description of the goals page.\",\n    \"default\": \"Insert the goals that you have chosen to work with.\",\n    \"enterMode\": \"p\",\n    \"tags\": [\n      \"strong\",\n      \"em\",\n      \"u\",\n      \"a\",\n      \"ul\",\n      \"ol\",\n      \"h2\",\n      \"h3\",\n      \"hr\",\n      \"pre\",\n      \"code\"\n    ],\n    \"optional\": true\n  },\n  {\n    \"name\": \"defineGoalText\",\n    \"label\": \"Define goal link text\",\n    \"importance\": \"low\",\n    \"type\": \"text\",\n    \"description\": \"Text that will be displayed on the button for creating a new goal.\",\n    \"default\": \"Create a new goal\"\n  },\n  {\n    \"name\": \"definedGoalLabel\",\n    \"label\": \"Label for a user defined goal\",\n    \"importance\": \"low\",\n    \"type\": \"text\",\n    \"description\": \"Text that will be displayed as label on a user created goal.\",\n    \"default\": \"User defined goal\"\n  },\n  {\n    \"name\": \"defineGoalPlaceholder\",\n    \"label\": \"Define goal placeholder\",\n    \"importance\": \"low\",\n    \"type\": \"text\",\n    \"description\": \"Text that will be displayed as a placeholder when creating a new goal.\",\n    \"default\": \"Write here...\"\n  },\n  {\n    \"name\": \"goalsAddedText\",\n    \"label\": \"Text indicating how many goals has been added\",\n    \"importance\": \"low\",\n    \"type\": \"text\",\n    \"default\": \"Goals added:\",\n    \"description\": \"This text will follow after the amount of goals that is currently created, example: \'Goals added: 5\' where \'Goals added:\' is this text.\"\n  },\n  {\n    \"name\": \"specifyGoalText\",\n    \"label\": \"Text for \\\"Specify goal\\\"-button\",\n    \"importance\": \"low\",\n    \"type\": \"text\",\n    \"default\": \"Specification\"\n  },\n  {\n    \"name\": \"removeGoalText\",\n    \"label\": \"Text for \\\"Remove goal\\\"-button\",\n    \"importance\": \"low\",\n    \"type\": \"text\",\n    \"default\": \"Remove Goal\"\n  },\n  {\n    \"name\": \"helpTextLabel\",\n    \"label\": \"Label for help text\",\n    \"importance\": \"low\",\n    \"type\": \"text\",\n    \"description\": \"Label for showing additional helpful information to the user.\",\n    \"default\": \"More information\"\n  },\n  {\n    \"name\": \"helpText\",\n    \"label\": \"Fill in additional help information\",\n    \"importance\": \"low\",\n    \"type\": \"text\",\n    \"widget\": \"html\",\n    \"description\": \"Here you can fill in additional helpful information for the user.\",\n    \"enterMode\": \"p\",\n    \"optional\": true,\n    \"tags\": [\n      \"strong\",\n      \"em\",\n      \"u\",\n      \"a\",\n      \"ul\",\n      \"ol\",\n      \"h2\",\n      \"h3\",\n      \"hr\",\n      \"pre\",\n      \"code\"\n    ]\n  },\n  {\n    \"name\": \"goalDeletionConfirmation\",\n    \"type\": \"group\",\n    \"common\": true,\n    \"importance\": \"low\",\n    \"label\": \"Localize goal deletion confirmation\",\n    \"fields\": [\n      {\n        \"name\": \"header\",\n        \"type\": \"text\",\n        \"label\": \"Header\",\n        \"optional\": false,\n        \"default\": \"Confirm deletion\"\n      },\n      {\n        \"name\": \"message\",\n        \"type\": \"text\",\n        \"label\": \"Message\",\n        \"optional\": false,\n        \"default\": \"Are you sure you want to delete this goal?\"\n      },\n      {\n        \"name\": \"cancelLabel\",\n        \"type\": \"text\",\n        \"label\": \"Cancel button label\",\n        \"optional\": false,\n        \"default\": \"Cancel\"\n      },\n      {\n        \"name\": \"confirmLabel\",\n        \"type\": \"text\",\n        \"label\": \"Confirm button label\",\n        \"optional\": false,\n        \"default\": \"Confirm\"\n      }\n    ]\n  }\n]\n', NULL, 1, 19, NULL, NULL, NULL, 1),
(61, 'H5P.StandardPage', 'Standard page', 1, 5, 16, 0, 0, '', 'standard-page.js', 'standard-page.css', '', '[\n  {\n    \"name\": \"elementList\",\n    \"label\": \"Elements\",\n    \"importance\": \"high\",\n    \"type\": \"list\",\n    \"entity\": \"element\",\n    \"field\": {\n      \"name\": \"element\",\n      \"type\": \"library\",\n      \"label\": \"Element type\",\n      \"importance\": \"high\",\n      \"description\": \"Library for this page.\",\n      \"options\": [\n        \"H5P.Text 1.1\",\n        \"H5P.TextInputField 1.2\",\n        \"H5P.Image 1.1\",\n        \"H5P.Accordion 1.0\"\n      ]\n    }\n  },\n  {\n    \"name\": \"helpTextLabel\",\n    \"label\": \"Label for help text\",\n    \"importance\": \"low\",\n    \"type\": \"text\",\n    \"description\": \"Label for showing additional helpful information to the user.\",\n    \"default\": \"More information\"\n  },\n  {\n    \"name\": \"helpText\",\n    \"label\": \"Fill in additional help information\",\n    \"importance\": \"low\",\n    \"type\": \"text\",\n    \"widget\": \"html\",\n    \"description\": \"Here you can fill in additional information for the user, which will be available when clicked.\",\n    \"enterMode\": \"p\",\n    \"optional\": true,\n    \"tags\": [\n      \"strong\",\n      \"em\",\n      \"u\",\n      \"a\",\n      \"ul\",\n      \"ol\",\n      \"h2\",\n      \"h3\",\n      \"hr\",\n      \"pre\",\n      \"code\"\n    ]\n  }\n]\n', NULL, 1, 19, NULL, NULL, NULL, 1),
(62, 'H5P.TextInputField', 'Text input field editor element', 1, 2, 17, 0, 0, '', 'text-input-field.js, xapi-generator.js', 'text-input-field.css', '', '[\n  {\n    \"name\": \"taskDescription\",\n    \"label\": \"Description of inputfield\",\n    \"type\": \"text\",\n    \"widget\": \"html\",\n    \"importance\": \"high\",\n    \"description\": \"Description of what the user should input.\",\n    \"enterMode\": \"div\",\n    \"tags\": [\n      \"strong\",\n      \"em\",\n      \"u\",\n      \"a\",\n      \"ul\",\n      \"ol\",\n      \"h2\",\n      \"h3\",\n      \"hr\",\n      \"pre\",\n      \"code\"\n    ],\n    \"optional\": true\n  },\n  {\n    \"name\": \"placeholderText\",\n    \"label\": \"Placeholder text\",\n    \"type\": \"text\",\n    \"description\": \"Example value or other placeholder text. Should not be used to replace the description of input-field, this value may not be available for screen-readers and also disappears when users start typing.\",\n    \"importance\": \"low\",\n    \"optional\": true\n  },\n  {\n    \"name\": \"maximumLength\",\n    \"label\": \"Maximum text length\",\n    \"type\": \"number\",\n    \"description\": \"Maximum number of characters for the text.\",\n    \"importance\": \"low\",\n    \"optional\": true,\n    \"min\": \"0\"\n  },\n  {\n    \"name\": \"inputFieldSize\",\n    \"label\": \"Input field size\",\n    \"type\": \"select\",\n    \"importance\": \"low\",\n    \"description\": \"The size of the input field in amount of lines it will cover.\",\n    \"options\": [\n      {\n        \"value\": \"1\",\n        \"label\": \"1 line\"\n      },\n      {\n        \"value\": \"3\",\n        \"label\": \"3 lines\"\n      },\n      {\n        \"value\": \"10\",\n        \"label\": \"10 lines\"\n      }\n    ],\n    \"default\": \"1\"\n  },\n  {\n    \"name\": \"requiredField\",\n    \"label\": \"Required field\",\n    \"type\": \"boolean\",\n    \"importance\": \"low\",\n    \"default\": false,\n    \"optional\": true,\n    \"description\": \"Check to make this field required, the user must answer all required fields to be able to export a document.\"\n  },\n  {\n    \"name\": \"remainingChars\",\n    \"type\": \"text\",\n    \"label\": \"Remaining characters\",\n    \"importance\": \"low\",\n    \"common\": true,\n    \"default\": \"Remaining characters: @chars\",\n    \"description\": \"Message for remaining characters. You can use @chars which will be replaced by the corresponding number.\"\n  }\n]', NULL, 1, 27, '{\"disable\":true,\"disableExtraTitleField\":true}', NULL, NULL, 1),
(63, 'H5P.ArithmeticQuiz', 'Arithmetic Quiz', 1, 1, 25, 1, 0, 'iframe', 'js/algebra.min.js, js/arithmetic-quiz.js, js/sound-effects.js, js/countdown-widget.js, js/timer-widget.js, js/intro-page.js, js/qe-generator.js, js/qa-generator.js, js/game-page.js, js/result-page.js, js/odometer.min.js', 'css/arithmetic-quiz.css, css/odometer-theme-default.css', '', '[\n  {\n    \"name\": \"intro\",\n    \"type\": \"text\",\n    \"label\": \"Intro\",\n    \"importance\": \"high\",\n    \"description\": \"The intro text (maximum 100 characters)\",\n    \"maxLength\": 100,\n    \"optional\": true\n  },\n  {\n    \"name\": \"quizType\",\n    \"type\": \"select\",\n    \"label\": \"Quiz type\",\n    \"importance\": \"high\",\n    \"options\": [\n      {\n        \"value\": \"arithmetic\",\n        \"label\": \"Arithmetic Operations Quiz\"\n      },\n      {\n        \"value\": \"linearEquation\",\n        \"label\": \"Linear Equations Quiz\"\n      }\n    ],\n    \"default\": \"arithmetic\"\n  },\n  {\n    \"name\": \"arithmeticType\",\n    \"type\": \"select\",\n    \"label\": \"Arithmetic type\",\n    \"widget\": \"showWhen\",\n    \"showWhen\": {\n      \"rules\": [\n        {\n          \"field\": \"quizType\",\n          \"equals\": [\n            \"arithmetic\"\n          ]\n        }\n      ]\n    },\n    \"importance\": \"high\",\n    \"options\": [\n      {\n        \"value\": \"addition\",\n        \"label\": \"Addition\"\n      },\n      {\n        \"value\": \"subtraction\",\n        \"label\": \"Subtraction\"\n      },\n      {\n        \"value\": \"multiplication\",\n        \"label\": \"Multiplication\"\n      },\n      {\n        \"value\": \"division\",\n        \"label\": \"Division\"\n      }\n    ],\n    \"default\": \"addition\"\n  },\n  {\n    \"name\": \"equationType\",\n    \"type\": \"select\",\n    \"label\": \"Equation type\",\n    \"widget\": \"showWhen\",\n    \"showWhen\": {\n      \"rules\": [\n        {\n          \"field\": \"quizType\",\n          \"equals\": [\n            \"linearEquation\"\n          ]\n        }\n      ]\n    },\n    \"importance\": \"high\",\n    \"options\": [\n      {\n        \"value\": \"basic\",\n        \"label\": \"Basic [ 3x = 12 ]\"\n      },\n      {\n        \"value\": \"intermediate\",\n        \"label\": \"Intermediate [ 4x - 3 = 13 ]\"\n      },\n      {\n        \"value\": \"advanced\",\n        \"label\": \"Advanced [ 5x + 3 = 3x + 15 ]\"\n      }\n    ],\n    \"default\": \"intermediate\"\n  },\n  {\n    \"name\": \"useFractions\",\n    \"type\": \"boolean\",\n    \"label\": \"Enable fractions\",\n    \"description\": \"Enable to allow fractions in equations.\",\n    \"default\": false,\n    \"widget\": \"showWhen\",\n    \"showWhen\": {\n      \"rules\": [\n        {\n          \"field\": \"quizType\",\n          \"equals\": [\n            \"linearEquation\"\n          ]\n        }\n      ]\n    }\n  },\n  {\n    \"name\": \"maxQuestions\",\n    \"type\": \"number\",\n    \"label\": \"Max number of questions\",\n    \"importance\": \"medium\",\n    \"default\": 20,\n    \"min\": 2,\n    \"max\": 100\n  },\n  {\n    \"name\": \"UI\",\n    \"type\": \"group\",\n    \"label\": \"User interface translations\",\n    \"importance\": \"low\",\n    \"common\": true,\n    \"fields\": [\n      {\n        \"name\": \"score\",\n        \"type\": \"text\",\n        \"label\": \"Scoring during quiz\",\n        \"importance\": \"low\",\n        \"default\": \"Score:\"\n      },\n      {\n        \"name\": \"time\",\n        \"type\": \"text\",\n        \"label\": \"Time\",\n        \"importance\": \"low\",\n        \"default\": \"Time: @time\"\n      },\n      {\n        \"name\": \"resultPageHeader\",\n        \"type\": \"text\",\n        \"label\": \"Result page header\",\n        \"importance\": \"low\",\n        \"default\": \"Finished!\"\n      },\n      {\n        \"name\": \"go\",\n        \"type\": \"text\",\n        \"label\": \"Go label\",\n        \"importance\": \"low\",\n        \"default\": \"GO!\"\n      },\n      {\n        \"name\": \"startButton\",\n        \"type\": \"text\",\n        \"label\": \"Start button label\",\n        \"importance\": \"low\",\n        \"default\": \"Start\"\n      },\n      {\n        \"name\": \"retryButton\",\n        \"type\": \"text\",\n        \"label\": \"Retry button label\",\n        \"importance\": \"low\",\n        \"default\": \"Retry\"\n      },\n      {\n        \"name\": \"correctText\",\n        \"type\": \"text\",\n        \"label\": \"Readspeaker text for correct answer\",\n        \"importance\": \"low\",\n        \"default\": \"Correct\"\n      },\n      {\n        \"name\": \"incorrectText\",\n        \"type\": \"text\",\n        \"label\": \"Readspeaker text for incorrect answer\",\n        \"importance\": \"low\",\n        \"default\": \"Incorrect. Correct answer was :num\"\n      },\n      {\n        \"name\": \"durationLabel\",\n        \"type\": \"text\",\n        \"label\": \"Readspeaker label for the timer\",\n        \"importance\": \"low\",\n        \"default\": \"Duration in hours, minutes and seconds.\"\n      },\n      {\n        \"name\": \"humanizedQuestion\",\n        \"type\": \"text\",\n        \"label\": \"Readspeaker text for question\",\n        \"importance\": \"low\",\n        \"default\": \"What does :arithmetic equal?\"\n      },\n      {\n        \"name\": \"humanizedEquation\",\n        \"type\": \"text\",\n        \"label\": \"Readspeaker text for equation question\",\n        \"importance\": \"low\",\n        \"default\": \"For the equation :equation, what does :item equal?\"\n      },\n      {\n        \"name\": \"humanizedVariable\",\n        \"type\": \"text\",\n        \"label\": \"Readspeaker text for equation variable\",\n        \"importance\": \"low\",\n        \"default\": \"What does :item equal?\"\n      },\n      {\n        \"name\": \"plusOperator\",\n        \"type\": \"text\",\n        \"label\": \"Plus operator text\",\n        \"importance\": \"low\",\n        \"default\": \"plus\"\n      },\n      {\n        \"name\": \"subtractionOperator\",\n        \"type\": \"text\",\n        \"label\": \"Subtraction operator text\",\n        \"importance\": \"low\",\n        \"default\": \"minus\"\n      },\n      {\n        \"name\": \"multiplicationOperator\",\n        \"type\": \"text\",\n        \"label\": \"Multiplication operator text\",\n        \"importance\": \"low\",\n        \"default\": \"times\"\n      },\n      {\n        \"name\": \"divisionOperator\",\n        \"type\": \"text\",\n        \"label\": \"Division operator text\",\n        \"importance\": \"low\",\n        \"default\": \"delt på\"\n      },\n      {\n        \"name\": \"equalitySign\",\n        \"type\": \"text\",\n        \"label\": \"Equality sign text\",\n        \"importance\": \"low\",\n        \"default\": \"equals\"\n      },\n      {\n        \"name\": \"slideOfTotal\",\n        \"type\": \"text\",\n        \"label\": \"Slide number text\",\n        \"importance\": \"low\",\n        \"description\": \"Announces current slide and total number of slides, variables are :num and :total\",\n        \"default\": \"Slide :num of :total\"\n      }\n    ]\n  }\n]\n', NULL, NULL, NULL, NULL, 'https://h5p.org/tutorial-arithmetic-quiz', 'https://h5p.org/arithmetic-quiz', 1),
(64, 'H5P.Chart', 'Chart', 1, 2, 22, 1, 0, 'iframe', 'chart.js, d3.js, pie.js, bar.js', 'chart.css', '', '[\n  {\n    \"name\": \"graphMode\",\n    \"type\": \"select\",\n    \"label\": \"Type of chart\",\n    \"importance\": \"high\",\n    \"options\": [\n      {\n        \"value\": \"pieChart\",\n        \"label\": \"Pie Chart\"\n      },\n      {\n        \"value\": \"barChart\",\n        \"label\": \"Bar Chart\"\n      }\n    ],\n    \"default\": \"pieChart\"\n  },\n  {\n    \"name\": \"listOfTypes\",\n    \"type\": \"list\",\n    \"label\": \"Data elements\",\n    \"importance\": \"high\",\n    \"entity\": \"option\",\n    \"min\": 1,\n    \"defaultNum\": 2,\n    \"field\": {\n      \"name\": \"type\",\n      \"type\": \"group\",\n      \"label\": \"Data element\",\n      \"importance\": \"high\",\n      \"fields\": [\n        {\n          \"name\": \"text\",\n          \"type\": \"text\",\n          \"label\": \"Name\",\n          \"importance\": \"medium\"\n        },\n        {\n          \"name\": \"value\",\n          \"type\": \"number\",\n          \"label\": \"Value\",\n          \"importance\": \"low\",\n          \"default\": 1,\n          \"min\": 0.0001,\n          \"decimals\": 4\n        },\n        {\n          \"name\": \"color\",\n          \"type\": \"text\",\n          \"widget\": \"colorSelector\",\n          \"label\": \"Color\",\n          \"importance\": \"low\",\n          \"default\": \"#000\",\n          \"optional\": true,\n          \"spectrum\": {\n            \"showInput\": true,\n            \"preferredFormat\": \"hex\"\n          }\n        },\n        {\n          \"name\": \"fontColor\",\n          \"type\": \"text\",\n          \"widget\": \"colorSelector\",\n          \"label\": \"Font Color\",\n          \"importance\": \"low\",\n          \"default\": \"#fff\",\n          \"optional\": true,\n          \"spectrum\": {\n            \"showInput\": true,\n            \"preferredFormat\": \"hex\"\n          }\n        }\n      ]\n    }\n  },\n  {\n    \"name\": \"figureDefinition\",\n    \"type\": \"text\",\n    \"label\": \"Text read by readspeakers defining the figure as a chart.\",\n    \"importance\": \"low\",\n    \"default\": \"Chart\",\n    \"common\": true\n  }\n]\n', NULL, 1, 21, NULL, 'https://h5p.org/tutorial-chart', 'https://h5p.org/chart', 1),
