(88, 'H5P.QuestionSet', 'Question Set', 1, 20, 31, 1, 0, 'iframe', 'js/questionset.js', 'css/questionset.css', '', '[\n  {\n    \"name\": \"introPage\",\n    \"type\": \"group\",\n    \"label\": \"Quiz introduction\",\n    \"importance\": \"medium\",\n    \"fields\": [\n      {\n        \"name\": \"showIntroPage\",\n        \"type\": \"boolean\",\n        \"label\": \"Display introduction\",\n        \"importance\": \"low\"\n      },\n      {\n        \"name\": \"title\",\n        \"type\": \"text\",\n        \"label\": \"Title\",\n        \"importance\": \"high\",\n        \"optional\": true,\n        \"description\": \"This title will be displayed above the introduction text.\",\n        \"tags\": [\n          \"sub\",\n          \"sup\",\n          \"strong\",\n          \"em\",\n          \"code\"\n        ]\n      },\n      {\n        \"name\": \"introduction\",\n        \"type\": \"text\",\n        \"widget\": \"html\",\n        \"label\": \"Introduction text\",\n        \"importance\": \"medium\",\n        \"optional\": true,\n        \"description\": \"This text will be displayed before the quiz starts.\",\n        \"enterMode\": \"p\",\n        \"tags\": [\n          \"sub\",\n          \"sup\",\n          \"strong\",\n          \"em\",\n          \"p\",\n          \"code\"\n        ]\n      },\n      {\n        \"name\": \"startButtonText\",\n        \"type\": \"text\",\n        \"label\": \"Start button text\",\n        \"importance\": \"low\",\n        \"optional\": true,\n        \"default\": \"Start Quiz\"\n      },\n      {\n        \"name\": \"backgroundImage\",\n        \"type\": \"image\",\n        \"label\": \"Background image\",\n        \"importance\": \"low\",\n        \"optional\": true,\n        \"description\": \"An optional background image for the introduction.\"\n      }\n    ]\n  },\n  {\n    \"name\": \"backgroundImage\",\n    \"type\": \"image\",\n    \"label\": \"Background image\",\n    \"importance\": \"low\",\n    \"optional\": true,\n    \"description\": \"An optional background image for the Question set.\"\n  },\n  {\n    \"name\": \"progressType\",\n    \"type\": \"select\",\n    \"label\": \"Progress indicator\",\n    \"importance\": \"low\",\n    \"description\": \"Question set progress indicator style.\",\n    \"options\": [\n      {\n        \"value\": \"textual\",\n        \"label\": \"Textual\"\n      },\n      {\n        \"value\": \"dots\",\n        \"label\": \"Dots\"\n      }\n    ],\n    \"default\": \"dots\"\n  },\n  {\n    \"name\": \"passPercentage\",\n    \"type\": \"number\",\n    \"label\": \"Pass percentage\",\n    \"importance\": \"low\",\n    \"description\": \"Percentage of Total score required for passing the quiz.\",\n    \"min\": 0,\n    \"max\": 100,\n    \"step\": 1,\n    \"default\": 50\n  },\n  {\n    \"name\": \"questions\",\n    \"label\": \"Questions\",\n    \"importance\": \"high\",\n    \"type\": \"list\",\n    \"widgets\": [\n      {\n        \"name\": \"VerticalTabs\",\n        \"label\": \"Default\"\n      },\n      {\n        \"name\": \"QuestionSetTextualEditor\",\n        \"label\": \"Textual\"\n      }\n    ],\n    \"min\": 1,\n    \"entity\": \"question\",\n    \"field\": {\n      \"name\": \"question\",\n      \"type\": \"library\",\n      \"label\": \"Question type\",\n      \"importance\": \"high\",\n      \"description\": \"Library for this question.\",\n      \"options\": [\n        \"H5P.MultiChoice 1.16\",\n        \"H5P.DragQuestion 1.14\",\n        \"H5P.Blanks 1.14\",\n        \"H5P.MarkTheWords 1.11\",\n        \"H5P.DragText 1.10\",\n        \"H5P.TrueFalse 1.8\",\n        \"H5P.Essay 1.5\",\n        \"H5P.MultiMediaChoice 0.3\"\n      ]\n    }\n  },\n  {\n    \"name\": \"texts\",\n    \"type\": \"group\",\n    \"label\": \"Interface texts in quiz\",\n    \"importance\": \"low\",\n    \"common\": true,\n    \"fields\": [\n      {\n        \"name\": \"prevButton\",\n        \"type\": \"text\",\n        \"label\": \"Back button\",\n        \"importance\": \"low\",\n        \"default\": \"Previous question\"\n      },\n      {\n        \"name\": \"nextButton\",\n        \"type\": \"text\",\n        \"label\": \"Next button\",\n        \"importance\": \"low\",\n        \"default\": \"Next question\"\n      },\n      {\n        \"name\": \"finishButton\",\n        \"type\": \"text\",\n        \"label\": \"Finish button\",\n        \"importance\": \"low\",\n        \"default\": \"Finish\"\n      },\n      {\n        \"name\": \"submitButton\",\n        \"type\": \"text\",\n        \"label\": \"Submit button\",\n        \"importance\": \"low\",\n        \"default\": \"Submit\"\n      },\n      {\n        \"name\": \"textualProgress\",\n        \"type\": \"text\",\n        \"label\": \"Progress text\",\n        \"importance\": \"low\",\n        \"description\": \"Text used if textual progress is selected.\",\n        \"default\": \"Question: @current of @total questions\",\n        \"tags\": [\n          \"strong\",\n          \"em\",\n          \"code\"\n        ]\n      },\n      {\n        \"name\": \"jumpToQuestion\",\n        \"type\": \"text\",\n        \"label\": \"Label for jumping to a certain question\",\n        \"importance\": \"low\",\n        \"description\": \"You must use the placeholder \'%d\' instead of the question number, and %total instead of total amount of questions.\",\n        \"default\": \"Question %d of %total\"\n      },\n      {\n        \"name\": \"questionLabel\",\n        \"type\": \"text\",\n        \"label\": \"Copyright dialog question label\",\n        \"importance\": \"low\",\n        \"default\": \"Question\"\n      },\n      {\n        \"name\": \"readSpeakerProgress\",\n        \"type\": \"text\",\n        \"label\": \"Readspeaker progress\",\n        \"importance\": \"low\",\n        \"description\": \"May use @current and @total question variables\",\n        \"default\": \"Question @current of @total\"\n      },\n      {\n        \"name\": \"unansweredText\",\n        \"type\": \"text\",\n        \"label\": \"Unanswered question text\",\n        \"importance\": \"low\",\n        \"default\": \"Unanswered\"\n      },\n      {\n        \"name\": \"answeredText\",\n        \"type\": \"text\",\n        \"label\": \"Answered question text\",\n        \"importance\": \"low\",\n        \"default\": \"Answered\"\n      },\n      {\n        \"name\": \"currentQuestionText\",\n        \"type\": \"text\",\n        \"label\": \"Current question text\",\n        \"importance\": \"low\",\n        \"default\": \"Current question\"\n      },\n      {\n        \"name\": \"navigationLabel\",\n        \"type\": \"text\",\n        \"label\": \"Navigation label for readspeakers\",\n        \"importance\": \"low\",\n        \"default\": \"Questions\"\n      },\n      {\n        \"name\": \"questionSetInstruction\",\n        \"type\": \"text\",\n        \"label\": \"Instruction for navigating question set with screenreader\",\n        \"importance\": \"low\",\n        \"default\": \"Choose question to display\",\n        \"state\": \"new\"\n      }\n    ]\n  },\n  {\n    \"name\": \"disableBackwardsNavigation\",\n    \"type\": \"boolean\",\n    \"label\": \"Disable backwards navigation\",\n    \"importance\": \"low\",\n    \"description\": \"This option will only allow you to move forward in Question Set\",\n    \"optional\": true,\n    \"default\": false\n  },\n  {\n    \"name\": \"randomQuestions\",\n    \"type\": \"boolean\",\n    \"label\": \"Randomize questions\",\n    \"importance\": \"low\",\n    \"description\": \"Enable to randomize the order of questions on display.\",\n    \"default\": false\n  },\n  {\n    \"name\": \"poolSize\",\n    \"type\": \"number\",\n    \"min\": 1,\n    \"label\": \"Number of questions to be shown:\",\n    \"importance\": \"low\",\n    \"description\": \"Create a randomized batch of questions from the total.\",\n    \"optional\": true\n  },\n  {\n    \"name\": \"endGame\",\n    \"type\": \"group\",\n    \"label\": \"Quiz finished\",\n    \"importance\": \"medium\",\n    \"fields\": [\n      {\n        \"name\": \"showResultPage\",\n        \"type\": \"boolean\",\n        \"label\": \"Display results\",\n        \"importance\": \"low\",\n        \"default\": true\n      },\n      {\n        \"name\": \"showSolutionButton\",\n        \"type\": \"boolean\",\n        \"label\": \"Display solution button\",\n        \"default\": true\n      },\n      {\n        \"name\": \"showRetryButton\",\n        \"type\": \"boolean\",\n        \"label\": \"Display retry button\",\n        \"default\": true\n      },\n      {\n        \"name\": \"noResultMessage\",\n        \"type\": \"text\",\n        \"label\": \"No results message\",\n        \"importance\": \"low\",\n        \"description\": \"Text displayed on end page when \\\"Display results\\\" is disabled\",\n        \"default\": \"Finished\",\n        \"optional\": true\n      },\n      {\n        \"name\": \"message\",\n        \"type\": \"text\",\n        \"label\": \"Feedback heading\",\n        \"importance\": \"low\",\n        \"default\": \"Your result:\",\n        \"description\": \"This heading will be displayed at the end of the quiz when the user has answered all questions.\",\n        \"tags\": [\n          \"strong\",\n          \"em\",\n          \"code\"\n        ]\n      },\n      {\n        \"name\": \"scoreBarLabel\",\n        \"type\": \"text\",\n        \"label\": \"Score announcer\",\n        \"importance\": \"low\",\n        \"description\": \"This label will be used for announcing the final score to the user on the end screen\",\n        \"default\": \"You got @finals out of @totals points\"\n      },\n      {\n        \"name\": \"overallFeedback\",\n        \"type\": \"group\",\n        \"label\": \"Overall Feedback\",\n        \"importance\": \"low\",\n        \"expanded\": true,\n        \"fields\": [\n          {\n            \"name\": \"overallFeedback\",\n            \"type\": \"list\",\n            \"widgets\": [\n              {\n                \"name\": \"RangeList\",\n                \"label\": \"Default\"\n              }\n            ],\n            \"importance\": \"high\",\n            \"label\": \"Define custom feedback for any score range\",\n            \"description\": \"Click the \\\"Add range\\\" button to add as many ranges as you need. Example: 0-20% Bad score, 21-91% Average Score, 91-100% Great Score!\",\n            \"entity\": \"range\",\n            \"min\": 1,\n            \"defaultNum\": 1,\n            \"optional\": true,\n            \"field\": {\n              \"name\": \"overallFeedback\",\n              \"type\": \"group\",\n              \"importance\": \"low\",\n              \"fields\": [\n                {\n                  \"name\": \"from\",\n                  \"type\": \"number\",\n                  \"label\": \"Score Range\",\n                  \"min\": 0,\n                  \"max\": 100,\n                  \"default\": 0,\n                  \"unit\": \"%\"\n                },\n                {\n                  \"name\": \"to\",\n                  \"type\": \"number\",\n                  \"min\": 0,\n                  \"max\": 100,\n                  \"default\": 100,\n                  \"unit\": \"%\"\n                },\n                {\n                  \"name\": \"feedback\",\n                  \"type\": \"text\",\n                  \"label\": \"Feedback for defined score range\",\n                  \"importance\": \"low\",\n                  \"placeholder\": \"Fill in the feedback\",\n                  \"optional\": true\n                }\n              ]\n            }\n          }\n        ]\n      },\n      {\n        \"name\": \"oldFeedback\",\n        \"type\": \"group\",\n        \"label\": \"Old Feedback\",\n        \"importance\": \"low\",\n        \"deprecated\": true,\n        \"fields\": [\n          {\n            \"name\": \"successGreeting\",\n            \"type\": \"text\",\n            \"label\": \"Quiz passed greeting\",\n            \"importance\": \"low\",\n            \"optional\": true,\n            \"description\": \"This text will be displayed above the score if the user has successfully passed the quiz.\",\n            \"tags\": [\n              \"strong\",\n              \"em\",\n              \"code\"\n            ]\n          },\n          {\n            \"name\": \"successComment\",\n            \"type\": \"text\",\n            \"widget\": \"html\",\n            \"label\": \"Passed comment\",\n            \"importance\": \"low\",\n            \"optional\": true,\n            \"description\": \"This comment will be displayed after the score if the user has successfully passed the quiz.\",\n            \"tags\": [\n              \"sub\",\n              \"sup\",\n              \"strong\",\n              \"em\",\n              \"a\",\n              \"p\",\n              \"code\"\n            ]\n          },\n          {\n            \"name\": \"failGreeting\",\n            \"type\": \"text\",\n            \"label\": \"Quiz failed title\",\n            \"importance\": \"low\",\n            \"optional\": true,\n            \"description\": \"This text will be displayed above the score if the user has failed the quiz.\",\n            \"tags\": [\n              \"strong\",\n              \"em\",\n              \"code\"\n            ]\n          },\n          {\n            \"name\": \"failComment\",\n            \"type\": \"text\",\n            \"widget\": \"html\",\n            \"label\": \"Failed comment\",\n            \"importance\": \"low\",\n            \"optional\": true,\n            \"description\": \"This comment will be displayed after the score if the user has failed the quiz.\",\n            \"tags\": [\n              \"sub\",\n              \"sup\",\n              \"strong\",\n              \"em\",\n              \"a\",\n              \"p\",\n              \"code\"\n            ]\n          }\n        ]\n      },\n      {\n        \"name\": \"solutionButtonText\",\n        \"type\": \"text\",\n        \"label\": \"Solution button label\",\n        \"importance\": \"low\",\n        \"default\": \"Show solution\",\n        \"description\": \"Text for the solution button.\"\n      },\n      {\n        \"name\": \"retryButtonText\",\n        \"type\": \"text\",\n        \"label\": \"Retry button label\",\n        \"importance\": \"low\",\n        \"default\": \"Retry\",\n        \"description\": \"Text for the retry button.\"\n      },\n      {\n        \"name\": \"finishButtonText\",\n        \"type\": \"text\",\n        \"label\": \"Finish button text\",\n        \"importance\": \"low\",\n        \"default\": \"Finish\"\n      },\n      {\n        \"name\": \"submitButtonText\",\n        \"type\": \"text\",\n        \"label\": \"Submit button text\",\n        \"importance\": \"low\",\n        \"default\": \"Submit\"\n      },\n      {\n        \"name\": \"showAnimations\",\n        \"type\": \"boolean\",\n        \"label\": \"Display video before quiz results\",\n        \"importance\": \"low\"\n      },\n      {\n        \"name\": \"skippable\",\n        \"type\": \"boolean\",\n        \"label\": \"Enable skip video button\",\n        \"importance\": \"low\"\n      },\n      {\n        \"name\": \"skipButtonText\",\n        \"type\": \"text\",\n        \"label\": \"Skip video button label\",\n        \"importance\": \"low\",\n        \"default\": \"Skip video\"\n      },\n      {\n        \"name\": \"successVideo\",\n        \"type\": \"video\",\n        \"label\": \"Passed video\",\n        \"importance\": \"low\",\n        \"optional\": true,\n        \"description\": \"This video will be played if the user successfully passed the quiz.\"\n      },\n      {\n        \"name\": \"failVideo\",\n        \"type\": \"video\",\n        \"label\": \"Fail video\",\n        \"importance\": \"low\",\n        \"optional\": true,\n        \"description\": \"This video will be played if the user fails the quiz.\"\n      }\n    ]\n  },\n  {\n    \"name\": \"override\",\n    \"type\": \"group\",\n    \"label\": \"Settings for \\\"Check\\\", \\\"Show solution\\\" and \\\"Retry\\\"\",\n    \"importance\": \"low\",\n    \"optional\": true,\n    \"fields\": [\n      {\n        \"name\": \"checkButton\",\n        \"type\": \"boolean\",\n        \"label\": \"Show \\\"Check\\\" buttons\",\n        \"importance\": \"low\",\n        \"description\": \"This option determines if the \\\"Check\\\" button will be shown for all questions.\",\n        \"optional\": true,\n        \"default\": true\n      },\n      {\n        \"name\": \"showSolutionButton\",\n        \"type\": \"select\",\n        \"label\": \"Override \\\"Show Solution\\\" button\",\n        \"importance\": \"low\",\n        \"description\": \"This option determines if the \\\"Show Solution\\\" button will be shown for all questions, disabled for all or configured for each question individually.\",\n        \"optional\": true,\n        \"widget\": \"showWhen\",\n        \"showWhen\": {\n          \"rules\": [\n            {\n              \"field\": \"checkButton\",\n              \"equals\": true\n            }\n          ]\n        },\n        \"options\": [\n          {\n            \"value\": \"on\",\n            \"label\": \"Enabled\"\n          },\n          {\n            \"value\": \"off\",\n            \"label\": \"Disabled\"\n          }\n        ]\n      },\n      {\n        \"name\": \"retryButton\",\n        \"type\": \"select\",\n        \"label\": \"Override \\\"Retry\\\" button\",\n        \"importance\": \"low\",\n        \"description\": \"This option determines if the \\\"Retry\\\" button will be shown for all questions, disabled for all or configured for each question individually.\",\n        \"optional\": true,\n        \"widget\": \"showWhen\",\n        \"showWhen\": {\n          \"rules\": [\n            {\n              \"field\": \"checkButton\",\n              \"equals\": true\n            }\n          ]\n        },\n        \"options\": [\n          {\n            \"value\": \"on\",\n            \"label\": \"Enabled\"\n          },\n          {\n            \"value\": \"off\",\n            \"label\": \"Disabled\"\n          }\n        ]\n      }\n    ]\n  }\n]', NULL, 1, 26, NULL, NULL, NULL, 1),
(89, 'H5P.Row', 'Row', 1, 0, 12, 0, 0, 'iframe', 'h5p-row.js', 'h5p-row.css', '', '[\n  {\n    \"name\": \"columns\",\n    \"type\": \"list\",\n    \"label\": \"Columns\",\n    \"importance\": \"high\",\n    \"max\": 4,\n    \"field\": {\n      \"name\": \"column\",\n      \"type\": \"group\",\n      \"importance\": \"high\",\n      \"fields\": [\n        {\n          \"name\": \"width\",\n          \"label\": \"Width\",\n          \"type\": \"number\",\n          \"description\": \"Column width in percentage.\",\n          \"optional\": true,\n          \"max\": 100\n        },\n        {\n          \"name\": \"content\",\n          \"label\": \"Column\",\n          \"type\": \"library\",\n          \"options\": [\n            \"H5P.RowColumn 1.0\"\n          ]\n        }\n      ]\n    }\n  }\n]\n', NULL, 1, 24, NULL, NULL, NULL, 1),
(90, 'H5P.RowColumn', 'Column', 1, 0, 4, 0, 0, 'iframe', 'scripts/h5p-column.js', 'styles/h5p-column.css', '', '[\n  {\n    \"name\": \"content\",\n    \"label\": \"List of Column Content\",\n    \"importance\": \"high\",\n    \"type\": \"list\",\n    \"min\": 1,\n    \"entity\": \"content\",\n    \"field\": {\n      \"name\": \"content\",\n      \"type\": \"group\",\n      \"fields\": [\n        {\n          \"name\": \"content\",\n          \"type\": \"library\",\n          \"importance\": \"high\",\n          \"label\": \"Content\",\n          \"options\": [\n            \"H5P.Accordion 1.0\",\n            \"H5P.Agamotto 1.6\",\n            \"H5P.Audio 1.5\",\n            \"H5P.AudioRecorder 1.0\",\n            \"H5P.Blanks 1.14\",\n            \"H5P.Chart 1.2\",\n            \"H5P.Collage 0.3\",\n            \"H5P.CoursePresentation 1.26\",\n            \"H5P.Dialogcards 1.9\",\n            \"H5P.DocumentationTool 1.8\",\n            \"H5P.DragQuestion 1.14\",\n            \"H5P.DragText 1.10\",\n            \"H5P.Essay 1.5\",\n            \"H5P.GuessTheAnswer 1.5\",\n            \"H5P.Table 1.2\",\n            \"H5P.AdvancedText 1.1\",\n            \"H5P.IFrameEmbed 1.0\",\n            \"H5P.Image 1.1\",\n            \"H5P.ImageHotspots 1.10\",\n            \"H5P.ImageHotspotQuestion 1.8\",\n            \"H5P.ImageSlider 1.1\",\n            \"H5P.InteractiveVideo 1.27\",\n            \"H5P.Link 1.3\",\n            \"H5P.MarkTheWords 1.11\",\n            \"H5P.MemoryGame 1.3\",\n            \"H5P.MultiChoice 1.16\",\n            \"H5P.Questionnaire 1.3\",\n            \"H5P.QuestionSet 1.20\",\n            \"H5P.SingleChoiceSet 1.11\",\n            \"H5P.Summary 1.10\",\n            \"H5P.Timeline 1.1\",\n            \"H5P.TrueFalse 1.8\",\n            \"H5P.Video 1.6\",\n            \"H5P.MultiMediaChoice 0.3\"\n          ]\n        }\n      ]\n    }\n  }\n]\n', NULL, 1, 27, NULL, NULL, NULL, 1),
(91, 'H5P.Shape', 'Shapes', 1, 0, 5, 0, 0, '', 'js/h5p-shape.js', 'css/h5p-shape.css', '', '[\n  {\n    \"name\": \"type\",\n    \"type\": \"select\",\n    \"label\": \"Type\",\n    \"importance\": \"low\",\n    \"widget\": \"radioGroup\",\n    \"alignment\": \"horizontal\",\n    \"options\": [\n      {\n        \"value\": \"rectangle\",\n        \"label\": \"Rectangle\"\n      },\n      {\n        \"value\": \"circle\",\n        \"label\": \"Circle\"\n      },\n      {\n        \"value\": \"vertical-line\",\n        \"label\": \"Vertical line\"\n      },\n      {\n        \"value\": \"horizontal-line\",\n        \"label\": \"Horizontal line\"\n      }\n    ],\n    \"default\": \"rectangle\"\n  },\n  {\n    \"type\": \"group\",\n    \"name\": \"shape\",\n    \"widget\": \"showWhen\",\n    \"expanded\": true,\n    \"showWhen\": {\n      \"rules\": [\n        {\n          \"field\": \"type\",\n          \"equals\": [\n            \"rectangle\",\n            \"circle\"\n          ]\n        }\n      ]\n    },\n    \"fields\": [\n      {\n        \"name\": \"fillColor\",\n        \"type\": \"text\",\n        \"label\": \"Fill color\",\n        \"importance\": \"medium\",\n        \"optional\": true,\n        \"default\": \"#ffffff\",\n        \"widget\": \"colorSelector\",\n        \"showAplha\": true,\n        \"spectrum\": {\n          \"showInput\": true,\n          \"showAlpha\": true,\n          \"preferredFormat\": \"rgb\"\n        },\n        \"optional\": true\n      },\n      {\n        \"name\": \"borderColor\",\n        \"type\": \"text\",\n        \"label\": \"Border color\",\n        \"importance\": \"medium\",\n        \"optional\": true,\n        \"default\": \"#000000\",\n        \"widget\": \"colorSelector\",\n        \"spectrum\": {\n          \"showInput\": true,\n          \"showAlpha\": true,\n          \"preferredFormat\": \"rgb\"\n        },\n        \"optional\": true\n      },\n      {\n        \"name\": \"borderWidth\",\n        \"type\": \"select\",\n        \"label\": \"Border width\",\n        \"importance\": \"low\",\n        \"default\": \"0\",\n        \"optional\": false,\n        \"options\": [\n          {\n            \"value\": \"0\",\n            \"label\": \"0\"\n          },\n          {\n            \"value\": \"1\",\n            \"label\": \"1\"\n          },\n          {\n            \"value\": \"2\",\n            \"label\": \"2\"\n          },\n          {\n            \"value\": \"3\",\n            \"label\": \"3\"\n          },\n          {\n            \"value\": \"4\",\n            \"label\": \"4\"\n          },\n          {\n            \"value\": \"5\",\n            \"label\": \"5\"\n          },\n          {\n            \"value\": \"6\",\n            \"label\": \"6\"\n          },\n          {\n            \"value\": \"7\",\n            \"label\": \"7\"\n          },\n          {\n            \"value\": \"8\",\n            \"label\": \"8\"\n          },\n          {\n            \"value\": \"9\",\n            \"label\": \"9\"\n          },\n          {\n            \"value\": \"10\",\n            \"label\": \"10\"\n          },\n          {\n            \"value\": \"11\",\n            \"label\": \"11\"\n          },\n          {\n            \"value\": \"12\",\n            \"label\": \"12\"\n          },\n          {\n            \"value\": \"13\",\n            \"label\": \"13\"\n          },\n          {\n            \"value\": \"14\",\n            \"label\": \"14\"\n          },\n          {\n            \"value\": \"15\",\n            \"label\": \"15\"\n          },\n          {\n            \"value\": \"16\",\n            \"label\": \"16\"\n          },\n          {\n            \"value\": \"17\",\n            \"label\": \"17\"\n          },\n          {\n            \"value\": \"18\",\n            \"label\": \"18\"\n          },\n          {\n            \"value\": \"19\",\n            \"label\": \"19\"\n          },\n          {\n            \"value\": \"20\",\n            \"label\": \"20\"\n          },\n          {\n            \"value\": \"21\",\n            \"label\": \"21\"\n          },\n          {\n            \"value\": \"22\",\n            \"label\": \"22\"\n          },\n          {\n            \"value\": \"23\",\n            \"label\": \"23\"\n          },\n          {\n            \"value\": \"24\",\n            \"label\": \"24\"\n          }\n        ]\n      },\n      {\n        \"name\": \"borderStyle\",\n        \"type\": \"select\",\n        \"label\": \"Border style\",\n        \"importance\": \"low\",\n        \"default\": \"solid\",\n        \"optional\": false,\n        \"options\": [\n          {\n            \"value\": \"solid\",\n            \"label\": \"Solid\"\n          },\n          {\n            \"value\": \"dotted\",\n            \"label\": \"Dotted\"\n          },\n          {\n            \"value\": \"dashed\",\n            \"label\": \"Dashed\"\n          },\n          {\n            \"value\": \"double\",\n            \"label\": \"Double\"\n          },\n          {\n            \"value\": \"inset\",\n            \"label\": \"Inset\"\n          },\n          {\n            \"value\": \"outset\",\n            \"label\": \"Outset\"\n          }\n        ]\n      },\n      {\n        \"name\": \"borderRadius\",\n        \"type\": \"select\",\n        \"label\": \"Border radius\",\n        \"importance\": \"low\",\n        \"default\": \"0\",\n        \"optional\": false,\n        \"options\": [\n          {\n            \"value\": \"0\",\n            \"label\": \"0\"\n          },\n          {\n            \"value\": \"1\",\n            \"label\": \"1\"\n          },\n          {\n            \"value\": \"2\",\n            \"label\": \"2\"\n          },\n          {\n            \"value\": \"3\",\n            \"label\": \"3\"\n          },\n          {\n            \"value\": \"4\",\n            \"label\": \"4\"\n          },\n          {\n            \"value\": \"5\",\n            \"label\": \"5\"\n          },\n          {\n            \"value\": \"6\",\n            \"label\": \"6\"\n          },\n          {\n            \"value\": \"7\",\n            \"label\": \"7\"\n          },\n          {\n            \"value\": \"8\",\n            \"label\": \"8\"\n          },\n          {\n            \"value\": \"9\",\n            \"label\": \"9\"\n          },\n          {\n            \"value\": \"10\",\n            \"label\": \"10\"\n          },\n          {\n            \"value\": \"11\",\n            \"label\": \"11\"\n          },\n          {\n            \"value\": \"12\",\n            \"label\": \"12\"\n          },\n          {\n            \"value\": \"13\",\n            \"label\": \"13\"\n          },\n          {\n            \"value\": \"14\",\n            \"label\": \"14\"\n          },\n          {\n            \"value\": \"15\",\n            \"label\": \"15\"\n          },\n          {\n            \"value\": \"16\",\n            \"label\": \"16\"\n          },\n          {\n            \"value\": \"17\",\n            \"label\": \"17\"\n          },\n          {\n            \"value\": \"18\",\n            \"label\": \"18\"\n          },\n          {\n            \"value\": \"19\",\n            \"label\": \"19\"\n          },\n          {\n            \"value\": \"20\",\n            \"label\": \"20\"\n          }\n        ],\n        \"widget\": \"showWhen\",\n        \"showWhen\": {\n          \"rules\": [\n            {\n              \"field\": \"../type\",\n              \"equals\": \"rectangle\"\n            }\n          ]\n        }\n      }\n    ]\n  },\n  {\n    \"type\": \"group\",\n    \"name\": \"line\",\n    \"widget\": \"showWhen\",\n    \"expanded\": true,\n    \"showWhen\": {\n      \"rules\": [\n        {\n          \"field\": \"type\",\n          \"equals\": [\n            \"vertical-line\",\n            \"horizontal-line\"\n          ]\n        }\n      ]\n    },\n    \"fields\": [\n      {\n        \"name\": \"borderColor\",\n        \"type\": \"text\",\n        \"label\": \"Line color\",\n        \"importance\": \"medium\",\n        \"optional\": true,\n        \"default\": \"#000000\",\n        \"widget\": \"colorSelector\",\n        \"optional\": true,\n        \"spectrum\": {\n          \"showInput\": true,\n          \"showAlpha\": true,\n          \"preferredFormat\": \"rgb\"\n        }\n      },\n      {\n        \"name\": \"borderWidth\",\n        \"type\": \"select\",\n        \"label\": \"Line width\",\n        \"importance\": \"low\",\n        \"default\": \"1\",\n        \"optional\": false,\n        \"options\": [\n          {\n            \"value\": \"1\",\n            \"label\": \"1\"\n          },\n          {\n            \"value\": \"2\",\n            \"label\": \"2\"\n          },\n          {\n            \"value\": \"3\",\n            \"label\": \"3\"\n          },\n          {\n            \"value\": \"4\",\n            \"label\": \"4\"\n          },\n          {\n            \"value\": \"5\",\n            \"label\": \"5\"\n          },\n          {\n            \"value\": \"6\",\n            \"label\": \"6\"\n          },\n          {\n            \"value\": \"7\",\n            \"label\": \"7\"\n          },\n          {\n            \"value\": \"8\",\n            \"label\": \"8\"\n          },\n          {\n            \"value\": \"9\",\n            \"label\": \"9\"\n          },\n          {\n            \"value\": \"10\",\n            \"label\": \"10\"\n          },\n          {\n            \"value\": \"11\",\n            \"label\": \"11\"\n          },\n          {\n            \"value\": \"12\",\n            \"label\": \"12\"\n          },\n          {\n            \"value\": \"13\",\n            \"label\": \"13\"\n          },\n          {\n            \"value\": \"14\",\n            \"label\": \"14\"\n          },\n          {\n            \"value\": \"15\",\n            \"label\": \"15\"\n          },\n          {\n            \"value\": \"16\",\n            \"label\": \"16\"\n          },\n          {\n            \"value\": \"17\",\n            \"label\": \"17\"\n          },\n          {\n            \"value\": \"18\",\n            \"label\": \"18\"\n          },\n          {\n            \"value\": \"19\",\n            \"label\": \"19\"\n          },\n          {\n            \"value\": \"20\",\n            \"label\": \"20\"\n          },\n          {\n            \"value\": \"21\",\n            \"label\": \"21\"\n          },\n          {\n            \"value\": \"22\",\n            \"label\": \"22\"\n          },\n          {\n            \"value\": \"23\",\n            \"label\": \"23\"\n          },\n          {\n            \"value\": \"24\",\n            \"label\": \"24\"\n          }\n        ]\n      },\n      {\n        \"name\": \"borderStyle\",\n        \"type\": \"select\",\n        \"label\": \"Line style\",\n        \"importance\": \"low\",\n        \"default\": \"solid\",\n        \"optional\": false,\n        \"options\": [\n          {\n            \"value\": \"solid\",\n            \"label\": \"Solid\"\n          },\n          {\n            \"value\": \"dotted\",\n            \"label\": \"Dotted\"\n          },\n          {\n            \"value\": \"dashed\",\n            \"label\": \"Dashed\"\n          },\n          {\n            \"value\": \"double\",\n            \"label\": \"Double\"\n          }\n        ]\n      }\n    ]\n  }\n]\n', NULL, NULL, NULL, '{\"disable\":true,\"disableExtraTitleField\":true}', NULL, NULL, 1),
(92, 'H5P.Table', 'Table', 1, 2, 2, 0, 0, '', 'scripts/table.js', 'styles/table.css', '', '[\n  {\n    \"name\": \"text\",\n    \"type\": \"text\",\n    \"widget\": \"html\",\n    \"label\": \"Table\",\n    \"importance\": \"high\",\n    \"default\": \"<figure class=\\\"table\\\"><table class=\\\"h5p-table\\\"><thead><tr><th>Heading Column 1</th><th>Heading Column 2</th></tr></thead><tbody><tr><td>Row 1 Col 1</td><td>Row 1 Col 2</td></tr><tr><td>Row 2 Col 1</td><td>Row 2 Col 2</td></tr></tbody></table></figure>\",\n    \"tags\": [\n      \"strong\",\n      \"em\",\n      \"del\",\n      \"a\",\n      \"table\",\n      \"code\"\n    ],\n    \"font\": {\n      \"color\": true\n    }\n  }\n]\n', NULL, 1, 27, NULL, NULL, NULL, 1);
INSERT INTO `mdl_h5p_libraries` (`id`, `machinename`, `title`, `majorversion`, `minorversion`, `patchversion`, `runnable`, `fullscreen`, `embedtypes`, `preloadedjs`, `preloadedcss`, `droplibrarycss`, `semantics`, `addto`, `coremajor`, `coreminor`, `metadatasettings`, `tutorial`, `example`, `enabled`) VALUES
(93, 'H5P.Timeline', 'Timeline', 1, 1, 25, 1, 1, 'iframe', 'timeline.js', 'timeline.css', '', '[\n  {\n    \"name\": \"timeline\",\n    \"label\": \"Timeline\",\n    \"importance\": \"high\",\n    \"type\": \"group\",\n    \"expanded\": true,\n    \"fields\": [\n      {\n        \"name\": \"headline\",\n        \"type\": \"text\",\n        \"label\": \"Headline\",\n        \"importance\": \"high\",\n        \"description\": \"Main timeline heading goes here (first page)\"\n      },\n      {\n        \"name\": \"text\",\n        \"type\": \"text\",\n        \"label\": \"Body Text\",\n        \"importance\": \"medium\",\n        \"widget\": \"html\",\n        \"description\": \"The main timeline body goes here (first page).\",\n        \"optional\": true,\n        \"tags\": [\n          \"strong\",\n          \"em\",\n          \"del\",\n          \"a\",\n          \"ul\",\n          \"ol\",\n          \"hr\",\n          \"code\"\n        ]\n      },\n      {\n        \"name\": \"defaultZoomLevel\",\n        \"type\": \"text\",\n        \"label\": \"Default zoom level\",\n        \"importance\": \"low\",\n        \"default\": \"0\",\n        \"optional\": true,\n        \"description\": \"This will tweak the default zoom level. Equivilent to pressing the zoom in or zoom out button the specified number of times. Negative numbers zoom out. default is 0\"\n      },\n      {\n        \"name\": \"backgroundImage\",\n        \"type\": \"image\",\n        \"label\": \"Background image\",\n        \"importance\": \"low\",\n        \"optional\": true,\n        \"description\": \"An image to display as background.\"\n      },\n      {\n        \"name\": \"height\",\n        \"type\": \"number\",\n        \"label\": \"Height\",\n        \"importance\": \"low\",\n        \"description\": \"The height in pixels\",\n        \"default\": 600\n      },\n      {\n        \"name\": \"asset\",\n        \"type\": \"group\",\n        \"label\": \"Asset\",\n        \"importance\": \"low\",\n        \"description\": \"Here you can add an asset to your timeline \\\"front page\\\"\",\n        \"optional\": true,\n        \"fields\": [\n          {\n            \"name\": \"media\",\n            \"type\": \"text\",\n            \"label\": \"Media\",\n            \"importance\": \"low\",\n            \"description\": \"Link to media URL (Twitter, YouTube, Flickr, Vimeo, Google Maps and SoundCloud are currently supported)\",\n            \"optional\": true\n          },\n          {\n            \"name\": \"credit\",\n            \"type\": \"text\",\n            \"label\": \"Credits\",\n            \"importance\": \"low\",\n            \"description\": \"Credits to the media\",\n            \"optional\": true\n          },\n          {\n            \"name\": \"caption\",\n            \"type\": \"text\",\n            \"label\": \"Caption\",\n            \"importance\": \"low\",\n            \"description\": \"Caption description goes here\",\n            \"optional\": true\n          }\n        ]\n      },\n      {\n        \"name\": \"date\",\n        \"type\": \"list\",\n        \"label\": \"Dates\",\n        \"importance\": \"medium\",\n        \"min\": 1,\n        \"description\": \"Add some dates to your timeline!\",\n        \"field\": {\n          \"name\": \"adate\",\n          \"type\": \"group\",\n          \"label\": \"Date\",\n          \"importance\": \"medium\",\n          \"description\": \"Date\",\n          \"fields\": [\n            {\n              \"name\": \"startDate\",\n              \"type\": \"text\",\n              \"label\": \"Start date\",\n              \"importance\": \"medium\",\n              \"description\": \"YYYY,MM,DD (Minimum YYYY required)\",\n              \"regexp\": {\n                \"pattern\": \"^-?\\\\d{1,}(,(1[012]|[0]?[1-9])(,([12][0-9]|3[01]|[0]?[1-9]))?)?$\"\n              }\n            },\n            {\n              \"name\": \"endDate\",\n              \"type\": \"text\",\n              \"label\": \"End date\",\n              \"importance\": \"medium\",\n              \"description\": \"YYYY,MM,DD (Minimum YYYY required)\",\n              \"optional\": true,\n              \"regexp\": {\n                \"pattern\": \"^-?\\\\d{1,}(,(1[012]|[0]?[1-9])(,([12][0-9]|3[01]|[0]?[1-9]))?)?$\"\n              }\n            },\n            {\n              \"name\": \"headline\",\n              \"type\": \"text\",\n              \"label\": \"Headline\",\n              \"importance\": \"medium\",\n              \"description\": \"Headline for the date entry\"\n            },\n            {\n              \"name\": \"text\",\n              \"type\": \"text\",\n              \"label\": \"Body text\",\n              \"importance\": \"medium\",\n              \"widget\": \"html\",\n              \"optional\": true,\n              \"description\": \"Body for the date entry\",\n              \"tags\": [\n                \"strong\",\n                \"em\",\n                \"del\",\n                \"a\",\n                \"ul\",\n                \"ol\",\n                \"h2\",\n                \"h3\",\n                \"hr\",\n                \"pre\",\n                \"code\"\n              ]\n            },\n            {\n              \"name\": \"tag\",\n              \"type\": \"text\",\n              \"label\": \"Tags\",\n              \"importance\": \"medium\",\n              \"description\": \"Enter Tags (categories)\",\n              \"optional\": true\n            },\n            {\n              \"name\": \"asset\",\n              \"type\": \"group\",\n              \"label\": \"Asset\",\n              \"importance\": \"low\",\n              \"description\": \"\",\n              \"optional\": true,\n              \"fields\": [\n                {\n                  \"name\": \"media\",\n                  \"type\": \"text\",\n                  \"label\": \"Media\",\n                  \"importance\": \"low\",\n                  \"description\": \"URL to the media (Twitter, YouTube, Flickr, Vimeo, Wikipedia, Google Maps and SoundCloud are currently supported).\",\n                  \"optional\": true\n                },\n                {\n                  \"name\": \"thumbnail\",\n                  \"type\": \"image\",\n                  \"label\": \"Thumbnail\",\n                  \"importance\": \"low\",\n                  \"description\": \"Add a thumbnail if needed, 32x32\",\n                  \"optional\": true\n                },\n                {\n                  \"name\": \"credit\",\n                  \"type\": \"text\",\n                  \"label\": \"Credit\",\n                  \"importance\": \"low\",\n                  \"description\": \"Credits to the media\",\n                  \"optional\": true\n                },\n                {\n                  \"name\": \"caption\",\n                  \"type\": \"text\",\n                  \"label\": \"Caption\",\n                  \"importance\": \"low\",\n                  \"description\": \"Caption text\",\n                  \"optional\": true\n                }\n              ]\n            }\n          ]\n        }\n      },\n      {\n        \"name\": \"era\",\n        \"type\": \"list\",\n        \"label\": \"Eras\",\n        \"importance\": \"medium\",\n        \"description\": \"Add an era to your timeline\",\n        \"min\": 0,\n        \"optional\": true,\n        \"field\": {\n          \"name\": \"anera\",\n          \"type\": \"group\",\n          \"label\": \"Era\",\n          \"importance\": \"medium\",\n          \"description\": \"\",\n          \"fields\": [\n            {\n              \"name\": \"startDate\",\n              \"type\": \"text\",\n              \"label\": \"Start date\",\n              \"importance\": \"medium\",\n              \"description\": \"YYYY,MM,DD (Minimum YYYY required)\",\n              \"regexp\": {\n                \"pattern\": \"^-?\\\\d{1,}(,(1[012]|[0]?[1-9])(,([12][0-9]|3[01]|[0]?[1-9]))?)?$\"\n              }\n            },\n            {\n              \"name\": \"endDate\",\n              \"type\": \"text\",\n              \"label\": \"End date\",\n              \"importance\": \"medium\",\n              \"description\": \"YYYY,MM,DD (Minimum YYYY required)\",\n              \"optional\": true,\n              \"regexp\": {\n                \"pattern\": \"^-?\\\\d{1,}(,(1[012]|[0]?[1-9])(,([12][0-9]|3[01]|[0]?[1-9]))?)?$\"\n              }\n            },\n            {\n              \"name\": \"headline\",\n              \"type\": \"text\",\n              \"label\": \"Headline\",\n              \"importance\": \"medium\",\n              \"description\": \"Era headline\"\n            },\n            {\n              \"name\": \"text\",\n              \"type\": \"text\",\n              \"label\": \"Text\",\n              \"importance\": \"medium\",\n              \"widget\": \"html\",\n              \"optional\": true,\n              \"description\": \"Era body\",\n              \"tags\": [\n                \"strong\",\n                \"em\",\n                \"del\",\n                \"a\",\n                \"ul\",\n                \"ol\",\n                \"hr\",\n                \"code\"\n              ]\n            },\n            {\n              \"name\": \"tag\",\n              \"type\": \"text\",\n              \"label\": \"Tag\",\n              \"importance\": \"medium\",\n              \"description\": \"Era tags (categories)\",\n              \"optional\": true\n            }\n          ]\n        }\n      },\n      {\n        \"name\": \"language\",\n        \"type\": \"select\",\n        \"label\": \"Language\",\n        \"importance\": \"medium\",\n        \"optional\": true,\n        \"description\": \"The language of the user interface\",\n        \"options\": [\n          {\n            \"value\": \"af\",\n            \"label\": \"Afrikaans\"\n          },\n          {\n            \"value\": \"ar\",\n            \"label\": \"Arabic\"\n          },\n          {\n            \"value\": \"hy\",\n            \"label\": \"Armenian\"\n          },\n          {\n            \"value\": \"eu\",\n            \"label\": \"Basque\"\n          },\n          {\n            \"value\": \"bg\",\n            \"label\": \"Bulgarian\"\n          },\n          {\n            \"value\": \"ca\",\n            \"label\": \"Catalan\"\n          },\n          {\n            \"value\": \"zh-cn\",\n            \"label\": \"Chinese\"\n          },\n          {\n            \"value\": \"hr\",\n            \"label\": \"Croatian / Hrvatski\"\n          },\n          {\n            \"value\": \"cz\",\n            \"label\": \"Czech\"\n          },\n          {\n            \"value\": \"da\",\n            \"label\": \"Danish\"\n          },\n          {\n            \"value\": \"nl\",\n            \"label\": \"Dutch\"\n          },\n          {\n            \"value\": \"en\",\n            \"label\": \"English\"\n          },\n          {\n            \"value\": \"en-24hr\",\n            \"label\": \"English (24-hour time)\"\n          },\n          {\n            \"value\": \"eo\",\n            \"label\": \"Esperanto\"\n          },\n          {\n            \"value\": \"et\",\n            \"label\": \"Estonian\"\n          },\n          {\n            \"value\": \"fo\",\n            \"label\": \"Faroese\"\n          },\n          {\n            \"value\": \"fa\",\n            \"label\": \"Farsi\"\n          },\n          {\n            \"value\": \"fi\",\n            \"label\": \"Finnish\"\n          },\n          {\n            \"value\": \"fr\",\n            \"label\": \"French\"\n          },\n          {\n            \"value\": \"gl\",\n            \"label\": \"Galician\"\n          },\n          {\n            \"value\": \"ka\",\n            \"label\": \"Georgian\"\n          },\n          {\n            \"value\": \"de\",\n            \"label\": \"German / Deutsch\"\n          },\n          {\n            \"value\": \"el\",\n            \"label\": \"Greek\"\n          },\n          {\n            \"value\": \"he\",\n            \"label\": \"Hebrew\"\n          },\n          {\n            \"value\": \"hu\",\n            \"label\": \"Hungarian\"\n          },\n          {\n            \"value\": \"is\",\n            \"label\": \"Icelandic\"\n          },\n          {\n            \"value\": \"id\",\n            \"label\": \"Indonesian\"\n          },\n          {\n            \"value\": \"it\",\n            \"label\": \"Italian\"\n          },\n          {\n            \"value\": \"ja\",\n            \"label\": \"Japanese\"\n          },\n          {\n            \"value\": \"ko\",\n            \"label\": \"Korean\"\n          },\n          {\n            \"value\": \"lv\",\n            \"label\": \"Latvian\"\n          },\n          {\n            \"value\": \"lt\",\n            \"label\": \"Lithuanian\"\n          },\n          {\n            \"value\": \"lb\",\n            \"label\": \"Luxembourgish\"\n          },\n          {\n            \"value\": \"ms\",\n            \"label\": \"Malay\"\n          },\n          {\n            \"value\": \"ne\",\n            \"label\": \"Nepali\"\n          },\n          {\n            \"value\": \"no\",\n            \"label\": \"Norwegian\"\n          },\n          {\n            \"value\": \"pl\",\n            \"label\": \"Polish\"\n          },\n          {\n            \"value\": \"pt\",\n            \"label\": \"Portuguese\"\n          },\n          {\n            \"value\": \"pt-br\",\n            \"label\": \"Portuguese (Brazilian)\"\n          },\n          {\n            \"value\": \"rm\",\n            \"label\": \"Romansh\"\n          },\n          {\n            \"value\": \"ru\",\n            \"label\": \"Russian\"\n          },\n          {\n            \"value\": \"sr-cy\",\n            \"label\": \"Serbian - Cyrillic\"\n          },\n          {\n            \"value\": \"sr\",\n            \"label\": \"Serbian - Latin\"\n          },\n          {\n            \"value\": \"si\",\n            \"label\": \"Sinhalese\"\n          },\n          {\n            \"value\": \"sk\",\n            \"label\": \"Slovak\"\n          },\n          {\n            \"value\": \"sl\",\n            \"label\": \"Slovenian\"\n          },\n          {\n            \"value\": \"es\",\n            \"label\": \"Spanish\"\n          },\n          {\n            \"value\": \"sv\",\n            \"label\": \"Swedish\"\n          },\n          {\n            \"value\": \"tl\",\n            \"label\": \"Tagalog\"\n          },\n          {\n            \"value\": \"ta\",\n            \"label\": \"Tamil\"\n          },\n          {\n            \"value\": \"zh-tw\",\n            \"label\": \"Taiwanese\"\n          },\n          {\n            \"value\": \"te\",\n            \"label\": \"Telugu\"\n          },\n          {\n            \"value\": \"tr\",\n            \"label\": \"Turkish\"\n          },\n          {\n            \"value\": \"uk\",\n            \"label\": \"Ukrainian\"\n          }\n        ],\n        \"default\": \"en\"\n      }\n    ]\n  }\n]\n', NULL, NULL, NULL, NULL, NULL, NULL, 1),
