(95, 'H5P.TrueFalse', 'True/False Question', 1, 8, 11, 1, 0, 'iframe', 'scripts/h5p-true-false.js, scripts/h5p-true-false-answer-group.js, scripts/h5p-true-false-answer.js', 'styles/h5p-true-false.css', '', '[\n  {\n    \"name\": \"media\",\n    \"type\": \"group\",\n    \"label\": \"Media\",\n    \"importance\": \"medium\",\n    \"fields\": [\n      {\n        \"name\": \"type\",\n        \"type\": \"library\",\n        \"label\": \"Type\",\n        \"importance\": \"medium\",\n        \"options\": [\n          \"H5P.Image 1.1\",\n          \"H5P.Video 1.6\",\n          \"H5P.Audio 1.5\"\n        ],\n        \"optional\": true,\n        \"description\": \"Optional media to display above the question.\"\n      },\n      {\n        \"name\": \"disableImageZooming\",\n        \"type\": \"boolean\",\n        \"label\": \"Disable image zooming\",\n        \"importance\": \"low\",\n        \"default\": false,\n        \"optional\": true,\n        \"widget\": \"showWhen\",\n        \"showWhen\": {\n          \"rules\": [\n            {\n              \"field\": \"type\",\n              \"equals\": \"H5P.Image 1.1\"\n            }\n          ]\n        }\n      }\n    ]\n  },\n  {\n    \"name\": \"question\",\n    \"type\": \"text\",\n    \"widget\": \"html\",\n    \"label\": \"Question\",\n    \"importance\": \"high\",\n    \"enterMode\": \"p\",\n    \"tags\": [\n      \"strong\",\n      \"em\",\n      \"sub\",\n      \"sup\",\n      \"h2\",\n      \"h3\",\n      \"pre\",\n      \"code\"\n    ]\n  },\n  {\n    \"name\": \"correct\",\n    \"type\": \"select\",\n    \"widget\": \"radioGroup\",\n    \"alignment\": \"horizontal\",\n    \"label\": \"Correct answer\",\n    \"importance\": \"high\",\n    \"options\": [\n      {\n        \"value\": \"true\",\n        \"label\": \"True\"\n      },\n      {\n        \"value\": \"false\",\n        \"label\": \"False\"\n      }\n    ],\n    \"default\": \"true\"\n  },\n  {\n    \"name\": \"l10n\",\n    \"type\": \"group\",\n    \"common\": true,\n    \"label\": \"User interface translations for True/False Questions\",\n    \"importance\": \"low\",\n    \"fields\": [\n      {\n        \"name\": \"trueText\",\n        \"type\": \"text\",\n        \"label\": \"Label for true button\",\n        \"importance\": \"low\",\n        \"default\": \"True\"\n      },\n      {\n        \"name\": \"falseText\",\n        \"type\": \"text\",\n        \"label\": \"Label for false button\",\n        \"importance\": \"low\",\n        \"default\": \"False\"\n      },\n      {\n        \"label\": \"Feedback text\",\n        \"importance\": \"low\",\n        \"name\": \"score\",\n        \"type\": \"text\",\n        \"default\": \"You got @score of @total points\",\n        \"description\": \"Feedback text, variables available: @score and @total. Example: \'You got @score of @total possible points\'\"\n      },\n      {\n        \"label\": \"Text for \\\"Check\\\" button\",\n        \"importance\": \"low\",\n        \"name\": \"checkAnswer\",\n        \"type\": \"text\",\n        \"default\": \"Check\"\n      },\n      {\n        \"label\": \"Text for \\\"Submit\\\" button\",\n        \"importance\": \"low\",\n        \"name\": \"submitAnswer\",\n        \"type\": \"text\",\n        \"default\": \"Submit\"\n      },\n      {\n        \"label\": \"Text for \\\"Show solution\\\" button\",\n        \"importance\": \"low\",\n        \"name\": \"showSolutionButton\",\n        \"type\": \"text\",\n        \"default\": \"Show solution\"\n      },\n      {\n        \"label\": \"Text for \\\"Retry\\\" button\",\n        \"importance\": \"low\",\n        \"name\": \"tryAgain\",\n        \"type\": \"text\",\n        \"default\": \"Retry\"\n      },\n      {\n        \"name\": \"wrongAnswerMessage\",\n        \"type\": \"text\",\n        \"label\": \"Wrong Answer\",\n        \"importance\": \"low\",\n        \"default\": \"Wrong answer\"\n      },\n      {\n        \"name\": \"correctAnswerMessage\",\n        \"type\": \"text\",\n        \"label\": \"Correct Answer\",\n        \"importance\": \"low\",\n        \"default\": \"Correct answer\"\n      },\n      {\n        \"name\": \"scoreBarLabel\",\n        \"type\": \"text\",\n        \"label\": \"Textual representation of the score bar for those using a readspeaker\",\n        \"default\": \"You got :num out of :total points\",\n        \"importance\": \"low\"\n      },\n      {\n        \"name\": \"a11yCheck\",\n        \"type\": \"text\",\n        \"label\": \"Assistive technology description for \\\"Check\\\" button\",\n        \"default\": \"Check the answers. The responses will be marked as correct, incorrect, or unanswered.\",\n        \"importance\": \"low\"\n      },\n      {\n        \"name\": \"a11yShowSolution\",\n        \"type\": \"text\",\n        \"label\": \"Assistive technology description for \\\"Show Solution\\\" button\",\n        \"default\": \"Show the solution. The task will be marked with its correct solution.\",\n        \"importance\": \"low\"\n      },\n      {\n        \"name\": \"a11yRetry\",\n        \"type\": \"text\",\n        \"label\": \"Assistive technology description for \\\"Retry\\\" button\",\n        \"default\": \"Retry the task. Reset all responses and start the task over again.\",\n        \"importance\": \"low\"\n      }\n    ]\n  },\n  {\n    \"name\": \"behaviour\",\n    \"type\": \"group\",\n    \"label\": \"Behavioural settings\",\n    \"importance\": \"low\",\n    \"description\": \"These options will let you control how the task behaves.\",\n    \"fields\": [\n      {\n        \"name\": \"enableRetry\",\n        \"type\": \"boolean\",\n        \"label\": \"Enable \\\"Retry\\\" button\",\n        \"importance\": \"low\",\n        \"default\": true\n      },\n      {\n        \"name\": \"enableSolutionsButton\",\n        \"type\": \"boolean\",\n        \"label\": \"Enable \\\"Show Solution\\\" button\",\n        \"importance\": \"low\",\n        \"default\": true\n      },\n      {\n        \"name\": \"enableCheckButton\",\n        \"type\": \"boolean\",\n        \"label\": \"Enable \\\"Check\\\" button\",\n        \"widget\": \"none\",\n        \"importance\": \"low\",\n        \"default\": true,\n        \"optional\": true\n      },\n      {\n        \"label\": \"Show confirmation dialog on \\\"Check\\\"\",\n        \"importance\": \"low\",\n        \"name\": \"confirmCheckDialog\",\n        \"type\": \"boolean\",\n        \"default\": false\n      },\n      {\n        \"label\": \"Show confirmation dialog on \\\"Retry\\\"\",\n        \"importance\": \"low\",\n        \"name\": \"confirmRetryDialog\",\n        \"type\": \"boolean\",\n        \"default\": false\n      },\n      {\n        \"label\": \"Automatically check answer\",\n        \"importance\": \"low\",\n        \"description\": \"Note that accessibility will suffer if enabling this option\",\n        \"name\": \"autoCheck\",\n        \"type\": \"boolean\",\n        \"default\": false\n      },\n      {\n        \"name\": \"feedbackOnCorrect\",\n        \"label\": \"Feedback on correct answer\",\n        \"importance\": \"low\",\n        \"description\": \"This will override the default feedback text. Variables available: @score and @total\",\n        \"type\": \"text\",\n        \"maxLength\": 2048,\n        \"optional\": true\n      },\n      {\n        \"name\": \"feedbackOnWrong\",\n        \"label\": \"Feedback on wrong answer\",\n        \"importance\": \"low\",\n        \"description\": \"This will override the default feedback text. Variables available: @score and @total\",\n        \"type\": \"text\",\n        \"maxLength\": 2048,\n        \"optional\": true\n      }\n    ]\n  },\n  {\n    \"label\": \"Check confirmation dialog\",\n    \"importance\": \"low\",\n    \"name\": \"confirmCheck\",\n    \"type\": \"group\",\n    \"common\": true,\n    \"fields\": [\n      {\n        \"label\": \"Header text\",\n        \"importance\": \"low\",\n        \"name\": \"header\",\n        \"type\": \"text\",\n        \"default\": \"Finish ?\"\n      },\n      {\n        \"label\": \"Body text\",\n        \"importance\": \"low\",\n        \"name\": \"body\",\n        \"type\": \"text\",\n        \"default\": \"Are you sure you wish to finish ?\",\n        \"widget\": \"html\",\n        \"enterMode\": \"p\",\n        \"tags\": [\n          \"strong\",\n          \"em\",\n          \"del\",\n          \"u\",\n          \"code\"\n        ]\n      },\n      {\n        \"label\": \"Cancel button label\",\n        \"importance\": \"low\",\n        \"name\": \"cancelLabel\",\n        \"type\": \"text\",\n        \"default\": \"Cancel\"\n      },\n      {\n        \"label\": \"Confirm button label\",\n        \"importance\": \"low\",\n        \"name\": \"confirmLabel\",\n        \"type\": \"text\",\n        \"default\": \"Finish\"\n      }\n    ]\n  },\n  {\n    \"label\": \"Retry confirmation dialog\",\n    \"importance\": \"low\",\n    \"name\": \"confirmRetry\",\n    \"type\": \"group\",\n    \"common\": true,\n    \"fields\": [\n      {\n        \"label\": \"Header text\",\n        \"importance\": \"low\",\n        \"name\": \"header\",\n        \"type\": \"text\",\n        \"default\": \"Retry ?\"\n      },\n      {\n        \"label\": \"Body text\",\n        \"importance\": \"low\",\n        \"name\": \"body\",\n        \"type\": \"text\",\n        \"default\": \"Are you sure you wish to retry ?\",\n        \"widget\": \"html\",\n        \"enterMode\": \"p\",\n        \"tags\": [\n          \"strong\",\n          \"em\",\n          \"del\",\n          \"u\",\n          \"code\"\n        ]\n      },\n      {\n        \"label\": \"Cancel button label\",\n        \"importance\": \"low\",\n        \"name\": \"cancelLabel\",\n        \"type\": \"text\",\n        \"default\": \"Cancel\"\n      },\n      {\n        \"label\": \"Confirm button label\",\n        \"importance\": \"low\",\n        \"name\": \"confirmLabel\",\n        \"type\": \"text\",\n        \"default\": \"Confirm\"\n      }\n    ]\n  }\n]', NULL, 1, 19, NULL, NULL, NULL, 1),
(96, 'H5P.TwitterUserFeed', 'Twitter User Feed', 1, 0, 21, 1, 0, '', 'twitter-user-feed.js', 'twitter-user-feed.css', '', '[\n  {\n    \"label\": \"Username on Twitter\",\n    \"importance\": \"high\",\n    \"name\": \"userName\",\n    \"type\": \"text\",\n    \"description\": \"The username we\'ll be fetching tweets from\"\n  },\n  {\n    \"label\": \"Show replies\",\n    \"importance\": \"low\",\n    \"name\": \"showReplies\",\n    \"type\": \"boolean\"\n  },\n  {\n    \"label\": \"Number of tweets\",\n    \"importance\": \"medium\",\n    \"name\": \"numTweets\",\n    \"type\": \"number\",\n    \"default\": 5,\n    \"min\": 1,\n    \"max\": 20\n  }\n]\n', NULL, NULL, NULL, '{\"disable\":true,\"disableExtraTitleField\":true}', NULL, NULL, 1),
(97, 'H5P.Video', 'Video', 1, 6, 66, 0, 0, '', 'scripts/vimeo.js, scripts/youtube.js, scripts/panopto.js, scripts/echo360.js, scripts/html5.js, scripts/video.js', 'styles/video.css', '', '[\n  {\n    \"name\": \"sources\",\n    \"type\": \"video\",\n    \"label\": \"Video sources\",\n    \"importance\": \"high\",\n    \"description\": \"To ensure that the video works in all browsers you should add both WebM and MP4 formatted sources.\",\n    \"disableCopyright\": true\n  },\n  {\n    \"name\": \"visuals\",\n    \"type\": \"group\",\n    \"label\": \"Visuals\",\n    \"importance\": \"medium\",\n    \"fields\": [\n      {\n        \"name\": \"poster\",\n        \"type\": \"image\",\n        \"label\": \"Poster image\",\n        \"importance\": \"low\"\n      },\n      {\n        \"name\": \"fit\",\n        \"type\": \"boolean\",\n        \"label\": \"Fit video player to use all available space\",\n        \"importance\": \"low\",\n        \"default\": true,\n        \"description\": \"If not set the video player will have the same aspect ratio as the video.\"\n      },\n      {\n        \"name\": \"controls\",\n        \"type\": \"boolean\",\n        \"label\": \"Show video player controls\",\n        \"importance\": \"low\",\n        \"default\": true,\n        \"description\": \"Add controls to the video player. This allows users to play, pause, etc.\"\n      }\n    ]\n  },\n  {\n    \"name\": \"playback\",\n    \"type\": \"group\",\n    \"label\": \"Playback\",\n    \"importance\": \"medium\",\n    \"fields\": [\n      {\n        \"name\": \"autoplay\",\n        \"type\": \"boolean\",\n        \"label\": \"Auto-play video\",\n        \"importance\": \"low\",\n        \"default\": false,\n        \"description\": \"Start playing the video automatically. May not work on mobile devices.\"\n      },\n      {\n        \"name\": \"loop\",\n        \"type\": \"boolean\",\n        \"label\": \"Loop video\",\n        \"importance\": \"low\",\n        \"default\": false,\n        \"description\": \"Automatically start the video over again when it ends.\"\n      }\n    ]\n  },\n  {\n    \"name\": \"l10n\",\n    \"type\": \"group\",\n    \"label\": \"Video localization\",\n    \"importance\": \"low\",\n    \"common\": true,\n    \"fields\": [\n      {\n        \"name\": \"name\",\n        \"type\": \"text\",\n        \"label\": \"Name\",\n        \"importance\": \"low\",\n        \"default\": \"Video\",\n        \"description\": \"Helps identify content of this type.\"\n      },\n      {\n        \"name\": \"loading\",\n        \"type\": \"text\",\n        \"label\": \"Loading\",\n        \"importance\": \"low\",\n        \"default\": \"Video player loading...\"\n      },\n      {\n        \"name\": \"noPlayers\",\n        \"type\": \"text\",\n        \"label\": \"No players found\",\n        \"importance\": \"low\",\n        \"default\": \"Found no video players that supports the given video format.\"\n      },\n      {\n        \"name\": \"noSources\",\n        \"type\": \"text\",\n        \"label\": \"No sources\",\n        \"importance\": \"low\",\n        \"default\": \"Video is missing sources.\"\n      },\n      {\n        \"name\": \"aborted\",\n        \"type\": \"text\",\n        \"label\": \"Aborted\",\n        \"importance\": \"low\",\n        \"default\": \"Media playback has been aborted.\"\n      },\n      {\n        \"name\": \"networkFailure\",\n        \"type\": \"text\",\n        \"label\": \"Network failure\",\n        \"importance\": \"low\",\n        \"default\": \"Network failure.\"\n      },\n      {\n        \"name\": \"cannotDecode\",\n        \"type\": \"text\",\n        \"label\": \"Cannot decode video source\",\n        \"importance\": \"low\",\n        \"default\": \"Unable to decode media.\"\n      },\n      {\n        \"name\": \"formatNotSupported\",\n        \"type\": \"text\",\n        \"label\": \"Format not supported\",\n        \"importance\": \"low\",\n        \"default\": \"Video format not supported.\"\n      },\n      {\n        \"name\": \"mediaEncrypted\",\n        \"type\": \"text\",\n        \"label\": \"Media encrypted\",\n        \"importance\": \"low\",\n        \"default\": \"Media encrypted.\"\n      },\n      {\n        \"name\": \"unknownError\",\n        \"type\": \"text\",\n        \"label\": \"Unknown error\",\n        \"importance\": \"low\",\n        \"default\": \"Unknown error.\"\n      },\n      {\n        \"name\": \"invalidYtId\",\n        \"type\": \"text\",\n        \"label\": \"Invalid YouTube ID\",\n        \"importance\": \"low\",\n        \"default\": \"Invalid YouTube ID.\"\n      },\n      {\n        \"name\": \"unknownYtId\",\n        \"type\": \"text\",\n        \"label\": \"Unknown YouTube ID\",\n        \"importance\": \"low\",\n        \"default\": \"Unable to find video with the given YouTube ID.\"\n      },\n      {\n        \"name\": \"restrictedYt\",\n        \"type\": \"text\",\n        \"label\": \"Restricted YouTube video\",\n        \"importance\": \"low\",\n        \"default\": \"The owner of this video does not allow it to be embedded.\"\n      }\n    ]\n  },\n  {\n    \"name\": \"a11y\",\n    \"type\": \"group\",\n    \"label\": \"Accessibility\",\n    \"importance\": \"medium\",\n    \"fields\": [\n      {\n        \"name\": \"videoTrack\",\n        \"type\": \"list\",\n        \"label\": \"Add video track\",\n        \"importance\": \"low\",\n        \"optional\": true,\n        \"entity\": \"Track\",\n        \"min\": 0,\n        \"field\": {\n          \"name\": \"track\",\n          \"type\": \"group\",\n          \"label\": \"Track\",\n          \"importance\": \"low\",\n          \"expanded\": false,\n          \"fields\": [\n            {\n              \"name\": \"label\",\n              \"type\": \"text\",\n              \"label\": \"Track label\",\n              \"importance\": \"low\",\n              \"optional\": true\n            },\n            {\n              \"name\": \"kind\",\n              \"type\": \"select\",\n              \"label\": \"Type kind, refer to <a target=\\\"_blank\\\" href=\\\"https://html.spec.whatwg.org/multipage/embedded-content.html#the-track-element\\\">HTML living standard</a>\",\n              \"importance\": \"low\",\n              \"default\": \"descriptions\",\n              \"options\": [\n                {\n                  \"value\": \"subtitles\",\n                  \"label\": \"Subtitles\"\n                },\n                {\n                  \"value\": \"captions\",\n                  \"label\": \"Captions\"\n                },\n                {\n                  \"value\": \"descriptions\",\n                  \"label\": \"Descriptions\"\n                },\n                {\n                  \"value\": \"chapters\",\n                  \"label\": \"Chapters\"\n                }\n              ]\n            },\n            {\n              \"name\": \"srcLang\",\n              \"type\": \"text\",\n              \"label\": \"Source language, must be defined for subtitles\",\n              \"importance\": \"low\",\n              \"default\": \"en\",\n              \"description\": \"Must be a valid BCP 47 language tag. If the kind attribute is set to subtitles, then srclang must be defined.\"\n            },\n            {\n              \"name\": \"track\",\n              \"type\": \"file\",\n              \"label\": \"Track file (WebVTT)\",\n              \"importance\": \"low\"\n            }\n          ]\n        }\n      }\n    ]\n  }\n]\n', NULL, 1, 19, NULL, NULL, NULL, 1),
