(115, 'H5P.Agamotto', 'Agamotto', 1, 6, 11, 1, 0, 'iframe', 'dist/h5p-agamotto.js', 'dist/h5p-agamotto.css', '', '[\n  {\n    \"name\": \"title\",\n    \"label\": \"Heading\",\n    \"importance\": \"high\",\n    \"type\": \"text\",\n    \"optional\": true,\n    \"placeholder\": \"Here you can add an optional heading.\",\n    \"description\": \"The heading you\'d like to show above the image\"\n  },\n  {\n    \"name\": \"items\",\n    \"type\": \"list\",\n    \"label\": \"Items\",\n    \"entity\": \"item\",\n    \"widgets\": [\n      {\n        \"name\": \"VerticalTabs\",\n        \"label\": \"Default\"\n      }\n    ],\n    \"importance\": \"medium\",\n    \"min\": 2,\n    \"max\": 50,\n    \"field\": {\n      \"name\": \"item\",\n      \"type\": \"group\",\n      \"label\": \"Item\",\n      \"importance\": \"low\",\n      \"expanded\": true,\n      \"fields\": [\n        {\n          \"name\": \"image\",\n          \"type\": \"library\",\n          \"label\": \"Image\",\n          \"importance\": \"low\",\n          \"options\": [\n            \"H5P.Image 1.1\"\n          ],\n          \"optional\": false\n        },\n        {\n          \"name\": \"labelText\",\n          \"label\": \"Label\",\n          \"importance\": \"low\",\n          \"type\": \"text\",\n          \"optional\": true,\n          \"description\": \"Optional label for a tick. Please make sure it\'s not too long, or it will be hidden.\"\n        },\n        {\n          \"name\": \"description\",\n          \"type\": \"text\",\n          \"importance\": \"low\",\n          \"widget\": \"html\",\n          \"label\": \"Description\",\n          \"optional\": true,\n          \"placeholder\": \"My image description ...\",\n          \"description\": \"Optional description for the image\",\n          \"enterMode\": \"p\",\n          \"tags\": [\n            \"strong\",\n            \"em\",\n            \"sub\",\n            \"sup\",\n            \"h3\",\n            \"h4\",\n            \"ul\",\n            \"ol\",\n            \"a\",\n            \"pre\",\n            \"code\"\n          ]\n        },\n        {\n          \"name\": \"audio\",\n          \"type\": \"audio\",\n          \"importance\": \"low\",\n          \"label\": \"Audio\",\n          \"description\": \"Optional audio that plays when an image is shown.\",\n          \"optional\": true,\n          \"widgetExtensions\": [\n            \"AudioRecorder\"\n          ]\n        }\n      ]\n    }\n  },\n  {\n    \"name\": \"behaviour\",\n    \"type\": \"group\",\n    \"label\": \"Behavioural settings\",\n    \"importance\": \"low\",\n    \"description\": \"These options will let you control how the task behaves.\",\n    \"fields\": [\n      {\n        \"name\": \"startImage\",\n        \"importance\": \"medium\",\n        \"type\": \"number\",\n        \"label\": \"Start image\",\n        \"description\": \"Set the number of the image to start with.\",\n        \"default\": 1,\n        \"min\": 1,\n        \"max\": 50\n      },\n      {\n        \"name\": \"snap\",\n        \"importance\": \"medium\",\n        \"type\": \"boolean\",\n        \"label\": \"Snap slider\",\n        \"description\": \"If activated, the slider will snap to an image\'s position.\",\n        \"default\": true\n      },\n      {\n        \"name\": \"ticks\",\n        \"importance\": \"medium\",\n        \"type\": \"boolean\",\n        \"label\": \"Display tick marks\",\n        \"description\": \"If activated, the slider bar will display a tick mark for each image.\",\n        \"default\": false\n      },\n      {\n        \"name\": \"labels\",\n        \"importance\": \"medium\",\n        \"type\": \"boolean\",\n        \"label\": \"Display labels\",\n        \"description\": \"If activated, the slider bar will display a label instead of/in addition to tick marks.\",\n        \"default\": false\n      },\n      {\n        \"name\": \"transparencyReplacementColor\",\n        \"importance\": \"medium\",\n        \"type\": \"text\",\n        \"label\": \"Transparency Replacement Color\",\n        \"description\": \"Set the color that will replace transparent areas of the images.\",\n        \"optional\": true,\n        \"default\": \"#000000\",\n        \"widget\": \"colorSelector\",\n        \"spectrum\": {\n          \"showInput\": true\n        }\n      },\n      {\n        \"name\": \"imagesDescriptionsRatio\",\n        \"importance\": \"medium\",\n        \"type\": \"number\",\n        \"label\": \"Image space in fullscreen mode\",\n        \"description\": \"If you have descriptions in addition to the images, set the the percentage of space that the images should use in fullscreen mode.\",\n        \"default\": 70,\n        \"min\": 50,\n        \"max\": 100\n      }\n    ]\n  },\n  {\n    \"name\": \"a11y\",\n    \"type\": \"group\",\n    \"common\": true,\n    \"label\": \"Readspeaker\",\n    \"importance\": \"low\",\n    \"fields\": [\n      {\n        \"name\": \"image\",\n        \"type\": \"text\",\n        \"label\": \"Image\",\n        \"importance\": \"low\",\n        \"default\": \"Image\"\n      },\n      {\n        \"name\": \"imageSlider\",\n        \"type\": \"text\",\n        \"label\": \"Image Slider\",\n        \"importance\": \"low\",\n        \"default\": \"Image Slider\"\n      },\n      {\n        \"name\": \"mute\",\n        \"type\": \"text\",\n        \"label\": \"Mute title\",\n        \"importance\": \"low\",\n        \"default\": \"Mute, currently unmuted\"\n      },\n      {\n        \"name\": \"unmute\",\n        \"type\": \"text\",\n        \"label\": \"Unmute title\",\n        \"importance\": \"low\",\n        \"default\": \"Unmute, currently muted\"\n      },\n      {\n        \"name\": \"buttonFullscreenEnter\",\n        \"type\": \"text\",\n        \"label\": \"Title for fullscreen button (enter)\",\n        \"importance\": \"low\",\n        \"default\": \"Enter fullscreen mode\"\n      },\n      {\n        \"name\": \"buttonFullscreenExit\",\n        \"type\": \"text\",\n        \"label\": \"Title for fullscreen button (exit)\",\n        \"importance\": \"low\",\n        \"default\": \"Exit fullscreen mode\"\n      }\n    ]\n  }\n]\n', NULL, 1, 27, NULL, 'https://h5p.org/agamotto-tutorial', 'https://h5p.org/node/79243', 1),
(116, 'H5P.Audio', 'Audio', 1, 2, 14, 1, 0, 'iframe', 'scripts/audio.js', 'styles/audio.css', '', '[\n  {\n    \"name\": \"files\",\n    \"type\": \"audio\",\n    \"importance\": \"high\",\n    \"label\": \"Source files\"\n  },\n  {\n    \"name\": \"playerMode\",\n    \"type\": \"select\",\n    \"importance\": \"low\",\n    \"label\": \"Player mode\",\n    \"description\": \"Select the layout of the player.\",\n    \"options\": [\n      {\n        \"value\": \"minimalistic\",\n        \"label\": \"Minimalistic\"\n      },\n      {\n        \"value\": \"full\",\n        \"label\": \"Full\"\n      },\n      {\n        \"value\": \"transparent\",\n        \"label\": \"Transparent\"\n      }\n    ],\n    \"default\": \"minimalistic\"\n  },\n  {\n    \"name\": \"fitToWrapper\",\n    \"type\": \"boolean\",\n    \"importance\": \"low\",\n    \"label\": \"Fit to wrapper\",\n    \"default\": false,\n    \"descriptions\": \"Adjust audioplayer size to use available space\"\n  },\n  {\n    \"name\": \"controls\",\n    \"type\": \"boolean\",\n    \"importance\": \"low\",\n    \"label\": \"Enable controls\",\n    \"default\": true,\n    \"description\": \"Controls allow the user to for instance pause the audio\"\n  },\n  {\n    \"name\": \"autoplay\",\n    \"type\": \"boolean\",\n    \"importance\": \"low\",\n    \"label\": \"Enable autoplay\",\n    \"description\": \"With autoplay the audio starts to play immediately. If autoplay is disabled the user presses a play button to start the audio.\"\n  },\n  {\n    \"name\": \"copyright\",\n    \"type\": \"group\",\n    \"importance\": \"low\",\n    \"label\": \"Copyright information\",\n    \"deprecated\": true,\n    \"optional\": true,\n    \"fields\": [\n      {\n        \"name\": \"title\",\n        \"type\": \"text\",\n        \"label\": \"Title\",\n        \"placeholder\": \"Für Elise\",\n        \"optional\": true\n      },\n      {\n        \"name\": \"author\",\n        \"type\": \"text\",\n        \"label\": \"Author\",\n        \"placeholder\": \"Ludwig van Beethoven\",\n        \"optional\": true\n      },\n      {\n        \"name\": \"source\",\n        \"type\": \"text\",\n        \"label\": \"Source\",\n        \"placeholder\": \"http://en.wikipedia.org/wiki/F%C3%BCr_Elise\",\n        \"optional\": true,\n        \"regexp\": {\n          \"pattern\": \"^http[s]?://.+\",\n          \"modifiers\": \"i\"\n        }\n      },\n      {\n        \"name\": \"license\",\n        \"type\": \"select\",\n        \"label\": \"License\",\n        \"default\": \"U\",\n        \"options\": [\n          {\n            \"value\": \"U\",\n            \"label\": \"Undisclosed\"\n          },\n          {\n            \"value\": \"CC BY\",\n            \"label\": \"Attribution\"\n          },\n          {\n            \"value\": \"CC BY-SA\",\n            \"label\": \"Attribution-ShareAlike\"\n          },\n          {\n            \"value\": \"CC BY-ND\",\n            \"label\": \"Attribution-NoDerivs\"\n          },\n          {\n            \"value\": \"CC BY-NC\",\n            \"label\": \"Attribution-NonCommercial\"\n          },\n          {\n            \"value\": \"CC BY-NC-SA\",\n            \"label\": \"Attribution-NonCommercial-ShareAlike\"\n          },\n          {\n            \"value\": \"CC BY-NC-ND\",\n            \"label\": \"Attribution-NonCommercial-NoDerivs\"\n          },\n          {\n            \"value\": \"GNU GPL\",\n            \"label\": \"General Public License\"\n          },\n          {\n            \"value\": \"PD\",\n            \"label\": \"Public Domain\"\n          },\n          {\n            \"value\": \"ODC PDDL\",\n            \"label\": \"Public Domain Dedication and Licence\"\n          },\n          {\n            \"value\": \"CC PDM\",\n            \"label\": \"Public Domain Mark\"\n          },\n          {\n            \"value\": \"C\",\n            \"label\": \"Copyright\"\n          }\n        ]\n      }\n    ]\n  },\n  {\n    \"name\": \"contentName\",\n    \"type\": \"text\",\n    \"importance\": \"low\",\n    \"label\": \"Audio content name\",\n    \"common\": true,\n    \"default\": \"Audio\"\n  },\n  {\n    \"name\": \"audioNotSupported\",\n    \"type\": \"text\",\n    \"label\": \"Audio not supported message\",\n    \"importance\": \"low\",\n    \"common\": true,\n    \"default\": \"Your browser does not support this audio\"\n  }\n]', NULL, 1, 4, NULL, NULL, NULL, 1),
(117, 'H5P.ImageSequencing', 'Image Sequencing', 1, 1, 0, 1, 0, 'iframe', 'scripts/h5p-image-sequencing.js, scripts/h5p-image-sequencing-card.js, scripts/h5p-image-sequencing-counter.js, scripts/h5p-image-sequencing-timer.js', 'styles/h5p-image-sequencing.css', '', '[\n  {\n    \"label\": \"Task Description\",\n    \"name\": \"taskDescription\",\n    \"type\": \"text\",\n    \"default\": \"Drag to arrange the images in the correct sequence\",\n    \"description\": \"A guide telling the user how to solve this task.\",\n    \"importance\": \"high\"\n  },\n  {\n    \"label\": \"Alternate Task Description\",\n    \"name\": \"altTaskDescription\",\n    \"type\": \"text\",\n    \"default\": \"Make the following list be ordered correctly. Use the cursor keys to navigate through the list items, use space to activate or deactivate an item and the cursor keys to move it\",\n    \"description\": \"A guide intended for visually impaired users on how to solve this task.\",\n    \"importance\": \"high\"\n  },\n  {\n    \"name\": \"sequenceImages\",\n    \"type\": \"list\",\n    \"widgets\": [\n      {\n        \"name\": \"VerticalTabs\",\n        \"label\": \"Default\"\n      }\n    ],\n    \"label\": \"Images\",\n    \"importance\": \"high\",\n    \"entity\": \"image\",\n    \"min\": 3,\n    \"field\": {\n      \"type\": \"group\",\n      \"name\": \"imageElement\",\n      \"label\": \"Image Element\",\n      \"importance\": \"high\",\n      \"fields\": [\n        {\n          \"name\": \"image\",\n          \"type\": \"image\",\n          \"label\": \"Image\",\n          \"importance\": \"high\"\n        },\n        {\n          \"name\": \"imageDescription\",\n          \"type\": \"text\",\n          \"label\": \"Image Description\",\n          \"importance\": \"low\",\n          \"description\": \"An image description for users who cannot recognize the image\"\n        },\n        {\n          \"name\": \"audio\",\n          \"description\": \"An optional audio for the card to play\",\n          \"type\": \"audio\",\n          \"label\": \"Audio files\",\n          \"importance\": \"low\",\n          \"optional\": true\n        }\n      ]\n    }\n  },\n  {\n    \"name\": \"behaviour\",\n    \"type\": \"group\",\n    \"label\": \"Behavioural settings\",\n    \"importance\": \"low\",\n    \"description\": \"These options will let you control how the game behaves.\",\n    \"optional\": true,\n    \"fields\": [\n      {\n        \"name\": \"enableSolution\",\n        \"type\": \"boolean\",\n        \"label\": \"Add a show solution button for the game\",\n        \"importance\": \"low\",\n        \"default\": true\n      },\n      {\n        \"name\": \"enableRetry\",\n        \"type\": \"boolean\",\n        \"label\": \"Add button for retrying when the game is over\",\n        \"importance\": \"low\",\n        \"default\": true\n      },\n      {\n        \"name\": \"enableResume\",\n        \"type\": \"boolean\",\n        \"label\": \"Add button for resuming from the current state \",\n        \"importance\": \"low\",\n        \"default\": true\n      }\n    ]\n  },\n  {\n    \"label\": \"Localization\",\n    \"importance\": \"low\",\n    \"name\": \"l10n\",\n    \"type\": \"group\",\n    \"common\": true,\n    \"fields\": [\n      {\n        \"label\": \"Total Moves text\",\n        \"importance\": \"low\",\n        \"name\": \"totalMoves\",\n        \"type\": \"text\",\n        \"default\": \"Total Moves\"\n      },\n      {\n        \"label\": \"Time spent text\",\n        \"importance\": \"low\",\n        \"name\": \"timeSpent\",\n        \"type\": \"text\",\n        \"default\": \"Time spent\"\n      },\n      {\n        \"label\": \"Feedback text\",\n        \"importance\": \"low\",\n        \"name\": \"score\",\n        \"type\": \"text\",\n        \"default\": \"You got @score of @total points\",\n        \"description\": \"Feedback text, variables available: @score and @total. Example: \'You got @score of @total possible points\'\"\n      },\n      {\n        \"label\": \"Text for \\\"Check\\\" button\",\n        \"importance\": \"low\",\n        \"name\": \"checkAnswer\",\n        \"type\": \"text\",\n        \"default\": \"Check\"\n      },\n      {\n        \"label\": \"Text for \\\"Retry\\\" button\",\n        \"importance\": \"low\",\n        \"name\": \"tryAgain\",\n        \"type\": \"text\",\n        \"default\": \"Retry\"\n      },\n      {\n        \"label\": \"Text for \\\"Show Solution\\\" button\",\n        \"importance\": \"low\",\n        \"name\": \"showSolution\",\n        \"type\": \"text\",\n        \"default\": \"ShowSolution\"\n      },\n      {\n        \"label\": \"Text for \\\"Resume\\\" button\",\n        \"importance\": \"low\",\n        \"name\": \"resume\",\n        \"type\": \"text\",\n        \"default\": \"Resume\"\n      },\n      {\n        \"name\": \"audioNotSupported\",\n        \"type\": \"text\",\n        \"label\": \"Audio not supported message\",\n        \"importance\": \"low\",\n        \"common\": true,\n        \"default\": \"Audio Error\"\n      },\n      {\n        \"name\": \"ariaPlay\",\n        \"type\": \"text\",\n        \"label\": \"Play button (text for readspeakers)\",\n        \"importance\": \"low\",\n        \"common\": true,\n        \"default\": \"Play the corresponding audio\"\n      },\n      {\n        \"name\": \"ariaMoveDescription\",\n        \"type\": \"text\",\n        \"label\": \"Card moving description (text for readspeakers)\",\n        \"description\": \"@posSrc : card initial position, @posDes : card final position\",\n        \"importance\": \"low\",\n        \"common\": true,\n        \"default\": \"Moved @cardDesc from @posSrc to @posDes\"\n      },\n      {\n        \"name\": \"ariaCardDesc\",\n        \"type\": \"text\",\n        \"label\": \"Default Card Description (text for readspeakers)\",\n        \"importance\": \"low\",\n        \"common\": true,\n        \"default\": \"sequencing item\"\n      }\n    ]\n  }\n]\n', NULL, NULL, NULL, NULL, 'https://h5p.org/tutorial-image-sequencing', 'https://h5p.org/content-types/image-sequencing', 1);
INSERT INTO `mdl_h5p_libraries` (`id`, `machinename`, `title`, `majorversion`, `minorversion`, `patchversion`, `runnable`, `fullscreen`, `embedtypes`, `preloadedjs`, `preloadedcss`, `droplibrarycss`, `semantics`, `addto`, `coremajor`, `coreminor`, `metadatasettings`, `tutorial`, `example`, `enabled`) VALUES
(118, 'H5P.Flashcards', 'Flashcards', 1, 7, 10, 1, 0, 'iframe', 'js/xapi.js, js/flashcards.js', 'css/flashcards.css', '', '[\n  {\n    \"name\": \"description\",\n    \"type\": \"text\",\n    \"label\": \"Task description\",\n    \"importance\": \"high\"\n  },\n  {\n    \"name\": \"cards\",\n    \"type\": \"list\",\n    \"widgets\": [\n      {\n        \"name\": \"VerticalTabs\",\n        \"label\": \"Default\"\n      }\n    ],\n    \"label\": \"Cards\",\n    \"entity\": \"card\",\n    \"importance\": \"high\",\n    \"min\": 1,\n    \"defaultNum\": 1,\n    \"field\": {\n      \"name\": \"card\",\n      \"type\": \"group\",\n      \"label\": \"Card\",\n      \"importance\": \"high\",\n      \"fields\": [\n        {\n          \"name\": \"text\",\n          \"type\": \"text\",\n          \"label\": \"Question\",\n          \"importance\": \"high\",\n          \"optional\": true,\n          \"description\": \"Optional textual question for the card. (The card may use just an image, just a text or both)\"\n        },\n        {\n          \"name\": \"answer\",\n          \"type\": \"text\",\n          \"label\": \"Answer\",\n          \"importance\": \"high\",\n          \"optional\": true,\n          \"description\": \"Answer (solution) for the card. Use a forward slash / to split alternative solutions. Use \\\\/ if a solution should contain a /.\"\n        },\n        {\n          \"name\": \"image\",\n          \"type\": \"image\",\n          \"label\": \"Image\",\n          \"importance\": \"high\",\n          \"optional\": true,\n          \"description\": \"Optional image for the card. (The card may use just an image, just a text or both)\"\n        },\n        {\n          \"name\": \"imageAltText\",\n          \"type\": \"text\",\n          \"label\": \"Alternative text for image\",\n          \"importance\": \"high\",\n          \"optional\": true\n        },\n        {\n          \"name\": \"tip\",\n          \"type\": \"group\",\n          \"label\": \"Tip\",\n          \"importance\": \"low\",\n          \"optional\": true,\n          \"fields\": [\n            {\n              \"name\": \"tip\",\n              \"label\": \"Tip text\",\n              \"importance\": \"low\",\n              \"type\": \"text\",\n              \"widget\": \"html\",\n              \"tags\": [\n                \"p\",\n                \"br\",\n                \"strong\",\n                \"em\",\n                \"code\"\n              ],\n              \"optional\": true\n            }\n          ]\n        }\n      ]\n    }\n  },\n  {\n    \"label\": \"Progress text\",\n    \"name\": \"progressText\",\n    \"type\": \"text\",\n    \"default\": \"Card @card of @total\",\n    \"importance\": \"low\",\n    \"description\": \"Progress text, variables available: @card and @total. Example: \'Card @card of @total\'\",\n    \"common\": true\n  },\n  {\n    \"label\": \"Text for the next button\",\n    \"name\": \"next\",\n    \"type\": \"text\",\n    \"default\": \"Next\",\n    \"importance\": \"low\",\n    \"common\": true\n  },\n  {\n    \"label\": \"Text for the previous button\",\n    \"name\": \"previous\",\n    \"type\": \"text\",\n    \"default\": \"Previous\",\n    \"importance\": \"low\",\n    \"common\": true\n  },\n  {\n    \"label\": \"Text for the check answers button\",\n    \"name\": \"checkAnswerText\",\n    \"type\": \"text\",\n    \"default\": \"Check\",\n    \"importance\": \"low\",\n    \"common\": true\n  },\n  {\n    \"label\": \"Require user input before the solution can be viewed\",\n    \"name\": \"showSolutionsRequiresInput\",\n    \"type\": \"boolean\",\n    \"default\": true,\n    \"importance\": \"low\",\n    \"optional\": true\n  },\n  {\n    \"label\": \"Text for the answer input field\",\n    \"name\": \"defaultAnswerText\",\n    \"type\": \"text\",\n    \"default\": \"Your answer\",\n    \"importance\": \"low\",\n    \"common\": true\n  },\n  {\n    \"label\": \"Text for correct answer\",\n    \"name\": \"correctAnswerText\",\n    \"type\": \"text\",\n    \"default\": \"Correct\",\n    \"importance\": \"low\",\n    \"common\": true\n  },\n  {\n    \"label\": \"Text for incorrect answer\",\n    \"name\": \"incorrectAnswerText\",\n    \"type\": \"text\",\n    \"default\": \"Incorrect\",\n    \"importance\": \"low\",\n    \"common\": true\n  },\n  {\n    \"label\": \"Show solution text\",\n    \"name\": \"showSolutionText\",\n    \"type\": \"text\",\n    \"default\": \"Correct answer(s)\",\n    \"importance\": \"low\",\n    \"common\": true\n  },\n  {\n    \"label\": \"Text for results title\",\n    \"name\": \"results\",\n    \"type\": \"text\",\n    \"default\": \"Results\",\n    \"importance\": \"low\",\n    \"common\": true\n  },\n  {\n    \"label\": \"Text for number of correct\",\n    \"name\": \"ofCorrect\",\n    \"type\": \"text\",\n    \"default\": \"@score of @total correct\",\n    \"importance\": \"low\",\n    \"description\": \"Result text, variables available: @score and @total. Example: \'@score of @total correct\'\",\n    \"common\": true\n  },\n  {\n    \"label\": \"Text for show results\",\n    \"name\": \"showResults\",\n    \"type\": \"text\",\n    \"default\": \"Show results\",\n    \"importance\": \"low\",\n    \"common\": true\n  },\n  {\n    \"label\": \"Text for short answer label\",\n    \"name\": \"answerShortText\",\n    \"type\": \"text\",\n    \"default\": \"A:\",\n    \"importance\": \"low\",\n    \"common\": true\n  },\n  {\n    \"label\": \"Text for \\\"retry\\\" button\",\n    \"name\": \"retry\",\n    \"type\": \"text\",\n    \"default\": \"Retry\",\n    \"importance\": \"low\",\n    \"common\": true\n  },\n  {\n    \"label\": \"Case sensitive\",\n    \"name\": \"caseSensitive\",\n    \"type\": \"boolean\",\n    \"default\": false,\n    \"description\": \"Makes sure the user input has to be exactly the same as the answer.\"\n  },\n  {\n    \"label\": \"Incorrect text for assistive technologies\",\n    \"name\": \"cardAnnouncement\",\n    \"type\": \"text\",\n    \"default\": \"Incorrect answer. Correct answer was @answer\",\n    \"description\": \"Text that will be announced to assistive technologies. Use @answer as variable.\",\n    \"common\": true\n  },\n  {\n    \"label\": \"Correct feedback text for assistive technologies\",\n    \"name\": \"correctAnswerAnnouncement\",\n    \"type\": \"text\",\n    \"default\": \"@answer is correct.\",\n    \"description\": \"Text that will be announced to assistive technologies when a card is answered correctly. Use @answer as variable.\",\n    \"common\": true\n  },\n  {\n    \"label\": \"Card change for assistive technologies\",\n    \"name\": \"pageAnnouncement\",\n    \"type\": \"text\",\n    \"default\": \"Page @current of @total\",\n    \"description\": \"Text that will be announced to assistive technologies when navigating between cards. Use @current and @total as variables.\",\n    \"common\": true\n  },\n  {\n    \"name\": \"randomCards\",\n    \"type\": \"boolean\",\n    \"label\": \"Randomize cards\",\n    \"importance\": \"low\",\n    \"description\": \"Enable to randomize the order of cards on display.\",\n    \"default\": false\n  }\n]\n', NULL, 1, 4, NULL, 'https://h5p.org/tutorial-flashcards', 'https://h5p.org/flashcards', 1),
(119, 'H5P.SpeakTheWordsSet', 'Speak the Words Set', 1, 3, 4, 1, 0, 'iframe', 'dist/dist.js', '', '', '[\n  {\n    \"name\": \"introduction\",\n    \"label\": \"Introduction\",\n    \"type\": \"group\",\n    \"fields\": [\n      {\n        \"name\": \"showIntroPage\",\n        \"type\": \"boolean\",\n        \"optional\": true,\n        \"default\": false,\n        \"label\": \"Display introduction\",\n        \"importance\": \"low\"\n      },\n      {\n        \"name\": \"introductionImage\",\n        \"type\": \"image\",\n        \"label\": \"Introduction image\",\n        \"optional\": true,\n        \"widget\": \"showWhen\",\n        \"showWhen\": {\n          \"rules\": [\n            {\n              \"field\": \"showIntroPage\",\n              \"equals\": true\n            }\n          ]\n        }\n      },\n      {\n        \"name\": \"introductionImageAltText\",\n        \"type\": \"text\",\n        \"label\": \"Alternative text for introduction image\",\n        \"optional\": true,\n        \"widget\": \"showWhen\",\n        \"showWhen\": {\n          \"rules\": [\n            {\n              \"field\": \"showIntroPage\",\n              \"equals\": true\n            }\n          ]\n        }\n      },\n      {\n        \"name\": \"introductionTitle\",\n        \"type\": \"text\",\n        \"label\": \"Title\",\n        \"optional\": true,\n        \"widget\": \"showWhen\",\n        \"showWhen\": {\n          \"rules\": [\n            {\n              \"field\": \"showIntroPage\",\n              \"equals\": true\n            }\n          ]\n        }\n      },\n      {\n        \"name\": \"introductionText\",\n        \"type\": \"text\",\n        \"label\": \"Introduction text\",\n        \"optional\": true,\n        \"description\": \"This title will be displayed above the introduction text.\",\n        \"widget\": \"showWhen\",\n        \"showWhen\": {\n          \"widget\": \"html\",\n          \"rules\": [\n            {\n              \"field\": \"showIntroPage\",\n              \"equals\": true\n            }\n          ]\n        },\n        \"tags\": [\n          \"sub\",\n          \"sup\",\n          \"strong\",\n          \"em\",\n          \"code\"\n        ]\n      }\n    ]\n  },\n  {\n    \"name\": \"questions\",\n    \"label\": \"Questions\",\n    \"importance\": \"high\",\n    \"type\": \"list\",\n    \"widgets\": [\n      {\n        \"name\": \"VerticalTabs\",\n        \"label\": \"Default\"\n      }\n    ],\n    \"min\": 1,\n    \"entity\": \"Question\",\n    \"field\": {\n      \"name\": \"question\",\n      \"type\": \"library\",\n      \"label\": \"Question\",\n      \"importance\": \"high\",\n      \"options\": [\n        \"H5P.SpeakTheWords 1.5\"\n      ]\n    }\n  },\n  {\n    \"name\": \"overallFeedback\",\n    \"type\": \"group\",\n    \"label\": \"Overall Feedback\",\n    \"importance\": \"low\",\n    \"expanded\": true,\n    \"fields\": [\n      {\n        \"name\": \"overallFeedback\",\n        \"type\": \"list\",\n        \"widgets\": [\n          {\n            \"name\": \"RangeList\",\n            \"label\": \"Default\"\n          }\n        ],\n        \"importance\": \"high\",\n        \"label\": \"Define custom feedback for any score range\",\n        \"description\": \"Click the \\\"Add range\\\" button to add as many ranges as you need. Example: 0-20% Bad score, 21-91% Average Score, 91-100% Great Score!\",\n        \"entity\": \"range\",\n        \"min\": 1,\n        \"defaultNum\": 1,\n        \"optional\": true,\n        \"field\": {\n          \"name\": \"overallFeedback\",\n          \"type\": \"group\",\n          \"importance\": \"low\",\n          \"fields\": [\n            {\n              \"name\": \"from\",\n              \"type\": \"number\",\n              \"label\": \"Score Range\",\n              \"min\": 0,\n              \"max\": 100,\n              \"default\": 0,\n              \"unit\": \"%\"\n            },\n            {\n              \"name\": \"to\",\n              \"type\": \"number\",\n              \"min\": 0,\n              \"max\": 100,\n              \"default\": 100,\n              \"unit\": \"%\"\n            },\n            {\n              \"name\": \"feedback\",\n              \"type\": \"text\",\n              \"label\": \"Feedback for defined score range\",\n              \"importance\": \"low\",\n              \"placeholder\": \"Fill in the feedback\",\n              \"optional\": true\n            }\n          ]\n        }\n      }\n    ]\n  },\n  {\n    \"name\": \"l10n\",\n    \"type\": \"group\",\n    \"label\": \"Speak The Words Set labels and texts\",\n    \"importance\": \"low\",\n    \"common\": true,\n    \"fields\": [\n      {\n        \"name\": \"introductionButtonLabel\",\n        \"label\": \"Introduction button label\",\n        \"type\": \"text\",\n        \"default\": \"Start Course!\"\n      },\n      {\n        \"name\": \"solutionScreenResultsLabel\",\n        \"label\": \"Solution screen results label\",\n        \"type\": \"text\",\n        \"default\": \"Your results:\"\n      },\n      {\n        \"name\": \"showSolutionsButtonLabel\",\n        \"label\": \"Show solutions button label\",\n        \"type\": \"text\",\n        \"default\": \"Show solution\"\n      },\n      {\n        \"name\": \"retryButtonLabel\",\n        \"label\": \"Retry button label\",\n        \"type\": \"text\",\n        \"default\": \"Retry\"\n      },\n      {\n        \"name\": \"finishButtonLabel\",\n        \"label\": \"Finish button label\",\n        \"type\": \"text\",\n        \"default\": \"Finish\"\n      },\n      {\n        \"name\": \"nextQuestionAriaLabel\",\n        \"label\": \"Next question accessibility label\",\n        \"type\": \"text\",\n        \"default\": \"Next question\"\n      },\n      {\n        \"name\": \"previousQuestionAriaLabel\",\n        \"label\": \"Previous question accessibility label\",\n        \"type\": \"text\",\n        \"default\": \"Previous question\"\n      },\n      {\n        \"name\": \"navigationBarTitle\",\n        \"label\": \"Navigation bar title\",\n        \"description\": \"Titles for questions in navigation bar. \\\":num\\\" will be replaced with the actual slide number.\",\n        \"type\": \"text\",\n        \"default\": \"Slide :num\"\n      },\n      {\n        \"name\": \"answeredSlideAriaLabel\",\n        \"label\": \"Answered slide accessibility label\",\n        \"type\": \"text\",\n        \"default\": \"Answered\"\n      },\n      {\n        \"name\": \"activeSlideAriaLabel\",\n        \"label\": \"Active slide accessibility label\",\n        \"type\": \"text\",\n        \"default\": \"Currently active\"\n      }\n    ]\n  }\n]\n', NULL, NULL, NULL, NULL, NULL, 'https://h5p.org/speak-the-words-set', 1),
(120, 'H5P.ImageSlide', 'Image Slide', 1, 1, 4, 0, 0, '', 'image-slide.js', 'image-slide.css', '', '[\n  {\n    \"label\": \"Image\",\n    \"name\": \"image\",\n    \"type\": \"library\",\n    \"options\": [\n      \"H5P.Image 1.1\"\n    ]\n  }\n]', NULL, NULL, NULL, NULL, NULL, NULL, 1),
(121, 'H5P.ImageSlider', 'Image Slider', 1, 1, 9, 1, 1, 'iframe', 'image-slider.js', 'image-slider.css', '', '[\n  {\n    \"label\": \"Images\",\n    \"name\": \"imageSlides\",\n    \"type\": \"list\",\n    \"field\": {\n      \"label\": \"Image Slide\",\n      \"name\": \"imageSlide\",\n      \"type\": \"group\",\n      \"fields\": [\n        {\n          \"label\": \"Image Slide\",\n          \"name\": \"imageSlide\",\n          \"type\": \"library\",\n          \"options\": [\n            \"H5P.ImageSlide 1.1\"\n          ]\n        }\n      ]\n    }\n  },\n  {\n    \"label\": \"Aspect ratio\",\n    \"name\": \"aspectRatioMode\",\n    \"type\": \"select\",\n    \"description\": \"Automatic means fixed aspect ratio automatically determined based on the images\",\n    \"default\": \"auto\",\n    \"options\": [\n      {\n        \"value\": \"auto\",\n        \"label\": \"Automatic\"\n      },\n      {\n        \"value\": \"custom\",\n        \"label\": \"Custom\"\n      },\n      {\n        \"value\": \"notFixed\",\n        \"label\": \"Not fixed\"\n      }\n    ]\n  },\n  {\n    \"label\": \"Aspect Ratio Settings\",\n    \"name\": \"aspectRatio\",\n    \"type\": \"group\",\n    \"widget\": \"showWhen\",\n    \"expanded\": true,\n    \"showWhen\": {\n      \"rules\": [\n        {\n          \"field\": \"aspectRatioMode\",\n          \"equals\": \"custom\"\n        }\n      ]\n    },\n    \"fields\": [\n      {\n        \"label\": \"Aspect ratio width\",\n        \"name\": \"aspectWidth\",\n        \"type\": \"number\",\n        \"default\": 4,\n        \"description\": \"If you use 4 here, and 3 for the height the aspect ratio will be 4:3\"\n      },\n      {\n        \"label\": \"Aspect ratio height\",\n        \"name\": \"aspectHeight\",\n        \"type\": \"number\",\n        \"default\": 3,\n        \"description\": \"If you use 3 here, and 4 for the width the aspect ratio will be 4:3\"\n      }\n    ]\n  },\n  {\n    \"name\": \"a11y\",\n    \"type\": \"group\",\n    \"label\": \"Image slider accessibility\",\n    \"importance\": \"low\",\n    \"common\": true,\n    \"fields\": [\n      {\n        \"name\": \"nextSlide\",\n        \"type\": \"text\",\n        \"label\": \"Label for next slide buttons\",\n        \"importance\": \"low\",\n        \"default\": \"Next Image\",\n        \"description\": \"This is only used for read-speakers. It won\'t be displayed.\"\n      },\n      {\n        \"name\": \"prevSlide\",\n        \"type\": \"text\",\n        \"label\": \"Label for previous slide buttons\",\n        \"importance\": \"low\",\n        \"default\": \"Previous Image\",\n        \"description\": \"This is only used for read-speakers. It won\'t be displayed.\"\n      },\n      {\n        \"name\": \"gotoSlide\",\n        \"type\": \"text\",\n        \"label\": \"Label for slide buttons\",\n        \"importance\": \"low\",\n        \"default\": \"Go to image %slide\",\n        \"description\": \"This is only used for read-speakers. It won\'t be displayed. %slide is a variable and will be replaced with the image number.\"\n      }\n    ]\n  }\n]', NULL, NULL, NULL, NULL, 'https://h5p.org/tutorial-image-slider', 'https://h5p.org/image-slider', 1),
(122, 'H5P.Essay', 'Essay', 1, 5, 13, 1, 0, 'iframe', 'scripts/essay.js, scripts/inputfield.js', 'styles/essay.css', '', '[\n  {\n    \"name\": \"media\",\n    \"type\": \"group\",\n    \"label\": \"Media\",\n    \"importance\": \"medium\",\n    \"fields\": [\n      {\n        \"name\": \"type\",\n        \"type\": \"library\",\n        \"label\": \"Type\",\n        \"importance\": \"medium\",\n        \"options\": [\n          \"H5P.Image 1.1\",\n          \"H5P.Video 1.6\",\n          \"H5P.Audio 1.5\"\n        ],\n        \"optional\": true,\n        \"description\": \"Optional media to display above the question.\"\n      },\n      {\n        \"name\": \"disableImageZooming\",\n        \"type\": \"boolean\",\n        \"label\": \"Disable image zooming\",\n        \"importance\": \"low\",\n        \"default\": false,\n        \"optional\": true,\n        \"widget\": \"showWhen\",\n        \"showWhen\": {\n          \"rules\": [\n            {\n              \"field\": \"type\",\n              \"equals\": \"H5P.Image 1.1\"\n            }\n          ]\n        }\n      }\n    ]\n  },\n  {\n    \"name\": \"taskDescription\",\n    \"label\": \"Task description\",\n    \"type\": \"text\",\n    \"widget\": \"html\",\n    \"importance\": \"high\",\n    \"description\": \"Describe your task here. The task description will appear above text input area.\",\n    \"placeholder\": \"Summarize the book in 500 characters ...\",\n    \"enterMode\": \"div\",\n    \"tags\": [\n      \"strong\",\n      \"em\",\n      \"u\",\n      \"a\",\n      \"ul\",\n      \"ol\",\n      \"h2\",\n      \"h3\",\n      \"hr\",\n      \"pre\",\n      \"code\"\n    ]\n  },\n  {\n    \"name\": \"placeholderText\",\n    \"label\": \"Help text\",\n    \"type\": \"text\",\n    \"description\": \"This text should help the user to get started.\",\n    \"placeholder\": \"This book is about ...\",\n    \"importance\": \"low\",\n    \"optional\": true\n  },\n  {\n    \"name\": \"solution\",\n    \"type\": \"group\",\n    \"label\": \"Sample solution\",\n    \"importance\": \"high\",\n    \"expanded\": true,\n    \"description\": \"You can optionally add a sample solution that\'s shown after the student created a text. It\'s called sample solution because there probably is not only one solution.\",\n    \"fields\": [\n      {\n        \"name\": \"introduction\",\n        \"type\": \"text\",\n        \"label\": \"Introduction\",\n        \"importance\": \"low\",\n        \"description\": \"You can optionally leave the students some explanations about your example. The explanation will only show up if you add an example, too.\",\n        \"placeholder\": \"Please remember that you were not expected to come up with the exact same solution. It\'s just a good example.\",\n        \"optional\": true,\n        \"widget\": \"html\",\n        \"enterMode\": \"div\",\n        \"tags\": [\n          \"strong\",\n          \"em\",\n          \"u\",\n          \"a\",\n          \"ul\",\n          \"ol\",\n          \"hr\",\n          \"code\"\n        ]\n      },\n      {\n        \"name\": \"sample\",\n        \"type\": \"text\",\n        \"label\": \"Sample solution text\",\n        \"importance\": \"low\",\n        \"description\": \"The student will see a \\\"Show solution\\\" button after submitting if you provide some text here.\",\n        \"optional\": true,\n        \"widget\": \"html\",\n        \"enterMode\": \"div\",\n        \"tags\": [\n          \"strong\",\n          \"a\"\n        ]\n      }\n    ]\n  },\n  {\n    \"name\": \"keywords\",\n    \"label\": \"Keywords\",\n    \"importance\": \"high\",\n    \"type\": \"list\",\n    \"widgets\": [\n      {\n        \"name\": \"VerticalTabs\",\n        \"label\": \"Default\"\n      }\n    ],\n    \"min\": 1,\n    \"entity\": \"Keyword\",\n    \"field\": {\n      \"name\": \"groupy\",\n      \"type\": \"group\",\n      \"label\": \"Keyword\",\n      \"fields\": [\n        {\n          \"name\": \"keyword\",\n          \"type\": \"text\",\n          \"label\": \"Keyword\",\n          \"description\": \"Keyword or phrase to look for. Use an asterisk \'*\' as a wildcard for one or more characters. Use a slash \'/\' at the beginning and the end to use a regular expression.\",\n          \"importance\": \"medium\"\n        },\n        {\n          \"name\": \"alternatives\",\n          \"type\": \"list\",\n          \"label\": \"Variations\",\n          \"description\": \"Add optional variations for this keyword. Example: For a \'city\' add alternatives \'town\', \'municipality\' etc. Points will be awarded if the user includes any of the specified alternatives.\",\n          \"importance\": \"medium\",\n          \"entity\": \"variation\",\n          \"optional\": true,\n          \"min\": 0,\n          \"field\": {\n            \"name\": \"alternative\",\n            \"type\": \"text\",\n            \"label\": \"Keyword variation\"\n          }\n        },\n        {\n          \"name\": \"options\",\n          \"type\": \"group\",\n          \"label\": \"Points, Options and Feedback\",\n          \"importance\": \"low\",\n          \"fields\": [\n            {\n              \"name\": \"points\",\n              \"type\": \"number\",\n              \"label\": \"Points\",\n              \"default\": 1,\n              \"description\": \"Points that the user will get if he/she includes this keyword or its alternatives in the answer.\",\n              \"min\": 0\n            },\n            {\n              \"name\": \"occurrences\",\n              \"type\": \"number\",\n              \"label\": \"Occurrences\",\n              \"default\": 1,\n              \"description\": \"Define how many occurrences of the keyword or its variations should be awarded with points.\",\n              \"min\": 1\n            },\n            {\n              \"name\": \"caseSensitive\",\n              \"type\": \"boolean\",\n              \"label\": \"Case sensitive\",\n              \"default\": true,\n              \"description\": \"Makes sure the user input has to be exactly the same as the answer.\"\n            },\n            {\n              \"name\": \"forgiveMistakes\",\n              \"type\": \"boolean\",\n              \"label\": \"Forgive minor mistakes\",\n              \"description\": \"This will accept minor spelling mistakes (3-9 characters: 1 mistake, more than 9 characters: 2 mistakes).\"\n            },\n            {\n              \"name\": \"feedbackIncluded\",\n              \"type\": \"text\",\n              \"label\": \"Feedback if keyword included\",\n              \"description\": \"This feedback will be displayed if the user includes this keyword or its alternatives in the answer.\",\n              \"optional\": true,\n              \"maxLength\": 1000\n            },\n            {\n              \"name\": \"feedbackMissed\",\n              \"type\": \"text\",\n              \"label\": \"Feedback if keyword missing\",\n              \"description\": \"This feedback will be displayed if the user doesn’t include this keyword or its alternatives in the answer.\",\n              \"optional\": true,\n              \"maxLength\": 1000\n            },\n            {\n              \"name\": \"feedbackIncludedWord\",\n              \"type\": \"select\",\n              \"label\": \"Feedback word shown if keyword included\",\n              \"importance\": \"low\",\n              \"description\": \"This option allows you to specify which word should be shown in front of your feedback if a keyword was found in the text.\",\n              \"optional\": false,\n              \"default\": \"keyword\",\n              \"options\": [\n                {\n                  \"value\": \"keyword\",\n                  \"label\": \"keyword\"\n                },\n                {\n                  \"value\": \"alternative\",\n                  \"label\": \"alternative found\"\n                },\n                {\n                  \"value\": \"answer\",\n                  \"label\": \"answer given\"\n                },\n                {\n                  \"value\": \"none\",\n                  \"label\": \"none\"\n                }\n              ]\n            },\n            {\n              \"name\": \"feedbackMissedWord\",\n              \"type\": \"select\",\n              \"label\": \"Feedback word shown if keyword missing\",\n              \"importance\": \"low\",\n              \"description\": \"This option allows you to specify which word should be shown in front of your feedback if a keyword was not found in the text.\",\n              \"optional\": false,\n              \"default\": \"none\",\n              \"options\": [\n                {\n                  \"value\": \"keyword\",\n                  \"label\": \"keyword\"\n                },\n                {\n                  \"value\": \"none\",\n                  \"label\": \"none\"\n                }\n              ]\n            }\n          ]\n        }\n      ]\n    }\n  },\n  {\n    \"name\": \"overallFeedback\",\n    \"type\": \"group\",\n    \"label\": \"Overall Feedback\",\n    \"importance\": \"low\",\n    \"expanded\": true,\n    \"fields\": [\n      {\n        \"name\": \"overallFeedback\",\n        \"type\": \"list\",\n        \"widgets\": [\n          {\n            \"name\": \"RangeList\",\n            \"label\": \"Default\"\n          }\n        ],\n        \"importance\": \"high\",\n        \"label\": \"Define custom feedback for any score range\",\n        \"description\": \"Click the \\\"Add range\\\" button to add as many ranges as you need. Example: 0-20% Bad score, 21-91% Average Score, 91-100% Great Score!\",\n        \"entity\": \"range\",\n        \"min\": 1,\n        \"defaultNum\": 1,\n        \"optional\": true,\n        \"field\": {\n          \"name\": \"overallFeedback\",\n          \"type\": \"group\",\n          \"importance\": \"low\",\n          \"fields\": [\n            {\n              \"name\": \"from\",\n              \"type\": \"number\",\n              \"label\": \"Score Range\",\n              \"min\": 0,\n              \"max\": 100,\n              \"default\": 0,\n              \"unit\": \"%\"\n            },\n            {\n              \"name\": \"to\",\n              \"type\": \"number\",\n              \"min\": 0,\n              \"max\": 100,\n              \"default\": 100,\n              \"unit\": \"%\"\n            },\n            {\n              \"name\": \"feedback\",\n              \"type\": \"text\",\n              \"label\": \"Feedback for defined score range\",\n              \"importance\": \"low\",\n              \"placeholder\": \"Fill in the feedback\",\n              \"optional\": true\n            }\n          ]\n        }\n      }\n    ]\n  },\n  {\n    \"name\": \"behaviour\",\n    \"type\": \"group\",\n    \"label\": \"Behavioural settings\",\n    \"importance\": \"low\",\n    \"description\": \"These options will let you control how the task behaves.\",\n    \"fields\": [\n      {\n        \"name\": \"minimumLength\",\n        \"label\": \"Minimum number of characters\",\n        \"type\": \"number\",\n        \"description\": \"Specify the minimum number of characters that the user must enter.\",\n        \"importance\": \"low\",\n        \"optional\": true,\n        \"min\": \"0\"\n      },\n      {\n        \"name\": \"maximumLength\",\n        \"label\": \"Maximum number of characters\",\n        \"type\": \"number\",\n        \"description\": \"Specify the maximum number of characters that the user can enter.\",\n        \"importance\": \"low\",\n        \"optional\": true,\n        \"min\": \"0\"\n      },\n      {\n        \"name\": \"inputFieldSize\",\n        \"label\": \"Input field size\",\n        \"type\": \"select\",\n        \"importance\": \"low\",\n        \"description\": \"The size of the input field in amount of lines it will cover\",\n        \"options\": [\n          {\n            \"value\": \"1\",\n            \"label\": \"1 line\"\n          },\n          {\n            \"value\": \"3\",\n            \"label\": \"3 lines\"\n          },\n          {\n            \"value\": \"10\",\n            \"label\": \"10 lines\"\n          }\n        ],\n        \"default\": \"10\"\n      },\n      {\n        \"name\": \"enableRetry\",\n        \"label\": \"Enable \\\"Retry\\\"\",\n        \"type\": \"boolean\",\n        \"importance\": \"low\",\n        \"description\": \"If checked, learners can retry the task.\",\n        \"default\": true,\n        \"optional\": true\n      },\n      {\n        \"name\": \"ignoreScoring\",\n        \"label\": \"Ignore scoring\",\n        \"type\": \"boolean\",\n        \"importance\": \"low\",\n        \"description\": \"If checked, learners will only see the feedback that you provided for the keywords, but no score.\",\n        \"default\": false,\n        \"optional\": true\n      },\n      {\n        \"name\": \"pointsHost\",\n        \"label\": \"Points in host environment\",\n        \"type\": \"number\",\n        \"importance\": \"low\",\n        \"description\": \"Used to award points in host environment merely for answering (not shown to learner).\",\n        \"min\": 0,\n        \"default\": 1,\n        \"widget\": \"showWhen\",\n        \"showWhen\": {\n          \"rules\": [\n            {\n              \"field\": \"ignoreScoring\",\n              \"equals\": true\n            }\n          ]\n        }\n      },\n      {\n        \"name\": \"percentagePassing\",\n        \"type\": \"number\",\n        \"label\": \"Passing percentage\",\n        \"description\": \"Percentage that\'s necessary for passing\",\n        \"optional\": true,\n        \"min\": 0,\n        \"max\": 100,\n        \"widget\": \"showWhen\",\n        \"showWhen\": {\n          \"rules\": [\n            {\n              \"field\": \"ignoreScoring\",\n              \"equals\": false\n            }\n          ]\n        }\n      },\n      {\n        \"name\": \"percentageMastering\",\n        \"type\": \"number\",\n        \"label\": \"Mastering percentage\",\n        \"description\": \"Percentage that\'s necessary for mastering. Setting the mastering percentage below 100 % will lower the maximum possible score accordingly. It\'s intended to give some leeway to students, not to \\\"graciously accept\\\" solutions that do not contain all keywords.\",\n        \"optional\": true,\n        \"min\": 0,\n        \"max\": 100,\n        \"widget\": \"showWhen\",\n        \"showWhen\": {\n          \"rules\": [\n            {\n              \"field\": \"ignoreScoring\",\n              \"equals\": false\n            }\n          ]\n        }\n      },\n      {\n        \"name\": \"overrideCaseSensitive\",\n        \"type\": \"select\",\n        \"label\": \"Override case sensitive\",\n        \"importance\": \"low\",\n        \"description\": \"This option determines if the \\\"Case sensitive\\\" option will be activated for all keywords.\",\n        \"optional\": true,\n        \"options\": [\n          {\n            \"value\": \"on\",\n            \"label\": \"Enabled\"\n          },\n          {\n            \"value\": \"off\",\n            \"label\": \"Disabled\"\n          }\n        ]\n      },\n      {\n        \"name\": \"overrideForgiveMistakes\",\n        \"type\": \"select\",\n        \"label\": \"Override forgive mistakes\",\n        \"importance\": \"low\",\n        \"description\": \"This option determines if the \\\"Forgive mistakes\\\" option will be activated for all keywords.\",\n        \"optional\": true,\n        \"options\": [\n          {\n            \"value\": \"on\",\n            \"label\": \"Enabled\"\n          },\n          {\n            \"value\": \"off\",\n            \"label\": \"Disabled\"\n          }\n        ]\n      },\n      {\n        \"name\": \"linebreakReplacement\",\n        \"type\": \"select\",\n        \"label\": \"Replacement for line breaks\",\n        \"importance\": \"low\",\n        \"description\": \"By default, line breaks will be replaced with a space character. If you want to check for line breaks, e.g. in regular expressions, you can set a different replacement here.\",\n        \"options\": [\n          {\n            \"value\": \" \",\n            \"label\": \"space\"\n          },\n          {\n            \"value\": \"\\n\",\n            \"label\": \"line break (\\\\n)\"\n          }\n        ],\n        \"default\": \" \"\n      }\n    ]\n  },\n  {\n    \"name\": \"checkAnswer\",\n    \"type\": \"text\",\n    \"label\": \"Text for \\\"Check\\\" button\",\n    \"importance\": \"low\",\n    \"default\": \"Check\",\n    \"common\": true\n  },\n  {\n    \"name\": \"submitAnswer\",\n    \"type\": \"text\",\n    \"label\": \"Text for \\\"Submit\\\" button\",\n    \"importance\": \"low\",\n    \"default\": \"Submit\",\n    \"common\": true\n  },\n  {\n    \"name\": \"tryAgain\",\n    \"label\": \"Text for \\\"Retry\\\" button\",\n    \"type\": \"text\",\n    \"importance\": \"low\",\n    \"default\": \"Retry\",\n    \"common\": true\n  },\n  {\n    \"name\": \"showSolution\",\n    \"type\": \"text\",\n    \"label\": \"Text for \\\"Show solution\\\" button\",\n    \"importance\": \"low\",\n    \"default\": \"Show solution\",\n    \"common\": true\n  },\n  {\n    \"name\": \"feedbackHeader\",\n    \"type\": \"text\",\n    \"label\": \"Header for panel containing feedback for included/missing keywords\",\n    \"importance\": \"low\",\n    \"default\": \"Feedback\",\n    \"common\": true\n  },\n  {\n    \"name\": \"solutionTitle\",\n    \"type\": \"text\",\n    \"label\": \"Label for solution\",\n    \"importance\": \"low\",\n    \"default\": \"Sample solution\",\n    \"common\": true\n  },\n  {\n    \"name\": \"remainingChars\",\n    \"type\": \"text\",\n    \"label\": \"Remaining characters\",\n    \"importance\": \"low\",\n    \"common\": true,\n    \"default\": \"Remaining characters: @chars\",\n    \"description\": \"Message for remaining characters. You can use @chars which will be replaced by the corresponding number.\"\n  },\n  {\n    \"name\": \"notEnoughChars\",\n    \"type\": \"text\",\n    \"label\": \"Not enough characters\",\n    \"importance\": \"low\",\n    \"common\": true,\n    \"default\": \"You must enter at least @chars characters!\",\n    \"description\": \"Message to indicate that the text doesn\'t contain enough characters. You can use @chars which will be replaced by the corresponding number.\"\n  },\n  {\n    \"name\": \"messageSave\",\n    \"type\": \"text\",\n    \"label\": \"Save message\",\n    \"description\": \"Message indicating that the text has been saved\",\n    \"importance\": \"low\",\n    \"common\": true,\n    \"default\": \"saved\"\n  },\n  {\n    \"name\": \"ariaYourResult\",\n    \"type\": \"text\",\n    \"label\": \"Your result (not displayed)\",\n    \"description\": \"Accessibility text used for readspeakers. @score will be replaced by the number of points. @total will be replaced by the maximum possible points.\",\n    \"importance\": \"low\",\n    \"common\": true,\n    \"default\": \"You got @score out of @total points\"\n  },\n  {\n    \"name\": \"ariaNavigatedToSolution\",\n    \"type\": \"text\",\n    \"label\": \"Navigation message (not displayed)\",\n    \"description\": \"Accessibility text used for readspeakers\",\n    \"importance\": \"low\",\n    \"common\": true,\n    \"default\": \"Navigated to newly included sample solution after textarea.\"\n  },\n  {\n    \"name\": \"ariaCheck\",\n    \"type\": \"text\",\n    \"label\": \"Assistive technology description for \\\"Check\\\" button\",\n    \"importance\": \"low\",\n    \"common\": true,\n    \"default\": \"Check the answers.\"\n  },\n  {\n    \"name\": \"ariaShowSolution\",\n    \"type\": \"text\",\n    \"label\": \"Assistive technology description for \\\"Show Solution\\\" button\",\n    \"importance\": \"low\",\n    \"common\": true,\n    \"default\": \"Show the solution. You will be provided with a sample solution.\"\n  },\n  {\n    \"name\": \"ariaRetry\",\n    \"type\": \"text\",\n    \"label\": \"Assistive technology description for \\\"Retry\\\" button\",\n    \"importance\": \"low\",\n    \"common\": true,\n    \"default\": \"Retry the task. You can improve your previous answer if the author allowed that.\"\n  }\n]', NULL, 1, 27, NULL, 'https://h5p.org/tutorial-essay', 'https://h5p.org/content-types/essay', 1),
