(126, 'H5P.AppearIn', 'appear.in for Chat and Talk', 1, 0, 14, 1, 0, '', 'h5p-appear-in.js', '', '', '[\n  {\n    \"label\": \"Room name\",\n    \"name\": \"appearRoom\",\n    \"importance\": \"high\",\n    \"type\": \"text\",\n    \"default\": \"h5p\",\n    \"description\": \"Name of the appear.in room\"\n  },\n  {\n    \"label\": \"Fit to container\",\n    \"name\": \"fitToContainer\",\n    \"importance\": \"low\",\n    \"type\": \"boolean\",\n    \"default\": true,\n    \"description\": \"Make the room fit its container, will override any height and width defined with 100% values.\"\n  },\n  {\n    \"label\": \"Height\",\n    \"importance\": \"low\",\n    \"name\": \"appearHeight\",\n    \"type\": \"number\",\n    \"default\": \"400\",\n    \"description\": \"Set Height of chat/talk room\"\n  },\n  {\n    \"label\": \"Width\",\n    \"importance\": \"low\",\n    \"name\": \"appearWidth\",\n    \"type\": \"number\",\n    \"default\": \"550\",\n    \"description\": \"Set Width of chat/talk room\"\n  }\n]', NULL, NULL, NULL, NULL, NULL, NULL, 1),
(127, 'H5P.Audio', 'Audio', 1, 4, 3, 1, 0, 'iframe', 'scripts/audio.js', 'styles/audio.css', '', '[\n  {\n    \"name\": \"files\",\n    \"type\": \"audio\",\n    \"importance\": \"high\",\n    \"label\": \"Source files\",\n    \"disableCopyright\": true\n  },\n  {\n    \"name\": \"playerMode\",\n    \"type\": \"select\",\n    \"importance\": \"low\",\n    \"label\": \"Player mode\",\n    \"description\": \"Select the layout of the player.\",\n    \"options\": [\n      {\n        \"value\": \"minimalistic\",\n        \"label\": \"Minimalistic\"\n      },\n      {\n        \"value\": \"full\",\n        \"label\": \"Full\"\n      },\n      {\n        \"value\": \"transparent\",\n        \"label\": \"Transparent\"\n      }\n    ],\n    \"default\": \"minimalistic\"\n  },\n  {\n    \"name\": \"fitToWrapper\",\n    \"type\": \"boolean\",\n    \"importance\": \"low\",\n    \"label\": \"Fit to wrapper\",\n    \"default\": false,\n    \"descriptions\": \"Adjust audioplayer size to use available space\"\n  },\n  {\n    \"name\": \"controls\",\n    \"type\": \"boolean\",\n    \"importance\": \"low\",\n    \"label\": \"Enable controls\",\n    \"default\": true,\n    \"description\": \"Controls allow the user to for instance pause the audio\"\n  },\n  {\n    \"name\": \"autoplay\",\n    \"type\": \"boolean\",\n    \"importance\": \"low\",\n    \"label\": \"Enable autoplay\",\n    \"description\": \"With autoplay the audio starts to play immediately. If autoplay is disabled the user presses a play button to start the audio.\"\n  },\n  {\n    \"name\": \"playAudio\",\n    \"type\": \"text\",\n    \"importance\": \"low\",\n    \"label\": \"Play audio (Readspeaker)\",\n    \"common\": true,\n    \"default\": \"Play audio\"\n  },\n  {\n    \"name\": \"pauseAudio\",\n    \"type\": \"text\",\n    \"importance\": \"low\",\n    \"label\": \"Pause audio (Readspeaker)\",\n    \"common\": true,\n    \"default\": \"Pause audio\"\n  },\n  {\n    \"name\": \"contentName\",\n    \"type\": \"text\",\n    \"importance\": \"low\",\n    \"label\": \"Audio content name\",\n    \"common\": true,\n    \"default\": \"Audio\"\n  },\n  {\n    \"name\": \"audioNotSupported\",\n    \"type\": \"text\",\n    \"label\": \"Audio not supported message\",\n    \"importance\": \"low\",\n    \"common\": true,\n    \"default\": \"Your browser does not support this audio\"\n  }\n]\n', NULL, 1, 19, NULL, NULL, NULL, 1);
INSERT INTO `mdl_h5p_libraries` (`id`, `machinename`, `title`, `majorversion`, `minorversion`, `patchversion`, `runnable`, `fullscreen`, `embedtypes`, `preloadedjs`, `preloadedcss`, `droplibrarycss`, `semantics`, `addto`, `coremajor`, `coreminor`, `metadatasettings`, `tutorial`, `example`, `enabled`) VALUES
(128, 'H5P.CoursePresentation', 'Course Presentation', 1, 22, 0, 1, 1, 'iframe', 'dist/h5p-course-presentation.js', 'dist/h5p-course-presentation.css', '', '[\n  {\n    \"name\": \"presentation\",\n    \"type\": \"group\",\n    \"importance\": \"high\",\n    \"widget\": \"coursepresentation\",\n    \"fields\": [\n      {\n        \"name\": \"slides\",\n        \"importance\": \"high\",\n        \"type\": \"list\",\n        \"field\": {\n          \"name\": \"slide\",\n          \"importance\": \"high\",\n          \"type\": \"group\",\n          \"fields\": [\n            {\n              \"name\": \"elements\",\n              \"importance\": \"high\",\n              \"type\": \"list\",\n              \"field\": {\n                \"name\": \"element\",\n                \"importance\": \"high\",\n                \"type\": \"group\",\n                \"fields\": [\n                  {\n                    \"name\": \"x\",\n                    \"importance\": \"low\",\n                    \"type\": \"number\",\n                    \"widget\": \"none\"\n                  },\n                  {\n                    \"name\": \"y\",\n                    \"importance\": \"low\",\n                    \"type\": \"number\",\n                    \"widget\": \"none\"\n                  },\n                  {\n                    \"name\": \"width\",\n                    \"importance\": \"low\",\n                    \"type\": \"number\",\n                    \"widget\": \"none\",\n                    \"optional\": true\n                  },\n                  {\n                    \"name\": \"height\",\n                    \"importance\": \"low\",\n                    \"type\": \"number\",\n                    \"widget\": \"none\",\n                    \"optional\": true\n                  },\n                  {\n                    \"name\": \"action\",\n                    \"type\": \"library\",\n                    \"importance\": \"high\",\n                    \"options\": [\n                      \"H5P.AdvancedText 1.1\",\n                      \"H5P.Link 1.3\",\n                      \"H5P.Image 1.1\",\n                      \"H5P.Shape 1.0\",\n                      \"H5P.Video 1.5\",\n                      \"H5P.Audio 1.4\",\n                      \"H5P.Blanks 1.12\",\n                      \"H5P.SingleChoiceSet 1.11\",\n                      \"H5P.MultiChoice 1.14\",\n                      \"H5P.TrueFalse 1.6\",\n                      \"H5P.DragQuestion 1.13\",\n                      \"H5P.Summary 1.10\",\n                      \"H5P.DragText 1.8\",\n                      \"H5P.MarkTheWords 1.9\",\n                      \"H5P.Dialogcards 1.8\",\n                      \"H5P.ContinuousText 1.2\",\n                      \"H5P.ExportableTextArea 1.3\",\n                      \"H5P.Table 1.1\",\n                      \"H5P.InteractiveVideo 1.22\",\n                      \"H5P.TwitterUserFeed 1.0\"\n                    ],\n                    \"optional\": true\n                  },\n                  {\n                    \"name\": \"solution\",\n                    \"type\": \"text\",\n                    \"widget\": \"html\",\n                    \"optional\": true,\n                    \"label\": \"Comments\",\n                    \"importance\": \"low\",\n                    \"description\": \"The comments are shown when the user displays the suggested answers for all slides.\",\n                    \"enterMode\": \"p\",\n                    \"tags\": [\n                      \"strong\",\n                      \"em\",\n                      \"del\",\n                      \"a\",\n                      \"ul\",\n                      \"ol\",\n                      \"h2\",\n                      \"h3\",\n                      \"hr\",\n                      \"pre\",\n                      \"code\"\n                    ]\n                  },\n                  {\n                    \"name\": \"alwaysDisplayComments\",\n                    \"type\": \"boolean\",\n                    \"label\": \"Always display comments\",\n                    \"importance\": \"low\",\n                    \"optional\": true\n                  },\n                  {\n                    \"name\": \"backgroundOpacity\",\n                    \"type\": \"number\",\n                    \"label\": \"Background Opacity\",\n                    \"importance\": \"low\",\n                    \"min\": 0,\n                    \"max\": 100,\n                    \"step\": 5,\n                    \"default\": 0,\n                    \"optional\": true\n                  },\n                  {\n                    \"name\": \"displayAsButton\",\n                    \"type\": \"boolean\",\n                    \"label\": \"Display as button\",\n                    \"importance\": \"medium\",\n                    \"default\": false,\n                    \"optional\": true\n                  },\n                  {\n                    \"name\": \"buttonSize\",\n                    \"type\": \"select\",\n                    \"label\": \"Button size\",\n                    \"importance\": \"low\",\n                    \"optional\": false,\n                    \"default\": \"big\",\n                    \"options\": [\n                      {\n                        \"value\": \"small\",\n                        \"label\": \"Small\"\n                      },\n                      {\n                        \"value\": \"big\",\n                        \"label\": \"Big\"\n                      }\n                    ]\n                  },\n                  {\n                    \"name\": \"title\",\n                    \"type\": \"text\",\n                    \"optional\": true,\n                    \"label\": \"Title\",\n                    \"importance\": \"medium\"\n                  },\n                  {\n                    \"name\": \"goToSlideType\",\n                    \"type\": \"select\",\n                    \"label\": \"Go to\",\n                    \"importance\": \"medium\",\n                    \"optional\": false,\n                    \"options\": [\n                      {\n                        \"value\": \"specified\",\n                        \"label\": \"Specific slide number\"\n                      },\n                      {\n                        \"value\": \"next\",\n                        \"label\": \"Next slide\"\n                      },\n                      {\n                        \"value\": \"previous\",\n                        \"label\": \"Previous slide\"\n                      }\n                    ],\n                    \"default\": \"specified\"\n                  },\n                  {\n                    \"name\": \"goToSlide\",\n                    \"type\": \"number\",\n                    \"label\": \"Specific slide number\",\n                    \"description\": \"Only applicable when \'Specific slide number\' is selected\",\n                    \"importance\": \"low\",\n                    \"min\": 1,\n                    \"optional\": true\n                  },\n                  {\n                    \"name\": \"invisible\",\n                    \"type\": \"boolean\",\n                    \"label\": \"Invisible\",\n                    \"importance\": \"low\",\n                    \"description\": \"Default cursor, no title and no tab index. Warning: Users with disabilities or keyboard only users will have trouble using this element.\",\n                    \"default\": false\n                  }\n                ]\n              }\n            },\n            {\n              \"name\": \"keywords\",\n              \"importance\": \"low\",\n              \"type\": \"list\",\n              \"optional\": true,\n              \"field\": {\n                \"name\": \"keyword\",\n                \"importance\": \"low\",\n                \"type\": \"group\",\n                \"optional\": true,\n                \"fields\": [\n                  {\n                    \"name\": \"main\",\n                    \"importance\": \"low\",\n                    \"type\": \"text\",\n                    \"optional\": true\n                  },\n                  {\n                    \"name\": \"subs\",\n                    \"importance\": \"low\",\n                    \"type\": \"list\",\n                    \"optional\": true,\n                    \"field\": {\n                      \"name\": \"keyword\",\n                      \"importance\": \"low\",\n                      \"type\": \"text\"\n                    }\n                  }\n                ]\n              }\n            },\n            {\n              \"name\": \"slideBackgroundSelector\",\n              \"importance\": \"medium\",\n              \"type\": \"group\",\n              \"widget\": \"radioSelector\",\n              \"fields\": [\n                {\n                  \"name\": \"imageSlideBackground\",\n                  \"type\": \"image\",\n                  \"label\": \"Image\",\n                  \"importance\": \"medium\",\n                  \"optional\": true,\n                  \"description\": \"Image background should have a 2:1 width to height ratio to avoid stretching. High resolution images will display better on larger screens.\"\n                },\n                {\n                  \"name\": \"fillSlideBackground\",\n                  \"importance\": \"medium\",\n                  \"type\": \"text\",\n                  \"widget\": \"colorSelector\",\n                  \"label\": \"Pick a color\",\n                  \"spectrum\": {\n                    \"flat\": true,\n                    \"showInput\": true,\n                    \"allowEmpty\": true,\n                    \"showButtons\": false\n                  },\n                  \"default\": null,\n                  \"optional\": true\n                }\n              ]\n            }\n          ]\n        }\n      },\n      {\n        \"name\": \"ct\",\n        \"importance\": \"low\",\n        \"type\": \"text\",\n        \"widget\": \"none\",\n        \"optional\": true,\n        \"tags\": [\n          \"strong\",\n          \"em\",\n          \"del\",\n          \"br\",\n          \"p\",\n          \"a\",\n          \"h2\",\n          \"h3\",\n          \"pre\",\n          \"code\"\n        ]\n      },\n      {\n        \"name\": \"keywordListEnabled\",\n        \"type\": \"boolean\",\n        \"label\": \"Keyword list\",\n        \"importance\": \"low\",\n        \"default\": true\n      },\n      {\n        \"name\": \"keywordListAlwaysShow\",\n        \"type\": \"boolean\",\n        \"label\": \"Always show\",\n        \"importance\": \"low\",\n        \"default\": false\n      },\n      {\n        \"name\": \"keywordListAutoHide\",\n        \"type\": \"boolean\",\n        \"label\": \"Auto hide\",\n        \"importance\": \"low\",\n        \"default\": false\n      },\n      {\n        \"name\": \"keywordListOpacity\",\n        \"type\": \"number\",\n        \"label\": \"Opacity\",\n        \"importance\": \"low\",\n        \"min\": 0,\n        \"max\": 100,\n        \"default\": 90\n      },\n      {\n        \"name\": \"globalBackgroundSelector\",\n        \"importance\": \"medium\",\n        \"type\": \"group\",\n        \"widget\": \"radioSelector\",\n        \"fields\": [\n          {\n            \"name\": \"imageGlobalBackground\",\n            \"type\": \"image\",\n            \"label\": \"Image\",\n            \"importance\": \"medium\",\n            \"optional\": true,\n            \"description\": \"Image background should have a 2:1 width to height ratio to avoid stretching. High resolution images will display better on larger screens.\"\n          },\n          {\n            \"name\": \"fillGlobalBackground\",\n            \"type\": \"text\",\n            \"widget\": \"colorSelector\",\n            \"label\": \"Pick a color\",\n            \"importance\": \"medium\",\n            \"spectrum\": {\n              \"flat\": true,\n              \"showInput\": true,\n              \"allowEmpty\": true,\n              \"showButtons\": false\n            },\n            \"default\": null,\n            \"optional\": true\n          }\n        ]\n      }\n    ]\n  },\n  {\n    \"name\": \"l10n\",\n    \"type\": \"group\",\n    \"label\": \"Localize\",\n    \"importance\": \"low\",\n    \"common\": true,\n    \"fields\": [\n      {\n        \"name\": \"slide\",\n        \"type\": \"text\",\n        \"label\": \"Translation for \\\"Slide\\\"\",\n        \"importance\": \"low\",\n        \"default\": \"Slide\"\n      },\n      {\n        \"name\": \"score\",\n        \"type\": \"text\",\n        \"label\": \"Translation for \\\"Score\\\"\",\n        \"importance\": \"low\",\n        \"default\": \"Score\"\n      },\n      {\n        \"name\": \"yourScore\",\n        \"type\": \"text\",\n        \"label\": \"Translation for \\\"Your Score\\\"\",\n        \"importance\": \"low\",\n        \"default\": \"Your Score\"\n      },\n      {\n        \"name\": \"maxScore\",\n        \"type\": \"text\",\n        \"label\": \"Translation for \\\"Max Score\\\"\",\n        \"importance\": \"low\",\n        \"default\": \"Max Score\"\n      },\n      {\n        \"name\": \"total\",\n        \"type\": \"text\",\n        \"label\": \"Translation for \\\"Total\\\"\",\n        \"importance\": \"low\",\n        \"default\": \"Total\"\n      },\n      {\n        \"name\": \"totalScore\",\n        \"type\": \"text\",\n        \"label\": \"Translation for \\\"Total Score\\\"\",\n        \"importance\": \"low\",\n        \"default\": \"Total Score\"\n      },\n      {\n        \"name\": \"showSolutions\",\n        \"type\": \"text\",\n        \"label\": \"Title for show solutions button\",\n        \"importance\": \"low\",\n        \"default\": \"Show solutions\"\n      },\n      {\n        \"name\": \"retry\",\n        \"type\": \"text\",\n        \"label\": \"Text for the retry button\",\n        \"importance\": \"low\",\n        \"default\": \"Retry\",\n        \"optional\": true\n      },\n      {\n        \"name\": \"exportAnswers\",\n        \"type\": \"text\",\n        \"label\": \"Text for the export text button\",\n        \"importance\": \"low\",\n        \"default\": \"Export text\"\n      },\n      {\n        \"name\": \"hideKeywords\",\n        \"type\": \"text\",\n        \"label\": \"Hide sidebar navigation menu button title\",\n        \"importance\": \"low\",\n        \"default\": \"Hide sidebar navigation menu\"\n      },\n      {\n        \"name\": \"showKeywords\",\n        \"type\": \"text\",\n        \"label\": \"Show sidebar navigation menu button title\",\n        \"importance\": \"low\",\n        \"default\": \"Show sidebar navigation menu\"\n      },\n      {\n        \"name\": \"fullscreen\",\n        \"type\": \"text\",\n        \"label\": \"Fullscreen label\",\n        \"importance\": \"low\",\n        \"default\": \"Fullscreen\"\n      },\n      {\n        \"name\": \"exitFullscreen\",\n        \"type\": \"text\",\n        \"label\": \"Exit fullscreen label\",\n        \"importance\": \"low\",\n        \"default\": \"Exit fullscreen\"\n      },\n      {\n        \"name\": \"prevSlide\",\n        \"type\": \"text\",\n        \"label\": \"Previous slide label\",\n        \"importance\": \"low\",\n        \"default\": \"Previous slide\"\n      },\n      {\n        \"name\": \"nextSlide\",\n        \"type\": \"text\",\n        \"label\": \"Next slide label\",\n        \"importance\": \"low\",\n        \"default\": \"Next slide\"\n      },\n      {\n        \"name\": \"currentSlide\",\n        \"type\": \"text\",\n        \"label\": \"Current slide label\",\n        \"importance\": \"low\",\n        \"default\": \"Current slide\"\n      },\n      {\n        \"name\": \"lastSlide\",\n        \"type\": \"text\",\n        \"label\": \"Last slide label\",\n        \"importance\": \"low\",\n        \"default\": \"Last slide\"\n      },\n      {\n        \"name\": \"solutionModeTitle\",\n        \"type\": \"text\",\n        \"label\": \"Exit solution mode text\",\n        \"importance\": \"low\",\n        \"default\": \"Exit solution mode\"\n      },\n      {\n        \"name\": \"solutionModeText\",\n        \"type\": \"text\",\n        \"label\": \"Solution mode text\",\n        \"importance\": \"low\",\n        \"default\": \"Solution Mode\"\n      },\n      {\n        \"name\": \"summaryMultipleTaskText\",\n        \"type\": \"text\",\n        \"label\": \"Text when multiple tasks on a page\",\n        \"importance\": \"low\",\n        \"default\": \"Multiple tasks\"\n      },\n      {\n        \"name\": \"scoreMessage\",\n        \"type\": \"text\",\n        \"label\": \"Score message text\",\n        \"importance\": \"low\",\n        \"default\": \"You achieved:\"\n      },\n      {\n        \"name\": \"shareFacebook\",\n        \"type\": \"text\",\n        \"label\": \"Share to Facebook text\",\n        \"importance\": \"low\",\n        \"default\": \"Share on Facebook\"\n      },\n      {\n        \"name\": \"shareTwitter\",\n        \"type\": \"text\",\n        \"label\": \"Share to Twitter text\",\n        \"importance\": \"low\",\n        \"default\": \"Share on Twitter\"\n      },\n      {\n        \"name\": \"shareGoogle\",\n        \"type\": \"text\",\n        \"label\": \"Share to Google text\",\n        \"importance\": \"low\",\n        \"default\": \"Share on Google+\"\n      },\n      {\n        \"name\": \"summary\",\n        \"type\": \"text\",\n        \"label\": \"Title for summary slide\",\n        \"importance\": \"low\",\n        \"default\": \"Summary\"\n      },\n      {\n        \"name\": \"solutionsButtonTitle\",\n        \"type\": \"text\",\n        \"label\": \"Title for the comments icon\",\n        \"importance\": \"low\",\n        \"default\": \"Show comments\"\n      },\n      {\n        \"name\": \"printTitle\",\n        \"type\": \"text\",\n        \"label\": \"Title for print button\",\n        \"importance\": \"low\",\n        \"default\": \"Print\"\n      },\n      {\n        \"name\": \"printIngress\",\n        \"type\": \"text\",\n        \"label\": \"Print dialog ingress\",\n        \"importance\": \"low\",\n        \"default\": \"How would you like to print this presentation?\"\n      },\n      {\n        \"name\": \"printAllSlides\",\n        \"type\": \"text\",\n        \"label\": \"Label for \\\"Print all slides\\\" button\",\n        \"importance\": \"low\",\n        \"default\": \"Print all slides\"\n      },\n      {\n        \"name\": \"printCurrentSlide\",\n        \"type\": \"text\",\n        \"label\": \"Label for \\\"Print current slide\\\" button\",\n        \"importance\": \"low\",\n        \"default\": \"Print current slide\"\n      },\n      {\n        \"name\": \"noTitle\",\n        \"type\": \"text\",\n        \"label\": \"Label for slides without a title\",\n        \"importance\": \"low\",\n        \"default\": \"No title\"\n      },\n      {\n        \"name\": \"accessibilitySlideNavigationExplanation\",\n        \"type\": \"text\",\n        \"label\": \"Explanation of slide navigation for assistive technologies\",\n        \"importance\": \"low\",\n        \"default\": \"Use left and right arrow to change slide in that direction whenever canvas is selected.\"\n      },\n      {\n        \"name\": \"accessibilityCanvasLabel\",\n        \"type\": \"text\",\n        \"label\": \"Canvas label for assistive technologies\",\n        \"importance\": \"low\",\n        \"default\": \"Presentation canvas. Use left and right arrow to move between slides.\"\n      },\n      {\n        \"name\": \"containsNotCompleted\",\n        \"type\": \"text\",\n        \"label\": \"Label for uncompleted interactions\",\n        \"importance\": \"low\",\n        \"default\": \"@slideName contains not completed interaction\"\n      },\n      {\n        \"name\": \"containsCompleted\",\n        \"type\": \"text\",\n        \"label\": \"Label for completed interactions\",\n        \"importance\": \"low\",\n        \"default\": \"@slideName contains completed interaction\"\n      },\n      {\n        \"name\": \"slideCount\",\n        \"type\": \"text\",\n        \"label\": \"Label for slide counter. Variables are @index, @total\",\n        \"importance\": \"low\",\n        \"default\": \"Slide @index of @total\"\n      },\n      {\n        \"name\": \"containsOnlyCorrect\",\n        \"type\": \"text\",\n        \"label\": \"Label for slides that only contains correct answers\",\n        \"importance\": \"low\",\n        \"default\": \"@slideName only has correct answers\"\n      },\n      {\n        \"name\": \"containsIncorrectAnswers\",\n        \"type\": \"text\",\n        \"label\": \"Label for slides that has incorrect answers\",\n        \"importance\": \"low\",\n        \"default\": \"@slideName has incorrect answers\"\n      },\n      {\n        \"name\": \"shareResult\",\n        \"type\": \"text\",\n        \"label\": \"Label for social sharing bar\",\n        \"importance\": \"low\",\n        \"default\": \"Share Result\"\n      },\n      {\n        \"name\": \"accessibilityTotalScore\",\n        \"type\": \"text\",\n        \"label\": \"Total score announcement for assistive technologies\",\n        \"default\": \"You got @score of @maxScore points in total\",\n        \"description\": \"Available variables are @score and @maxScore\"\n      },\n      {\n        \"name\": \"accessibilityEnteredFullscreen\",\n        \"type\": \"text\",\n        \"label\": \"Entered fullscreen announcement for assistive technologies\",\n        \"default\": \"Entered fullscreen\"\n      },\n      {\n        \"name\": \"accessibilityExitedFullscreen\",\n        \"type\": \"text\",\n        \"label\": \"Exited fullscreen announcement for assistive technologies\",\n        \"default\": \"Exited fullscreen\"\n      }\n    ]\n  },\n  {\n    \"name\": \"override\",\n    \"type\": \"group\",\n    \"label\": \"Behaviour settings.\",\n    \"importance\": \"low\",\n    \"description\": \"These options will let you override behaviour settings.\",\n    \"optional\": true,\n    \"fields\": [\n      {\n        \"name\": \"activeSurface\",\n        \"type\": \"boolean\",\n        \"widget\": \"disposableBoolean\",\n        \"label\": \"Activate Active Surface Mode\",\n        \"importance\": \"low\",\n        \"description\": \"Removes navigation controls for the end user. Use Go To Slide to navigate.\",\n        \"default\": false\n      },\n      {\n        \"name\": \"hideSummarySlide\",\n        \"type\": \"boolean\",\n        \"label\": \"Hide Summary Slide\",\n        \"importance\": \"low\",\n        \"description\": \"Hides the summary slide.\",\n        \"default\": false\n      },\n      {\n        \"name\": \"showSolutionButton\",\n        \"type\": \"select\",\n        \"label\": \"Override \\\"Show Solution\\\" button\",\n        \"importance\": \"low\",\n        \"description\": \"This option determines if the \\\"Show Solution\\\" button will be configured for each question individually (default) shown for all questions (Enabled) or disabled for all questions (Disabled) \",\n        \"optional\": true,\n        \"options\": [\n          {\n            \"value\": \"on\",\n            \"label\": \"Enabled\"\n          },\n          {\n            \"value\": \"off\",\n            \"label\": \"Disabled\"\n          }\n        ]\n      },\n      {\n        \"name\": \"retryButton\",\n        \"type\": \"select\",\n        \"label\": \"Override \\\"Retry\\\" button\",\n        \"importance\": \"low\",\n        \"description\": \"This option determines if the \\\"Retry\\\" button will be configured for each question individually (default) shown for all questions (Enabled) or disabled for all questions (Disabled)\",\n        \"optional\": true,\n        \"options\": [\n          {\n            \"value\": \"on\",\n            \"label\": \"Enabled\"\n          },\n          {\n            \"value\": \"off\",\n            \"label\": \"Disabled\"\n          }\n        ]\n      },\n      {\n        \"name\": \"summarySlideSolutionButton\",\n        \"type\": \"boolean\",\n        \"label\": \"Show \\\"Show solution\\\" button in the summary slide\",\n        \"description\": \"If enabled, the learner will be able to show the solutions for all question when they reach the summary slide\",\n        \"default\": true,\n        \"importance\": \"low\",\n        \"widget\": \"showWhen\",\n        \"showWhen\": {\n          \"rules\": [\n            {\n              \"field\": \"hideSummarySlide\",\n              \"equals\": false\n            }\n          ]\n        }\n      },\n      {\n        \"name\": \"summarySlideRetryButton\",\n        \"type\": \"boolean\",\n        \"label\": \"Show \\\"Retry\\\" button in the summary slide\",\n        \"description\": \"If enabled, the learner will be able to retry all questions when they reach the summary slide. Be advised that by refreshing the page the learners will be able to retry even if this button isn\'t showing.\",\n        \"default\": true,\n        \"importance\": \"low\",\n        \"widget\": \"showWhen\",\n        \"showWhen\": {\n          \"rules\": [\n            {\n              \"field\": \"hideSummarySlide\",\n              \"equals\": false\n            }\n          ]\n        }\n      },\n      {\n        \"name\": \"enablePrintButton\",\n        \"type\": \"boolean\",\n        \"label\": \"Enable print button\",\n        \"importance\": \"low\",\n        \"description\": \"Enables the print button.\",\n        \"default\": false\n      },\n      {\n        \"name\": \"social\",\n        \"type\": \"group\",\n        \"label\": \"Social Settings\",\n        \"widget\": \"showWhen\",\n        \"showWhen\": {\n          \"rules\": [\n            {\n              \"field\": \"hideSummarySlide\",\n              \"equals\": false\n            }\n          ]\n        },\n        \"importance\": \"low\",\n        \"description\": \"These options will let you override social behaviour settings. Empty values will be filled in automatically if a link is provided, otherwise all values will be generated.\",\n        \"optional\": true,\n        \"fields\": [\n          {\n            \"name\": \"showFacebookShare\",\n            \"type\": \"boolean\",\n            \"label\": \"Display Facebook share icon\",\n            \"importance\": \"low\",\n            \"default\": false\n          },\n          {\n            \"name\": \"facebookShare\",\n            \"importance\": \"low\",\n            \"type\": \"group\",\n            \"expanded\": true,\n            \"label\": \"Facebook share settings\",\n            \"widget\": \"showWhen\",\n            \"showWhen\": {\n              \"rules\": [\n                {\n                  \"field\": \"showFacebookShare\",\n                  \"equals\": true\n                }\n              ]\n            },\n            \"fields\": [\n              {\n                \"name\": \"url\",\n                \"type\": \"text\",\n                \"label\": \"Share to Facebook link\",\n                \"importance\": \"low\",\n                \"default\": \"@currentpageurl\"\n              },\n              {\n                \"name\": \"quote\",\n                \"type\": \"text\",\n                \"label\": \"Share to Facebook quote\",\n                \"importance\": \"low\",\n                \"default\": \"I scored @score out of @maxScore on a task at @currentpageurl.\"\n              }\n            ]\n          },\n          {\n            \"name\": \"showTwitterShare\",\n            \"type\": \"boolean\",\n            \"label\": \"Display Twitter share icon\",\n            \"importance\": \"low\",\n            \"default\": false\n          },\n          {\n            \"name\": \"twitterShare\",\n            \"importance\": \"low\",\n            \"type\": \"group\",\n            \"expanded\": true,\n            \"label\": \"Twitter share settings\",\n            \"widget\": \"showWhen\",\n            \"showWhen\": {\n              \"rules\": [\n                {\n                  \"field\": \"showTwitterShare\",\n                  \"equals\": true\n                }\n              ]\n            },\n            \"fields\": [\n              {\n                \"name\": \"statement\",\n                \"type\": \"text\",\n                \"label\": \"Share to Twitter statement\",\n                \"importance\": \"low\",\n                \"default\": \"I scored @score out of @maxScore on a task at @currentpageurl.\"\n              },\n              {\n                \"name\": \"url\",\n                \"type\": \"text\",\n                \"label\": \"Share to Twitter link\",\n                \"importance\": \"low\",\n                \"default\": \"@currentpageurl\"\n              },\n              {\n                \"name\": \"hashtags\",\n                \"type\": \"text\",\n                \"label\": \"Share to Twitter hashtags\",\n                \"importance\": \"low\",\n                \"default\": \"h5p, course\"\n              }\n            ]\n          },\n          {\n            \"name\": \"showGoogleShare\",\n            \"type\": \"boolean\",\n            \"label\": \"Display Google+ share icon\",\n            \"importance\": \"low\",\n            \"default\": false\n          },\n          {\n            \"name\": \"googleShareUrl\",\n            \"type\": \"text\",\n            \"label\": \"Share to Google link\",\n            \"importance\": \"low\",\n            \"default\": \"@currentpageurl\",\n            \"widget\": \"showWhen\",\n            \"showWhen\": {\n              \"rules\": [\n                {\n                  \"field\": \"showGoogleShare\",\n                  \"equals\": true\n                }\n              ]\n            }\n          }\n        ]\n      }\n    ]\n  }\n]', NULL, 1, 23, NULL, NULL, NULL, 1),
(129, 'H5P.Dialogcards', 'Dialog Cards', 1, 8, 4, 1, 0, 'iframe', 'dist/h5p-dialogcards.js', 'dist/h5p-dialogcards.css', '', '[\n  {\n    \"name\": \"title\",\n    \"type\": \"text\",\n    \"widget\": \"html\",\n    \"label\": \"Heading\",\n    \"importance\": \"high\",\n    \"optional\": true,\n    \"tags\": [\n      \"p\",\n      \"br\",\n      \"strong\",\n      \"em\",\n      \"code\"\n    ]\n  },\n  {\n    \"name\": \"mode\",\n    \"type\": \"select\",\n    \"label\": \"Mode\",\n    \"description\": \"Mode of presenting the dialog cards\",\n    \"importance\": \"medium\",\n    \"options\": [\n      {\n        \"value\": \"normal\",\n        \"label\": \"Normal\"\n      },\n      {\n        \"value\": \"repetition\",\n        \"label\": \"Repetition\"\n      }\n    ],\n    \"default\": \"normal\"\n  },\n  {\n    \"name\": \"description\",\n    \"type\": \"text\",\n    \"widget\": \"html\",\n    \"label\": \"Task description\",\n    \"importance\": \"medium\",\n    \"default\": \"\",\n    \"optional\": true,\n    \"tags\": [\n      \"p\",\n      \"br\",\n      \"strong\",\n      \"em\",\n      \"code\"\n    ]\n  },\n  {\n    \"name\": \"dialogs\",\n    \"type\": \"list\",\n    \"importance\": \"high\",\n    \"widgets\": [\n      {\n        \"name\": \"VerticalTabs\",\n        \"label\": \"Default\"\n      }\n    ],\n    \"label\": \"Dialogs\",\n    \"entity\": \"dialog\",\n    \"min\": 1,\n    \"defaultNum\": 1,\n    \"field\": {\n      \"name\": \"question\",\n      \"type\": \"group\",\n      \"label\": \"Question\",\n      \"importance\": \"high\",\n      \"fields\": [\n        {\n          \"name\": \"text\",\n          \"type\": \"text\",\n          \"widget\": \"html\",\n          \"tags\": [\n            \"p\",\n            \"br\",\n            \"strong\",\n            \"em\",\n            \"code\"\n          ],\n          \"label\": \"Text\",\n          \"importance\": \"high\",\n          \"description\": \"Hint for the first part of the dialogue\"\n        },\n        {\n          \"name\": \"answer\",\n          \"type\": \"text\",\n          \"widget\": \"html\",\n          \"tags\": [\n            \"p\",\n            \"br\",\n            \"strong\",\n            \"em\",\n            \"code\"\n          ],\n          \"label\": \"Answer\",\n          \"importance\": \"high\",\n          \"description\": \"Hint for the second part of the dialogue\"\n        },\n        {\n          \"name\": \"image\",\n          \"type\": \"image\",\n          \"label\": \"Image\",\n          \"importance\": \"high\",\n          \"optional\": true,\n          \"description\": \"Optional image for the card. (The card may use just an image, just a text or both)\"\n        },\n        {\n          \"name\": \"imageAltText\",\n          \"type\": \"text\",\n          \"label\": \"Alternative text for the image\",\n          \"importance\": \"high\",\n          \"optional\": true\n        },\n        {\n          \"name\": \"audio\",\n          \"type\": \"audio\",\n          \"label\": \"Audio files\",\n          \"importance\": \"low\",\n          \"optional\": true\n        },\n        {\n          \"name\": \"tips\",\n          \"type\": \"group\",\n          \"label\": \"Tips\",\n          \"importance\": \"low\",\n          \"fields\": [\n            {\n              \"name\": \"front\",\n              \"type\": \"text\",\n              \"label\": \"Tip for text\",\n              \"importance\": \"low\",\n              \"optional\": true,\n              \"description\": \"Tip for the first part of the dialogue\"\n            },\n            {\n              \"name\": \"back\",\n              \"type\": \"text\",\n              \"label\": \"Tip for answer\",\n              \"importance\": \"low\",\n              \"optional\": true,\n              \"description\": \"Tip for the second part of the dialogue\"\n            }\n          ]\n        }\n      ]\n    }\n  },\n  {\n    \"name\": \"behaviour\",\n    \"type\": \"group\",\n    \"label\": \"Behavioural settings.\",\n    \"importance\": \"low\",\n    \"description\": \"These options will let you control how the task behaves.\",\n    \"optional\": true,\n    \"fields\": [\n      {\n        \"name\": \"enableRetry\",\n        \"type\": \"boolean\",\n        \"label\": \"Enable \\\"Retry\\\" button\",\n        \"importance\": \"low\",\n        \"default\": true,\n        \"optional\": true\n      },\n      {\n        \"name\": \"disableBackwardsNavigation\",\n        \"type\": \"boolean\",\n        \"label\": \"Disable backwards navigation\",\n        \"importance\": \"low\",\n        \"description\": \"This option will only allow you to move forward with Dialog Cards\",\n        \"optional\": true,\n        \"default\": false,\n        \"widget\": \"showWhen\",\n        \"showWhen\": {\n          \"rules\": [\n            {\n              \"field\": \"../mode\",\n              \"equals\": \"normal\"\n            }\n          ]\n        }\n      },\n      {\n        \"name\": \"scaleTextNotCard\",\n        \"type\": \"boolean\",\n        \"label\": \"Scale the text to fit inside the card\",\n        \"importance\": \"low\",\n        \"description\": \"Unchecking this option will make the card adapt its size to the size of the text\",\n        \"default\": false\n      },\n      {\n        \"name\": \"randomCards\",\n        \"type\": \"boolean\",\n        \"label\": \"Randomize cards\",\n        \"importance\": \"low\",\n        \"description\": \"Enable to randomize the order of cards on display.\",\n        \"default\": false,\n        \"widget\": \"showWhen\",\n        \"showWhen\": {\n          \"rules\": [\n            {\n              \"field\": \"../mode\",\n              \"equals\": \"normal\"\n            }\n          ]\n        }\n      },\n      {\n        \"name\": \"maxProficiency\",\n        \"type\": \"number\",\n        \"label\": \"Maximum proficiency level\",\n        \"importance\": \"low\",\n        \"default\": 5,\n        \"min\": 3,\n        \"max\": 7,\n        \"optional\": true,\n        \"widget\": \"showWhen\",\n        \"showWhen\": {\n          \"rules\": [\n            {\n              \"field\": \"../mode\",\n              \"equals\": \"repetition\"\n            }\n          ]\n        }\n      },\n      {\n        \"name\": \"quickProgression\",\n        \"type\": \"boolean\",\n        \"label\": \"Allow quick progression\",\n        \"description\": \"If activated, learners can decide to indicate that they know a card without turning it\",\n        \"importance\": \"low\",\n        \"default\": false,\n        \"optional\": true,\n        \"widget\": \"showWhen\",\n        \"showWhen\": {\n          \"rules\": [\n            {\n              \"field\": \"../mode\",\n              \"equals\": \"repetition\"\n            }\n          ]\n        }\n      }\n    ]\n  },\n  {\n    \"label\": \"Text for the turn button\",\n    \"importance\": \"low\",\n    \"name\": \"answer\",\n    \"type\": \"text\",\n    \"default\": \"Turn\",\n    \"common\": true\n  },\n  {\n    \"label\": \"Text for the next button\",\n    \"importance\": \"low\",\n    \"type\": \"text\",\n    \"name\": \"next\",\n    \"default\": \"Next\",\n    \"common\": true\n  },\n  {\n    \"name\": \"prev\",\n    \"type\": \"text\",\n    \"label\": \"Text for the previous button\",\n    \"importance\": \"low\",\n    \"default\": \"Previous\",\n    \"common\": true\n  },\n  {\n    \"name\": \"retry\",\n    \"type\": \"text\",\n    \"label\": \"Text for the retry button\",\n    \"importance\": \"low\",\n    \"default\": \"Retry\",\n    \"common\": true\n  },\n  {\n    \"name\": \"correctAnswer\",\n    \"type\": \"text\",\n    \"label\": \"Text for the \\\"correct answer\\\" button\",\n    \"importance\": \"low\",\n    \"default\": \"I got it right!\",\n    \"common\": true\n  },\n  {\n    \"name\": \"incorrectAnswer\",\n    \"type\": \"text\",\n    \"label\": \"Text for the \\\"incorrect answer\\\" button\",\n    \"importance\": \"low\",\n    \"default\": \"I got it wrong\",\n    \"common\": true\n  },\n  {\n    \"name\": \"round\",\n    \"type\": \"text\",\n    \"label\": \"Text for \\\"Round\\\" message below cards and on the summary screen\",\n    \"description\": \"@round will be replaced by the number of the current round\",\n    \"importance\": \"low\",\n    \"default\": \"Round @round\",\n    \"common\": true\n  },\n  {\n    \"name\": \"cardsLeft\",\n    \"type\": \"text\",\n    \"label\": \"Text for \\\"Cards left\\\" message\",\n    \"description\": \"@number will be replaced by the number of cards left in this round\",\n    \"importance\": \"low\",\n    \"default\": \"Cards left: @number\",\n    \"common\": true\n  },\n  {\n    \"name\": \"nextRound\",\n    \"type\": \"text\",\n    \"label\": \"Text for the \\\"next round\\\" button\",\n    \"description\": \"@round will be replaced by the round number\",\n    \"importance\": \"low\",\n    \"default\": \"Proceed to round @round\",\n    \"common\": true\n  },\n  {\n    \"name\": \"startOver\",\n    \"type\": \"text\",\n    \"label\": \"Text for the \\\"Start over\\\" button\",\n    \"importance\": \"low\",\n    \"default\": \"Start over\",\n    \"common\": true\n  },\n  {\n    \"name\": \"showSummary\",\n    \"type\": \"text\",\n    \"label\": \"Text for the \\\"show summary\\\" button\",\n    \"importance\": \"low\",\n    \"default\": \"Next\",\n    \"common\": true\n  },\n  {\n    \"name\": \"summary\",\n    \"type\": \"text\",\n    \"label\": \"Title text for the summary page\",\n    \"importance\": \"low\",\n    \"default\": \"Summary\",\n    \"common\": true\n  },\n  {\n    \"name\": \"summaryCardsRight\",\n    \"type\": \"text\",\n    \"label\": \"Text for \\\"Cards you got right:\\\"\",\n    \"importance\": \"low\",\n    \"default\": \"Cards you got right:\",\n    \"common\": true\n  },\n  {\n    \"name\": \"summaryCardsWrong\",\n    \"type\": \"text\",\n    \"label\": \"Text for \\\"Cards you got wrong:\\\"\",\n    \"importance\": \"low\",\n    \"default\": \"Cards you got wrong:\",\n    \"common\": true\n  },\n  {\n    \"name\": \"summaryCardsNotShown\",\n    \"type\": \"text\",\n    \"label\": \"Text for \\\"Cards not shown:\\\"\",\n    \"importance\": \"low\",\n    \"default\": \"Cards in pool not shown:\",\n    \"common\": true\n  },\n  {\n    \"name\": \"summaryOverallScore\",\n    \"type\": \"text\",\n    \"label\": \"Text for \\\"Overall Score\\\"\",\n    \"importance\": \"low\",\n    \"default\": \"Overall Score\",\n    \"common\": true\n  },\n  {\n    \"name\": \"summaryCardsCompleted\",\n    \"type\": \"text\",\n    \"label\": \"Text for \\\"Cards completed\\\"\",\n    \"importance\": \"low\",\n    \"default\": \"Cards you have completed learning:\",\n    \"common\": true\n  },\n  {\n    \"name\": \"summaryCompletedRounds\",\n    \"type\": \"text\",\n    \"label\": \"Text for \\\"Completed rounds:\\\"\",\n    \"importance\": \"low\",\n    \"default\": \"Completed rounds:\",\n    \"common\": true\n  },\n  {\n    \"name\": \"summaryAllDone\",\n    \"type\": \"text\",\n    \"label\": \"Message when all cards have been learned proficiently\",\n    \"description\": \"@cards will be replaced by the number of all cards in the pool. @max will be replaced by the maximum proficiency level - 1.\",\n    \"importance\": \"low\",\n    \"default\": \"Well done! You got all @cards cards correct @max times in a row!\",\n    \"common\": true\n  },\n  {\n    \"name\": \"progressText\",\n    \"type\": \"text\",\n    \"label\": \"Progress text\",\n    \"importance\": \"low\",\n    \"description\": \"Available variables are @card and @total.\",\n    \"default\": \"Card @card of @total\",\n    \"common\": true\n  },\n  {\n    \"name\": \"cardFrontLabel\",\n    \"type\": \"text\",\n    \"label\": \"Label for card text\",\n    \"importance\": \"low\",\n    \"description\": \"Used for accessibility by assistive technologies\",\n    \"default\": \"Card front\",\n    \"common\": true\n  },\n  {\n    \"name\": \"cardBackLabel\",\n    \"type\": \"text\",\n    \"label\": \"Label for card back\",\n    \"importance\": \"low\",\n    \"description\": \"Used for accessibility by assistive technologies\",\n    \"default\": \"Card back\",\n    \"common\": true\n  },\n  {\n    \"name\": \"tipButtonLabel\",\n    \"type\": \"text\",\n    \"label\": \"Label for the show tip button\",\n    \"importance\": \"low\",\n    \"default\": \"Show tip\",\n    \"common\": true\n  },\n  {\n    \"name\": \"audioNotSupported\",\n    \"type\": \"text\",\n    \"label\": \"Audio not supported message\",\n    \"importance\": \"low\",\n    \"common\": true,\n    \"default\": \"Your browser does not support this audio\"\n  },\n  {\n    \"name\": \"confirmStartingOver\",\n    \"type\": \"group\",\n    \"label\": \"Confirm starting over dialog\",\n    \"importance\": \"low\",\n    \"common\": true,\n    \"fields\": [\n      {\n        \"name\": \"header\",\n        \"type\": \"text\",\n        \"label\": \"Header text\",\n        \"importance\": \"low\",\n        \"default\": \"Start over?\"\n      },\n      {\n        \"name\": \"body\",\n        \"type\": \"text\",\n        \"label\": \"Body text\",\n        \"importance\": \"low\",\n        \"default\": \"All progress will be lost. Are you sure you want to start over?\",\n        \"widget\": \"html\",\n        \"enterMode\": \"p\",\n        \"tags\": [\n          \"strong\",\n          \"em\",\n          \"del\",\n          \"u\",\n          \"code\"\n        ]\n      },\n      {\n        \"name\": \"cancelLabel\",\n        \"type\": \"text\",\n        \"label\": \"Cancel button label\",\n        \"importance\": \"low\",\n        \"default\": \"Cancel\"\n      },\n      {\n        \"name\": \"confirmLabel\",\n        \"type\": \"text\",\n        \"label\": \"Confirm button label\",\n        \"importance\": \"low\",\n        \"default\": \"Start over\"\n      }\n    ]\n  }\n]\n', NULL, 1, 15, NULL, NULL, NULL, 1),
