(132, 'H5P.Column', 'Column', 1, 12, 0, 1, 0, 'iframe', 'scripts/h5p-column.js', 'styles/h5p-column.css', '', '[\n  {\n    \"name\": \"content\",\n    \"label\": \"List of Column Content\",\n    \"importance\": \"high\",\n    \"type\": \"list\",\n    \"min\": 1,\n    \"entity\": \"content\",\n    \"field\": {\n      \"name\": \"content\",\n      \"type\": \"group\",\n      \"fields\": [\n        {\n          \"name\": \"content\",\n          \"type\": \"library\",\n          \"importance\": \"high\",\n          \"label\": \"Content\",\n          \"options\": [\n            \"H5P.Accordion 1.0\",\n            \"H5P.Agamotto 1.4\",\n            \"H5P.Audio 1.4\",\n            \"H5P.AudioRecorder 1.0\",\n            \"H5P.Blanks 1.12\",\n            \"H5P.Chart 1.2\",\n            \"H5P.Collage 0.3\",\n            \"H5P.CoursePresentation 1.22\",\n            \"H5P.Dialogcards 1.8\",\n            \"H5P.DocumentationTool 1.8\",\n            \"H5P.DragQuestion 1.13\",\n            \"H5P.DragText 1.8\",\n            \"H5P.Essay 1.2\",\n            \"H5P.GuessTheAnswer 1.4\",\n            \"H5P.Table 1.1\",\n            \"H5P.AdvancedText 1.1\",\n            \"H5P.IFrameEmbed 1.0\",\n            \"H5P.Image 1.1\",\n            \"H5P.ImageHotspots 1.8\",\n            \"H5P.ImageHotspotQuestion 1.8\",\n            \"H5P.ImageSlider 1.1\",\n            \"H5P.InteractiveVideo 1.22\",\n            \"H5P.Link 1.3\",\n            \"H5P.MarkTheWords 1.9\",\n            \"H5P.MemoryGame 1.3\",\n            \"H5P.MultiChoice 1.14\",\n            \"H5P.Questionnaire 1.3\",\n            \"H5P.QuestionSet 1.17\",\n            \"H5P.SingleChoiceSet 1.11\",\n            \"H5P.Summary 1.10\",\n            \"H5P.Timeline 1.1\",\n            \"H5P.TrueFalse 1.6\",\n            \"H5P.TwitterUserFeed 1.0\",\n            \"H5P.Video 1.5\"\n          ]\n        },\n        {\n          \"name\": \"useSeparator\",\n          \"type\": \"select\",\n          \"importance\": \"low\",\n          \"label\": \"Separate content with a horizontal ruler\",\n          \"default\": \"auto\",\n          \"options\": [\n            {\n              \"value\": \"auto\",\n              \"label\": \"Automatic (default)\"\n            },\n            {\n              \"value\": \"disabled\",\n              \"label\": \"Never use ruler above\"\n            },\n            {\n              \"value\": \"enabled\",\n              \"label\": \"Always use ruler above\"\n            }\n          ]\n        }\n      ]\n    }\n  }\n]', NULL, 1, 19, NULL, NULL, NULL, 1);
INSERT INTO `mdl_h5p_libraries` (`id`, `machinename`, `title`, `majorversion`, `minorversion`, `patchversion`, `runnable`, `fullscreen`, `embedtypes`, `preloadedjs`, `preloadedcss`, `droplibrarycss`, `semantics`, `addto`, `coremajor`, `coreminor`, `metadatasettings`, `tutorial`, `example`, `enabled`) VALUES
(133, 'H5P.ImageHotspots', 'Image Hotspots', 1, 8, 3, 1, 1, 'iframe', 'scripts/image-hotspots.js, scripts/hotspot.js, scripts/popup.js', 'styles/image-hotspots.css', '', '[\n  {\n    \"label\": \"Background image\",\n    \"importance\": \"high\",\n    \"name\": \"image\",\n    \"type\": \"image\",\n    \"description\": \"Image shown on background.\"\n  },\n  {\n    \"name\": \"backgroundImageAltText\",\n    \"type\": \"text\",\n    \"label\": \"Alternative text for background image\",\n    \"description\": \"If the browser can\'t load the image this text will be displayed instead. Also used by assistive technologies.\",\n    \"optional\": true\n  },\n  {\n    \"name\": \"iconType\",\n    \"type\": \"select\",\n    \"label\": \"Hotspot Icon\",\n    \"options\": [\n      {\n        \"value\": \"icon\",\n        \"label\": \"Predefined icon\"\n      },\n      {\n        \"value\": \"image\",\n        \"label\": \"Uploaded image\"\n      }\n    ],\n    \"default\": \"icon\"\n  },\n  {\n    \"name\": \"icon\",\n    \"type\": \"select\",\n    \"label\": \"Predefined icon\",\n    \"importance\": \"medium\",\n    \"description\": \"Using a predefined icon for the hotspot.\",\n    \"widget\": \"showWhen\",\n    \"showWhen\": {\n      \"rules\": [\n        {\n          \"field\": \"iconType\",\n          \"equals\": [\n            \"icon\"\n          ]\n        }\n      ]\n    },\n    \"options\": [\n      {\n        \"value\": \"plus\",\n        \"label\": \"Plus\"\n      },\n      {\n        \"value\": \"minus\",\n        \"label\": \"Minus\"\n      },\n      {\n        \"value\": \"times\",\n        \"label\": \"Times\"\n      },\n      {\n        \"value\": \"check\",\n        \"label\": \"Check\"\n      },\n      {\n        \"value\": \"question\",\n        \"label\": \"Question\"\n      },\n      {\n        \"value\": \"info\",\n        \"label\": \"Info\"\n      },\n      {\n        \"value\": \"exclamation\",\n        \"label\": \"Exclamation\"\n      }\n    ],\n    \"default\": \"plus\"\n  },\n  {\n    \"name\": \"iconImage\",\n    \"type\": \"image\",\n    \"label\": \"Uploaded image\",\n    \"optional\": false,\n    \"description\": \"Use your own image for the hotspot icon.<br>75px by 75px is recommended for your image.\",\n    \"widget\": \"showWhen\",\n    \"showWhen\": {\n      \"rules\": [\n        {\n          \"field\": \"iconType\",\n          \"equals\": [\n            \"image\"\n          ]\n        }\n      ]\n    }\n  },\n  {\n    \"name\": \"color\",\n    \"type\": \"text\",\n    \"label\": \"Hotspot color\",\n    \"importance\": \"medium\",\n    \"description\": \"The color of the hotspots\",\n    \"optional\": true,\n    \"default\": \"#981d99\",\n    \"widget\": \"showWhen\",\n    \"spectrum\": {\n      \"showInput\": true\n    },\n    \"showWhen\": {\n      \"widget\": \"colorSelector\",\n      \"rules\": [\n        {\n          \"field\": \"iconType\",\n          \"equals\": [\n            \"icon\"\n          ]\n        }\n      ]\n    }\n  },\n  {\n    \"name\": \"hotspots\",\n    \"type\": \"list\",\n    \"entity\": \"hotspot\",\n    \"label\": \"Hotspots\",\n    \"importance\": \"high\",\n    \"min\": 1,\n    \"defaultNum\": 1,\n    \"field\": {\n      \"name\": \"hotspot\",\n      \"type\": \"group\",\n      \"label\": \"Hotspot\",\n      \"importance\": \"high\",\n      \"fields\": [\n        {\n          \"name\": \"position\",\n          \"type\": \"group\",\n          \"widget\": \"imageCoordinateSelector\",\n          \"imageFieldPath\": \"../../image\",\n          \"label\": \"Hotspot position\",\n          \"importance\": \"high\",\n          \"description\": \"Click on the thumbnail image to place the hotspot\",\n          \"fields\": [\n            {\n              \"name\": \"x\",\n              \"type\": \"number\"\n            },\n            {\n              \"name\": \"y\",\n              \"type\": \"number\"\n            },\n            {\n              \"name\": \"legacyPositioning\",\n              \"type\": \"boolean\"\n            }\n          ]\n        },\n        {\n          \"name\": \"alwaysFullscreen\",\n          \"type\": \"boolean\",\n          \"label\": \"Cover entire background image\",\n          \"importance\": \"low\",\n          \"description\": \"When the user clicks the hotspot the popup will cover the entire background image\"\n        },\n        {\n          \"name\": \"header\",\n          \"type\": \"text\",\n          \"label\": \"Header\",\n          \"importance\": \"low\",\n          \"description\": \"Optional header for the popup\",\n          \"optional\": true\n        },\n        {\n          \"name\": \"content\",\n          \"type\": \"list\",\n          \"label\": \"Popup content\",\n          \"importance\": \"medium\",\n          \"field\": {\n            \"name\": \"action\",\n            \"type\": \"library\",\n            \"label\": \"Content Item\",\n            \"options\": [\n              \"H5P.Text 1.1\",\n              \"H5P.Video 1.5\",\n              \"H5P.Image 1.1\"\n            ]\n          }\n        }\n      ]\n    }\n  },\n  {\n    \"name\": \"hotspotNumberLabel\",\n    \"type\": \"text\",\n    \"label\": \"Hotspot label for assistive technologies\",\n    \"default\": \"Hotspot #num\",\n    \"description\": \"Will help announce what hotspot element has been navigated to if there is no header specified for a hotspot. #num can be used to replace the hotspot number.\",\n    \"common\": true\n  },\n  {\n    \"name\": \"closeButtonLabel\",\n    \"type\": \"text\",\n    \"label\": \"Close button label for assistive technologies\",\n    \"default\": \"Close\",\n    \"common\": true\n  }\n]\n', NULL, 1, 19, NULL, NULL, NULL, 1),
(134, 'H5P.InteractiveBook', 'Interactive Book', 1, 2, 10, 1, 1, 'iframe', 'dist/h5p-interactive-book.js', '', '', '[\n  {\n    \"name\": \"showCoverPage\",\n    \"type\": \"boolean\",\n    \"label\": \"Enable book cover\",\n    \"description\": \"A cover that shows info regarding the book before access\",\n    \"importance\": \"low\",\n    \"default\": false\n  },\n  {\n    \"name\": \"bookCover\",\n    \"type\": \"group\",\n    \"label\": \"Cover Page\",\n    \"importance\": \"medium\",\n    \"widget\": \"showWhen\",\n    \"showWhen\": {\n      \"rules\": [\n        {\n          \"field\": \"showCoverPage\",\n          \"equals\": true\n        }\n      ]\n    },\n    \"fields\": [\n      {\n        \"name\": \"coverDescription\",\n        \"type\": \"text\",\n        \"widget\": \"html\",\n        \"label\": \"Cover description\",\n        \"importance\": \"medium\",\n        \"optional\": true,\n        \"description\": \"This text will be the description of your book.\",\n        \"enterMode\": \"p\",\n        \"tags\": [\n          \"sub\",\n          \"sup\",\n          \"strong\",\n          \"em\",\n          \"p\",\n          \"code\"\n        ]\n      },\n      {\n        \"name\": \"coverImage\",\n        \"type\": \"image\",\n        \"label\": \"Cover image\",\n        \"importance\": \"low\",\n        \"optional\": true,\n        \"description\": \"An optional background image for the introduction.\"\n      },\n      {\n        \"name\": \"coverAltText\",\n        \"type\": \"text\",\n        \"label\": \"Cover image alternative text\",\n        \"importance\": \"low\",\n        \"optional\": true,\n        \"description\": \"An alternative text for the cover image\"\n      }\n    ]\n  },\n  {\n    \"name\": \"chapters\",\n    \"type\": \"list\",\n    \"label\": \"Pages\",\n    \"entity\": \"Page\",\n    \"widgets\": [\n      {\n        \"name\": \"VerticalTabs\",\n        \"label\": \"Default\"\n      }\n    ],\n    \"importance\": \"high\",\n    \"min\": 1,\n    \"max\": 50,\n    \"field\": {\n      \"name\": \"item\",\n      \"type\": \"group\",\n      \"label\": \"Item\",\n      \"importance\": \"low\",\n      \"expanded\": true,\n      \"fields\": [\n        {\n          \"label\": \"Page\",\n          \"name\": \"chapter\",\n          \"type\": \"library\",\n          \"options\": [\n            \"H5P.Column 1.12\"\n          ]\n        }\n      ]\n    }\n  },\n  {\n    \"name\": \"behaviour\",\n    \"type\": \"group\",\n    \"importance\": \"low\",\n    \"label\": \"Behavioural settings\",\n    \"fields\": [\n      {\n        \"name\": \"defaultTableOfContents\",\n        \"type\": \"boolean\",\n        \"label\": \"Display table of contents as default\",\n        \"description\": \"When enabled the table of contents is showed when opening the book\",\n        \"default\": true\n      },\n      {\n        \"name\": \"progressIndicators\",\n        \"type\": \"boolean\",\n        \"label\": \"Display Progress Indicators\",\n        \"description\": \"When enabled there will be indicators per page showing the user if he is done with the page or not.\",\n        \"default\": true\n      },\n      {\n        \"name\": \"progressAuto\",\n        \"type\": \"boolean\",\n        \"label\": \"Enable automatic progress\",\n        \"description\": \"If enabled a page without tasks is considered done when viewed. A page with tasks when all tasks are done. If disabled there will be a button at the bottom of every page for the user to click when done with the page.\",\n        \"default\": true,\n        \"widget\": \"showWhen\",\n        \"showWhen\": {\n          \"rules\": [\n            {\n              \"field\": \"progressIndicators\",\n              \"equals\": true\n            }\n          ]\n        }\n      },\n      {\n        \"name\": \"displaySummary\",\n        \"type\": \"boolean\",\n        \"label\": \"Display summary\",\n        \"description\": \"When enabled the user can see a summary and submit the progress/answers\",\n        \"default\": true\n      }\n    ]\n  },\n  {\n    \"name\": \"read\",\n    \"type\": \"text\",\n    \"label\": \"Translation for \\\"Read\\\"\",\n    \"importance\": \"low\",\n    \"default\": \"Read\",\n    \"common\": true,\n    \"optional\": true\n  },\n  {\n    \"name\": \"displayTOC\",\n    \"type\": \"text\",\n    \"label\": \"Translation for \\\"Display \'Table of contents\'\\\"\",\n    \"importance\": \"low\",\n    \"default\": \"Display \'Table of contents\'\",\n    \"common\": true,\n    \"optional\": true\n  },\n  {\n    \"name\": \"hideTOC\",\n    \"type\": \"text\",\n    \"label\": \"Translation for \\\"Hide \'Table of contents\'\\\"\",\n    \"importance\": \"low\",\n    \"default\": \"Hide \'Table of contents\'\",\n    \"common\": true,\n    \"optional\": true\n  },\n  {\n    \"name\": \"nextPage\",\n    \"type\": \"text\",\n    \"label\": \"Translation for \\\"Next page\\\"\",\n    \"importance\": \"low\",\n    \"default\": \"Next page\",\n    \"common\": true,\n    \"optional\": true\n  },\n  {\n    \"name\": \"previousPage\",\n    \"type\": \"text\",\n    \"label\": \"Translation for \\\"Previous page\\\"\",\n    \"importance\": \"low\",\n    \"default\": \"Previous page\",\n    \"common\": true,\n    \"optional\": true\n  },\n  {\n    \"name\": \"chapterCompleted\",\n    \"type\": \"text\",\n    \"label\": \"Translation for \\\"Page completed!\\\"\",\n    \"importance\": \"low\",\n    \"default\": \"Page completed!\",\n    \"common\": true,\n    \"optional\": true\n  },\n  {\n    \"name\": \"partCompleted\",\n    \"type\": \"text\",\n    \"label\": \"Translation for \\\"@pages of @total completed\\\" (@pages and @total will be replaced by actual values)\",\n    \"importance\": \"low\",\n    \"default\": \"@pages of @total completed\",\n    \"common\": true,\n    \"optional\": true\n  },\n  {\n    \"name\": \"incompleteChapter\",\n    \"type\": \"text\",\n    \"label\": \"Translation for \\\"Incomplete page\\\"\",\n    \"importance\": \"low\",\n    \"default\": \"Incomplete page\",\n    \"common\": true,\n    \"optional\": true\n  },\n  {\n    \"name\": \"navigateToTop\",\n    \"type\": \"text\",\n    \"label\": \"Translation for \\\"Navigate to the top\\\"\",\n    \"importance\": \"low\",\n    \"default\": \"Navigate to the top\",\n    \"common\": true,\n    \"optional\": true\n  },\n  {\n    \"name\": \"markAsFinished\",\n    \"type\": \"text\",\n    \"importance\": \"low\",\n    \"label\": \"Translation for \\\"I have finished this page\\\"\",\n    \"default\": \"I have finished this page\",\n    \"common\": true,\n    \"optional\": true\n  },\n  {\n    \"name\": \"fullscreen\",\n    \"type\": \"text\",\n    \"importance\": \"low\",\n    \"label\": \"Fullscreen button label\",\n    \"default\": \"Fullscreen\",\n    \"common\": true,\n    \"optional\": true\n  },\n  {\n    \"name\": \"exitFullscreen\",\n    \"type\": \"text\",\n    \"importance\": \"low\",\n    \"label\": \"Exit fullscreen button label\",\n    \"default\": \"Exit fullscreen\",\n    \"common\": true,\n    \"optional\": true\n  },\n  {\n    \"name\": \"bookProgressSubtext\",\n    \"type\": \"text\",\n    \"importance\": \"low\",\n    \"label\": \"Page progress in book\",\n    \"description\": \"\\\"@count\\\" will be replaced by page count, and \\\"@total\\\" with the total number of pages\",\n    \"default\": \"@count of @total pages\",\n    \"common\": true,\n    \"optional\": true\n  },\n  {\n    \"name\": \"interactionsProgressSubtext\",\n    \"type\": \"text\",\n    \"importance\": \"low\",\n    \"label\": \"Interaction progress\",\n    \"description\": \"\\\"@count\\\" will be replaced by page count, and \\\"@total\\\" with the total number of pages\",\n    \"default\": \"@count of @total interactions\",\n    \"common\": true,\n    \"optional\": true\n  },\n  {\n    \"name\": \"submitReport\",\n    \"type\": \"text\",\n    \"importance\": \"low\",\n    \"label\": \"Translation for \\\"Submit report\\\"\",\n    \"default\": \"Submit Report\",\n    \"common\": true,\n    \"optional\": true\n  },\n  {\n    \"name\": \"restartLabel\",\n    \"type\": \"text\",\n    \"importance\": \"low\",\n    \"label\": \"Label for \\\"restart\\\" button\",\n    \"default\": \"Restart\",\n    \"common\": true,\n    \"optional\": true\n  },\n  {\n    \"name\": \"summaryHeader\",\n    \"type\": \"text\",\n    \"importance\": \"low\",\n    \"label\": \"Summary header\",\n    \"default\": \"Summary\",\n    \"common\": true,\n    \"optional\": true\n  },\n  {\n    \"name\": \"allInteractions\",\n    \"type\": \"text\",\n    \"importance\": \"low\",\n    \"label\": \"Translation for \\\"All interactions\\\"\",\n    \"default\": \"All interactions\",\n    \"common\": true,\n    \"optional\": true\n  },\n  {\n    \"name\": \"unansweredInteractions\",\n    \"type\": \"text\",\n    \"importance\": \"low\",\n    \"label\": \"Translation for \\\"Unanswered interactions\\\"\",\n    \"default\": \"Unanswered interactions\",\n    \"common\": true,\n    \"optional\": true\n  },\n  {\n    \"name\": \"scoreText\",\n    \"type\": \"text\",\n    \"importance\": \"low\",\n    \"label\": \"Score\",\n    \"description\": \"\\\"@score\\\" will be replaced with current score, and \\\"@maxscore\\\" will be replaced with max achievable score\",\n    \"default\": \"@score / @maxscore\",\n    \"common\": true,\n    \"optional\": true\n  },\n  {\n    \"name\": \"leftOutOfTotalCompleted\",\n    \"type\": \"text\",\n    \"importance\": \"low\",\n    \"label\": \"Per page interactions completion\",\n    \"description\": \"\\\"@left\\\" will be replaced with remaining interactions, and \\\"@max\\\" will be replaced with total number of interactions on the page\",\n    \"default\": \"@left of @max interactions completed\",\n    \"common\": true,\n    \"optional\": true\n  },\n  {\n    \"name\": \"noInteractions\",\n    \"type\": \"text\",\n    \"importance\": \"low\",\n    \"label\": \"Translation for \\\"No interactions\\\"\",\n    \"default\": \"No interactions\",\n    \"common\": true,\n    \"optional\": true\n  },\n  {\n    \"name\": \"score\",\n    \"type\": \"text\",\n    \"importance\": \"low\",\n    \"label\": \"Translation for \\\"Score\\\"\",\n    \"default\": \"Score\",\n    \"common\": true,\n    \"optional\": true\n  },\n  {\n    \"name\": \"summaryAndSubmit\",\n    \"type\": \"text\",\n    \"importance\": \"low\",\n    \"label\": \"Label for \\\"Summary & submit\\\" button\",\n    \"default\": \"Summary & submit\",\n    \"common\": true,\n    \"optional\": true\n  },\n  {\n    \"name\": \"noChapterInteractionBoldText\",\n    \"type\": \"text\",\n    \"importance\": \"low\",\n    \"label\": \"Translation for \\\"You have not interacted with any pages.\\\"\",\n    \"default\": \"You have not interacted with any pages.\",\n    \"common\": true,\n    \"optional\": true\n  },\n  {\n    \"name\": \"noChapterInteractionText\",\n    \"type\": \"text\",\n    \"importance\": \"low\",\n    \"label\": \"Translation for \\\"You have to interact with at least one page before you can see the summary.\\\"\",\n    \"default\": \"You have to interact with at least one page before you can see the summary.\",\n    \"common\": true,\n    \"optional\": true\n  },\n  {\n    \"name\": \"yourAnswersAreSubmittedForReview\",\n    \"type\": \"text\",\n    \"importance\": \"low\",\n    \"label\": \"Translation for \\\"Your answers are submitted for review!\\\"\",\n    \"default\": \"Your answers are submitted for review!\",\n    \"common\": true,\n    \"optional\": true\n  },\n  {\n    \"name\": \"bookProgress\",\n    \"type\": \"text\",\n    \"importance\": \"low\",\n    \"label\": \"Summary progress label\",\n    \"default\": \"Book progress\",\n    \"common\": true,\n    \"optional\": true\n  },\n  {\n    \"name\": \"interactionsProgress\",\n    \"type\": \"text\",\n    \"importance\": \"low\",\n    \"label\": \"Interactions progress label\",\n    \"default\": \"Interactions progress\",\n    \"common\": true,\n    \"optional\": true\n  },\n  {\n    \"name\": \"totalScoreLabel\",\n    \"type\": \"text\",\n    \"importance\": \"low\",\n    \"label\": \"Total score label\",\n    \"default\": \"Total score\",\n    \"common\": true,\n    \"optional\": true\n  },\n  {\n    \"name\": \"a11y\",\n    \"type\": \"group\",\n    \"label\": \"Accessibility texts\",\n    \"common\": true,\n    \"fields\": [\n      {\n        \"name\": \"progress\",\n        \"type\": \"text\",\n        \"label\": \"Page progress textual alternative\",\n        \"description\": \"An alternative text for the visual page progress. @page and @total variables available.\",\n        \"default\": \"Page @page of @total.\"\n      },\n      {\n        \"name\": \"menu\",\n        \"type\": \"text\",\n        \"label\": \"Label for expanding/collapsing navigation menu\",\n        \"default\": \"Toggle navigation menu\"\n      }\n    ]\n  }\n]', NULL, NULL, NULL, NULL, NULL, NULL, 1),
(135, 'H5P.GoToScene', 'Go To Scene', 0, 1, 0, 0, 0, '', 'scripts/go-to-scene.js', '', '', '[\n  {\n    \"name\": \"nextSceneId\",\n    \"type\": \"number\",\n    \"label\": \"Go to scene with ID\",\n    \"importance\": \"high\",\n    \"description\": \"ID of the scene that we will jump to\"\n  }\n]', NULL, NULL, NULL, NULL, NULL, NULL, 1),
(136, 'H5P.ThreeImage', 'Virtual Tour (360)', 0, 5, 8, 1, 1, 'iframe', 'dist/h5p-three-image.js', 'dist/h5p-three-image.css', '', '[\n  {\n    \"name\": \"threeImage\",\n    \"type\": \"group\",\n    \"widget\": \"threeImage\",\n    \"label\": \"Three Image Editor\",\n    \"importance\": \"high\",\n    \"fields\": [\n      {\n        \"name\": \"scenes\",\n        \"type\": \"list\",\n        \"label\": \"Scenes\",\n        \"entity\": \"Scene\",\n        \"min\": 0,\n        \"field\": {\n          \"name\": \"scene\",\n          \"type\": \"group\",\n          \"fields\": [\n            {\n              \"name\": \"sceneType\",\n              \"type\": \"select\",\n              \"label\": \"Scene type\",\n              \"widget\": \"radioGroup\",\n              \"alignment\": \"horizontal\",\n              \"options\": [\n                {\n                  \"value\": \"360\",\n                  \"label\": \"360 image\"\n                },\n                {\n                  \"value\": \"static\",\n                  \"label\": \"Static image\"\n                }\n              ],\n              \"default\": \"360\"\n            },\n            {\n              \"name\": \"showBackButton\",\n              \"type\": \"boolean\",\n              \"label\": \"Display \\\"Back\\\" button\",\n              \"description\": \"Display button for navigating back to your previous scene\",\n              \"default\": true,\n              \"widget\": \"showWhen\",\n              \"showWhen\": {\n                \"rules\": [\n                  {\n                    \"field\": \"sceneType\",\n                    \"equals\": \"static\"\n                  }\n                ]\n              }\n            },\n            {\n              \"name\": \"sceneId\",\n              \"type\": \"number\"\n            },\n            {\n              \"name\": \"scenename\",\n              \"type\": \"text\",\n              \"label\": \"Scene Title\",\n              \"description\": \"Used to identify the scene\"\n            },\n            {\n              \"name\": \"scenesrc\",\n              \"type\": \"image\",\n              \"label\": \"Scene Background\"\n            },\n            {\n              \"name\": \"scenedescription\",\n              \"type\": \"text\",\n              \"widget\": \"html\",\n              \"label\": \"Scene Description\",\n              \"description\": \"A text that can describe the scene for the end-user\",\n              \"optional\": true,\n              \"tags\": [\n                \"p\",\n                \"br\",\n                \"strong\",\n                \"em\",\n                \"code\"\n              ]\n            },\n            {\n              \"name\": \"cameraStartPosition\",\n              \"type\": \"text\"\n            },\n            {\n              \"name\": \"interactions\",\n              \"type\": \"list\",\n              \"min\": 0,\n              \"field\": {\n                \"name\": \"interaction\",\n                \"type\": \"group\",\n                \"fields\": [\n                  {\n                    \"name\": \"labelText\",\n                    \"type\": \"text\",\n                    \"label\": \"Label\",\n                    \"optional\": true,\n                    \"description\": \"If left blank no label will be displayed and we\'ll try to use the title field for screen readers\"\n                  },\n                  {\n                    \"name\": \"label\",\n                    \"type\": \"group\",\n                    \"label\": \"Label Settings\",\n                    \"importance\": \"low\",\n                    \"fields\": [\n                      {\n                        \"name\": \"labelPosition\",\n                        \"type\": \"select\",\n                        \"label\": \"Label position\",\n                        \"description\": \"Choose where the label should appear\",\n                        \"options\": [\n                          {\n                            \"value\": \"inherit\",\n                            \"label\": \"Use behavioral setting\"\n                          },\n                          {\n                            \"value\": \"right\",\n                            \"label\": \"Right aligned\"\n                          },\n                          {\n                            \"value\": \"left\",\n                            \"label\": \"Left aligned\"\n                          },\n                          {\n                            \"value\": \"top\",\n                            \"label\": \"Top aligned\"\n                          },\n                          {\n                            \"value\": \"bottom\",\n                            \"label\": \"Bottom aligned\"\n                          }\n                        ],\n                        \"default\": \"inherit\"\n                      },\n                      {\n                        \"name\": \"showLabel\",\n                        \"type\": \"select\",\n                        \"label\": \"Display Label\",\n                        \"description\": \"If hidden - labels will show only on mouse over\",\n                        \"options\": [\n                          {\n                            \"value\": \"inherit\",\n                            \"label\": \"Use behavioral setting\"\n                          },\n                          {\n                            \"value\": \"show\",\n                            \"label\": \"Show\"\n                          },\n                          {\n                            \"value\": \"hide\",\n                            \"label\": \"Hide\"\n                          }\n                        ],\n                        \"default\": \"inherit\"\n                      }\n                    ]\n                  },\n                  {\n                    \"name\": \"action\",\n                    \"type\": \"library\",\n                    \"options\": [\n                      \"H5P.GoToScene 0.1\",\n                      \"H5P.AdvancedText 1.1\",\n                      \"H5P.Image 1.1\",\n                      \"H5P.Audio 1.5\",\n                      \"H5P.Video 1.6\",\n                      \"H5P.Summary 1.10\",\n                      \"H5P.SingleChoiceSet 1.11\"\n                    ]\n                  },\n                  {\n                    \"name\": \"interactionpos\",\n                    \"type\": \"text\"\n                  }\n                ]\n              }\n            },\n            {\n              \"name\": \"iconType\",\n              \"type\": \"select\",\n              \"label\": \"Button style\",\n              \"description\": \"Decide how buttons pointing to this scene should look. For scenes that are static and does not lead to new scenes, we recommend the \\\"More information\\\" button.\",\n              \"widget\": \"radioGroup\",\n              \"alignment\": \"horizontal\",\n              \"options\": [\n                {\n                  \"value\": \"arrow\",\n                  \"label\": \"New scene (arrow)\"\n                },\n                {\n                  \"value\": \"plus\",\n                  \"label\": \"More information (plus)\"\n                }\n              ],\n              \"default\": \"arrow\"\n            },\n            {\n              \"name\": \"audio\",\n              \"type\": \"audio\",\n              \"label\": \"Audio Track\",\n              \"description\": \"Add an audio track that\'s specific for this scene.\",\n              \"optional\": true,\n              \"widgetExtensions\": [\n                \"AudioRecorder\"\n              ]\n            }\n          ]\n        }\n      },\n      {\n        \"name\": \"startSceneId\",\n        \"type\": \"number\",\n        \"default\": 0\n      },\n      {\n        \"name\": \"audio\",\n        \"type\": \"audio\",\n        \"label\": \"Audio track\",\n        \"optional\": true\n      }\n    ]\n  },\n  {\n    \"name\": \"behaviour\",\n    \"type\": \"group\",\n    \"label\": \"Behavioral settings\",\n    \"importance\": \"low\",\n    \"description\": \"These options will let you control how the world behaves.\",\n    \"fields\": [\n      {\n        \"name\": \"audio\",\n        \"type\": \"audio\",\n        \"label\": \"Global Audio\",\n        \"description\": \"Add an audio track that\'s available for all of the scenes by default.\",\n        \"optional\": true,\n        \"widgetExtensions\": [\n          \"AudioRecorder\"\n        ]\n      },\n      {\n        \"name\": \"sceneRenderingQuality\",\n        \"type\": \"select\",\n        \"label\": \"Scene rendering quality\",\n        \"description\": \"Choose the amount of width and height segments used to render a scene. This directly affects the quality level of the scene, try increasing the quality if a scene looks \\\"blocky\\\" or \\\"waves\\\" are seen within the scenes. Note that higher quality rendering takes more time to load.\",\n        \"options\": [\n          {\n            \"value\": \"high\",\n            \"label\": \"High Quality (128x128)\"\n          },\n          {\n            \"value\": \"medium\",\n            \"label\": \"Medium Quality (64x64)\"\n          },\n          {\n            \"value\": \"low\",\n            \"label\": \"Low Quality (16x16)\"\n          }\n        ],\n        \"default\": \"high\"\n      },\n      {\n        \"name\": \"label\",\n        \"type\": \"group\",\n        \"label\": \"Label settings\",\n        \"importance\": \"low\",\n        \"expanded\": true,\n        \"fields\": [\n          {\n            \"name\": \"labelPosition\",\n            \"type\": \"select\",\n            \"label\": \"Label position\",\n            \"description\": \"The default label position. The position may be overriden per interaction\",\n            \"options\": [\n              {\n                \"value\": \"right\",\n                \"label\": \"Right aligned\"\n              },\n              {\n                \"value\": \"left\",\n                \"label\": \"Left aligned\"\n              },\n              {\n                \"value\": \"top\",\n                \"label\": \"Top aligned\"\n              },\n              {\n                \"value\": \"bottom\",\n                \"label\": \"Bottom aligned\"\n              }\n            ],\n            \"default\": \"right\"\n          },\n          {\n            \"name\": \"showLabel\",\n            \"type\": \"boolean\",\n            \"label\": \"Display Labels\",\n            \"description\": \"If unchecked - labels will show only on mouse over\",\n            \"default\": true\n          }\n        ]\n      }\n    ]\n  },\n  {\n    \"name\": \"l10n\",\n    \"type\": \"group\",\n    \"common\": true,\n    \"label\": \"Localize\",\n    \"fields\": [\n      {\n        \"name\": \"title\",\n        \"type\": \"text\",\n        \"label\": \"Aria label for content type\",\n        \"default\": \"Virtual Tour\"\n      },\n      {\n        \"name\": \"playAudioTrack\",\n        \"type\": \"text\",\n        \"label\": \"Label for to play audio\",\n        \"default\": \"Play Audio Track\"\n      },\n      {\n        \"name\": \"pauseAudioTrack\",\n        \"type\": \"text\",\n        \"label\": \"Label to pause audio\",\n        \"default\": \"Pause Audio Track\"\n      },\n      {\n        \"name\": \"sceneDescription\",\n        \"type\": \"text\",\n        \"label\": \"Title to scene dialog\",\n        \"default\": \"Scene Description\"\n      },\n      {\n        \"name\": \"resetCamera\",\n        \"type\": \"text\",\n        \"label\": \"Label for button to reset camera\",\n        \"default\": \"Reset Camera\"\n      },\n      {\n        \"name\": \"submitDialog\",\n        \"type\": \"text\",\n        \"label\": \"Label for the submit dialog button\",\n        \"default\": \"Submit Dialog\"\n      },\n      {\n        \"name\": \"closeDialog\",\n        \"type\": \"text\",\n        \"label\": \"Label for the close dialog button\",\n        \"default\": \"Close Dialog\"\n      },\n      {\n        \"name\": \"expandButtonAriaLabel\",\n        \"type\": \"text\",\n        \"label\": \"Aria label for the expand label button\",\n        \"default\": \"Expand the visual label\"\n      },\n      {\n        \"name\": \"backgroundLoading\",\n        \"type\": \"text\",\n        \"label\": \"Label for when background image is loading in 360 scene\",\n        \"default\": \"Loading background image...\"\n      },\n      {\n        \"name\": \"noContent\",\n        \"type\": \"text\",\n        \"label\": \"Label for when there is no content\",\n        \"default\": \"No content\"\n      }\n    ]\n  }\n]', NULL, 1, 20, NULL, NULL, NULL, 1),
(137, 'H5P.ThreeJS', 'three.js', 1, 0, 107, 0, 0, '', 'dist/three.min.js', '', '', '', NULL, 1, 12, NULL, NULL, NULL, 1),
(138, 'H5P.ThreeSixty', 'Three Sixty', 0, 3, 7, 0, 0, '', 'scripts/three-sixty.js', 'styles/three-sixty.css', '', '', NULL, 1, 12, NULL, NULL, NULL, 1),
(139, 'H5PEditor.ThreeImage', 'Three Image Editor', 0, 5, 2, 0, 0, '', 'dist/h5p-editor-three-image.js', '', '', '', NULL, NULL, NULL, NULL, NULL, NULL, 1);
